INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11561078956', 'Conjunto de 6 Xícaras Grandes 220ml Com Pires Ryo Blue Bay', 'A Oxford foi buscar inspiração em Blue Bay, cidade costeira localizada em Nova Gales do Sul, Austrália, para criar os tons dessa coleção. As peças trazem a beleza das praias dessa região, numa mistura entre a areia de tons claros e a cor azul refletida do oceano. O pontilhismo da decoração é fruto de um processo manual, o que garante desenhos exclusivos em cada peça. Conteúdo da embalagem: 6 xícaras para chá com 220ml de capacidade / 6 pires para chá com 16cm de diâmetro - Garantia: 3 Meses para Defeitos de fabricação - Uso: Resistente a micro-ondas e lava-louças - Tipo da embalagem: Papelão pardo - Tipo: Xícara - Material: Porcelana - Cor: Azul - Formato: Outros - Utilizações seguras: Micro-ondas e lava-louças - Tipo do jogo: Xícara - Capacidade em volume: 220ml', 252.89, 252.89, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/e237fef8463501eea09b1fb51b67a8f5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F548911108%2F11561078956', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
