INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11685803134', 'Mangá - Jujutsu Kaisen - Batalha de Feiticeiros - 05', 'Jujutsu Kaisen - Batalha de Feiticeiros - 05Tem início o Intercâmbio da Escola Irmã de Kyoto. O primeiro dia do torneio em equipe terá como vencedor o grupo que exorcizar primeiro uma maldição de nível 2, mas o briguento Todou ataca de surpresa o grupo da Escola de Tokyo, e Itadori recebe a tarefa de enfrentá-lo. O que ele não esperava é que o restante da equipe da Escola de Kyoto apareceria para se juntar ao confronto!!Periodicidade: BimestralFormato: 13.7X20 cmTipo de Distribuição: NacionalTipo de Produto: RevistaSegmentos: MangásMarcas: Planet MangaAutor(es): Gege AkutamiISBN: 9786559600205Check-List: Dezembro/2021Classificação Etária: 16 anosEditora: Editora PaniniNúmero de páginas: 192Lombada/Encadernação: QUADRADATipo de capa: CartãoData de Lançamento: 16/04/2021Idioma: Português', 47.9, 47.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/6fd2b590902259eca48a169a8eaec2a9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F11685803134', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53056882441', 'Mangá - Jojo''s Bizarre Adventure - Parte 7 - Steel Ball Run 11 - Novo/Lacrado', 'Jojo''s Bizarre Adventure - Parte 7 - Steel Ball Run 11 A batalha contra Axl RO, um assassino enviado pelo presidente, traz um resultado inesperado para Gyro e Johnny: as partes do cadáver que eles possuíam acabaram sendo roubadas! A oitava etapa da corrida começa com os dois em uma situação difícil na disputa pelo cadáver. Gyro se lembra de que ainda resta outro portador das partes entre os participantes. Enquanto isso, Wekapipo age para proteger Lucy, porém... Tipo de Produto: Revista Segmentos: Mangás Marcas: Planet Manga Autor(es): Hirohiko Araki ISBN: 9786525954301 Check-List: Março/2026 Classificação Etária: 16 anos Editora: Panini Gênero: Ação, Aventura Demografia: Shonen Número de páginas: 256 Tipo de capa: Capa Cartão Data de Lançamento: 21/03/2026 Idioma: Português Condição: Novo/Lacrado', 61.9, 61.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-8261d-mlic3lc3hd6w06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F53056882441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
