INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200015648', 'Escolinha | Caligrafia - Letra de Forma e Cursiva | Capa Brochura', 'Esta obra propicia o aprendizado correto das letras do Alfabeto e da escrita por meio de exercícios de coordenação motora e de atividades que estimulam a imaginação da criança, de forma criativa e divertida. Páginas: 98 Dimensões: 20x27cm', 24.9, 24.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8258d-mg89x26piccpbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F58200015648', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599029585', 'Gibi é Diversão | Festa no Céu', 'Leia a história do sapo que se juntou aos animais voadores para uma festa no céu. 13x20cm 16 Páginas', 7.99, 3.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8258j-mfsguxoit4wab0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22599029585', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17582831853', 'Livro Casal Imperfeito | Fernanda Witwytzky', 'Retratos de um casamento aperfeiçoado no Senhor. Sorrisos largos, filhos lindos, viagens empolgantes, refeições cuidadosamente planejadas — um cenário mais alegre que o outro. É assim que muitos casais se apresentam nas redes sociais. Fernanda Witwytzky e Rafael Carrilho também parecem ser um casal assim, daqueles que “perfeição” parece ser uma palavra adequada para descrever o que se vê, porém, eles são imperfeitos. Pior, o casamento deles é imperfeito. Quer uma boa notícia? É que esse livro mostra que um casal imperfeito pode ser muito mais do que feliz: ele pode ser uma bênção, capaz de aperfeiçoar cada pessoa do relacionamento e até o mundo à sua volta. Em seu novo livro, Fernanda Witwytzky, ao lado de seu marido, Rafael Carrilho, fala sobre os desafios reais e a dinâmica (imperfeita) que há nos relacionamentos sob uma perspectiva cristã, e oferece um guia prático sobre como usar essas imperfeições em favor do casamento. “Casal imperfeito”, de Fernanda Witwytzky parte da sua experiência no casamento para discutir os meandros do relacionamento a dois. Dentro de sete capítulos, ela propõe passos práticos e ferramentas preciosas para o casal chegar a um lugar de entendimento, comunicação e conexão. Capítulos:• Um Novo Lar.• Entre Quatro Paredes.• Incompatibilidade é uma Oportunidade.• Um Time de Três.• Lado a Lado.• A Chegada dos Filhos.• O Trabalho Árduo Casal Imperfeito, também conta com seções escritas por Rafael Carrilho, esposo de Fernanda, em que ele conta seus desafios — e aprendizados — na esfera dos relacionamentos, oferecendo uma perspectiva masculina das temáticas abordadas. Ao fim de cada capítulo, o leitor encontrará, ainda, perguntas para se aprofundar e colocar em prática o que foi aprendido. Dessa forma, aprenderá que casais cristãos, pela graça de Deus, podem se fortalecer mesmo com suas fraquezas, pois, como diz a autora, “é em meio a imperfeições, louças sujas, conversas longas, noites sem sexo e fraldas sujas que encontramos a beleza de um casamento fundamentado no Senhor.” 240 Páginas 14x21cm', 35.9, 35.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/364db497561f38cf7212a6e5cd3b1f72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F17582831853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44128771569', 'Herbert West: Reanimator e outros contos | H. P. Lovecraft', 'Herbert West acredita que o corpo humano não é senão uma máquina orgânica e, portanto, deve haver uma maneira de reiniciá-lo quando ele falecer. Como ele era um estudante de medicina na Universidade Miskatonic, aliou-se ao narrador da história, outro colega estudante de medicina, para fazer experimentos secretos que tornassem possível a reanimação de uma pessoa morta... Que resultado dará tudo isso? Este e mais treze contos de terror estão neste livro considerado por muitos estudiosos uma das melhores reuniões do trabalho de Lovecraft. 160 páginas 22,6x15,5 cm', 18.9, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8262v-mkon04u142rp98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F44128771569', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18597217182', 'No vale da sombra da morte | Harold Walker', 'No Vale da Sombra da Morte: uma leitura que vai transformar sua perspectiva sobre o sofrimento e vida cristã. Uma pergunta que sempre surge nestas horas é: “Por que um Deus bom permite o sofrimento?” É uma pergunta óbvia e muito lógica, que causa dúvida no coração do cristão. Harold Walker, em uma narrativa emocionante, compartilha sua jornada de desafios e a constante presença de Deus. Nas páginas deste livro, você encontrará relatos autênticos e comoventes do autor, que enfrenta corajosamente a batalha contra o câncer. Em meio a essa luta, ele descobriu uma fé inabalável e a bondade divina, que o acompanha a cada passo. No Vale da Sombra da Morte é uma obra que nos inspira a encontrar esperança e força mesmo nas circunstâncias mais difíceis da vida. É uma poderosa lembrança de que Deus está ao nosso lado, fortalecendo-nos e sustentando-nos em meio às adversidades.', 21.61, 16.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7qvfi-ljx8nbcooz6ae5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F18597217182', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
