INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098455025', 'Smoke Treatment Stp Tratamento Redutor De Fumaça 450ml', 'Bem-vindo(a) à nossa loja! STP Smoke Treatment – Redutor de Fumaça e Desgaste para Motores Descrição do Produto: O STP Smoke Treatment é um aditivo de alta performance desenvolvido para reduzir a emissão de fumaça e proteger o motor do seu veículo. Com fórmula avançada, contém dispersantes, melhoradores de índice de viscosidade, detergentes, agentes antidesgaste e antioxidantes. Forma um revestimento de óleo mais espesso, preenchendo folgas internas e diminuindo a passagem de óleo para a câmara de combustão – o que reduz significativamente a fumaça e o consumo de óleo. Aplicação: Adicione 1 frasco (450 mL) ao óleo lubrificante do motor. Recomendado para uso com até 5 litros de óleo. Compatível com motores a álcool, gasolina, GNV e flex. Benefícios: - Reduz a emissão de fumaça - Diminui o consumo de óleo - Protege contra o desgaste do motor - Ação antioxidante e detergente - Reduz a fricção entre componentes metálicos - Contribui para maior durabilidade e performance do motor • GARANTIA Colocamos à disposição nossa equipe para informar as etapas corretas de entrada no processo de garantia de acordo com as recomendações do fabricante. • 100% Original com nota fiscal. • Recomendamos sempre que toda e qualquer instalação seja realizada por profissionais especializados para evitar problemas futuros, pois não somos responsáveis pela má instalação ou mau uso do produto.', 109.89, 109.89, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rff4-m9a9b8a6x4id6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816129267%2F23098455025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699333200', 'PELÚCIA AVELÃ COM MATATABI PARA GATOS - OIKOS ANIMAL', '"conheça a pelúcia avelã da oikos animal! atrativa e relaxante, possui formato e textura que diverte e distrai seu amigo! além disso, tem matatabi: o graveto mais amado dos felinos! é natural, estimula, distrai e alivia o estresse. o matatabi reduz a ansiedade do seu gato. o brinquedo é de poliéster e matatabi. variação de efeitos: os efeitos do matatabi variam. o animal pode miar, se sentir calmo, lamber, rolar no chão, pular, correr ou se roçar em objetos. imunidade ao efeito: as reações são hereditárias. alguns gatos podem ser imunes ao efeito. indicação: esse produto não é indicado pra crianças ou outros animais. pode ser utilizado por gatos de todos os portes. leve diversão para o seu pet! medidas: largura: 3 cm altura: 5 cm"', 41.9, 34.9, NULL, 'Pets > Pet Accessories > Toys', 'https://cf.shopee.com.br/file/sg-11134201-8262k-mlg9np6ext6o1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F20699333200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
