INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20598293149', 'Pequeno pode tudo', 'O pequeno Pardal, fugindo da polui&ccedil &atilde o e dos perigos da cidade, vai para a floresta. L&aacute , &eacute rejeitado pelas outras aves, que zombam dele. Envergonhado e sentindo-se insignificante, ele resolve se esconder. Encontra um deserto e ali vai plantando, com paci&ecirc ncia e persist&ecirc ncia, sementes de &aacute rvores e flores. Um dia, cai numa arapuca e fica um bom tempo preso numa gaiola. Quando, enfim, consegue se livrar e voltar para o deserto, encontra em seu lugar uma bela floresta. A partir de ent&atilde o o Pardal percebe o seu valor e descobre que &eacute capaz de grandes feitos.', 94.07, 84.67, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-824ij-mehnqv0d3e9s61', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1624754721%2F20598293149', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
