INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297022589', 'Cartão de Memória MicroSd Sandisk 64gb MicroSd Ultra 140Mbs', 'Cartão de Memória Sandisk 64gb Micro Sd Ultra Velocidade até 140MB/s, Ideal para Smartphones, Tablets, Câmeras, Drones, Alta Performance Armazenamento Confiável - No Brasil Performance elevada: O cartão Sandisk Ultra microSDXC UHS-I de 64GB oferece velocidades de leitura de até 140MB/s, proporcionando um desempenho rápido para gravação de vídeos, fotos e transferências de arquivos em seus dispositivos móveis; Gravação Full HD: Com a classificação UHS Speed Class 1 (U1) e Video Speed Class 10 (V10), este cartão é ideal para gravação de vídeos em alta resolução, como Full HD, garantindo imagens nítidas e detalhadas sem perda de quadros; Durabilidade e resistência: O Sandisk Ultra microSDXC é projetado para resistir a condições extremas, como água, temperaturas variadas, impactos e raios-X, tornando-o perfeito para uso em smartphones, tablets, câmeras e drones; Compatibilidade ampla: Funciona com dispositivos compatíveis com cartões microSDXC, como smartphones, tablets, câmeras, drones, entre outros. Verifique a compatibilidade com seu equipamento antes da compra; Classificação de Desempenho A1: A classificação de desempenho A1 significa que este micro sd apresenta uma performance de desempenho superior para a excução de aplicativos em dispositivos compatíveis, a velocidade de transferência de 140mbs facilita a transferência de arquivos para computadores e outros dispositivos compatíveis. Garantia 90 dias', 269.58, 269.58, NULL, 'Mobile & Gadgets > Accessories > Memory Cards', 'https://cf.shopee.com.br/file/sg-11134201-7rbki-llxjt7w2eu34d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078289679%2F22297022589', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
