INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597078507', 'Chumbinho Match Diabolô Cal 5,5 Mm - 250 Unidades - Gamo', 'O Chumbinho Match Diabolô é a escolha ideal para competições e treinamento de tiro esportivo e lazer. Com sua cabeça chata e estrias, proporciona um ótimo agrupamento e excepcional precisão, garantindo resultados superiores em cada disparo. Sua construção é projetada para atender tanto iniciantes quanto atiradores experientes, que buscam qualidade e confiabilidade em seus treinos e competições. Com cada embalagem contendo 250 unidades, o Chumbinho Match Diabolô oferece uma solução prática e econômica para quem leva a sério o tiro esportivo. Invista na qualidade e performance que seus treinos e competições merecem. Ficha Técnica - Modelo: Match Diabolô - Calibre: 5,5 mm - Peso: 1 g - Conteúdo: Embalagem com 250 unidades.', 82.42, 82.42, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rdwo-lxwwi8eu1mzjb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F23597078507', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197480990', 'Palheta Parabrisa Bosch Original Nissan March 2011 A 2018', 'Descrição JOGO DE PALHETA DIANTEIRA AEROFIT ORIGINAL BOSCH 01 - Palheta Bosch lado motorista 21" / 53 CM 01 - Palheta Bosch lado passageiro 14" / 35 CM APLICAÇÃO: - Nissan March - 2011 2012 2013 2014 2015 2016 2017 2018 ENCAIXE : GANCHO Garanta máxima eficiência e segurança em todas as condições de estrada com as palhetas Bosch Aerofit. Produto original Bosch com nota fiscal inclusa. Características: Encaixe Gancho para instalação fácil e segura. Maior durabilidade e eficiência comprovadas. Nova embalagem moderna. Tratamento de grafite para limpeza suave. Estrutura robusta para estabilidade em todas as situações. Recursos Destacados: Tecnologia de ponta e inovação para uso com conexões especiais. Borracha aprimorada com Power Protection Plus, garantindo uma limpeza suave e silenciosa. Lâmina de aço Evodium pré-tensionada, oferecendo uma adaptação perfeita ao para-brisa. Produto novo, com aplicação compatível com peças originais. Construção robusta projetada para um desempenho duradouro, independentemente das condições climáticas. Processo de instalação simples e rápido para sua conveniência. Substituição Recomendada: Observe sinais de problemas no para-brisa e nas palhetas. Dicas de manutenção incluídas para prolongar a vida útil das palhetas. Importante: Substitua as palhetas pelo menos uma vez por ano. Em caso de dúvidas sobre a compatibilidade do seu veículo, pergunte no campo de perguntas do anúncio. Garanta uma visão clara e eficiente em qualquer condição com as Palhetas Bosch Aerofit. Compre já!', 78.97, 77.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rd6q-lujed1r3245td0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337450537%2F22197480990', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497123253', 'Shampoo Soft Mind Spa Blue 250ml Combate Queda Capilar e Oleosidade no Crescimento dos Cabelos', 'SOFT MIND SHAMPOO URBANO SPA BLUE Deseja ter cabelos limpos, equilibrados e saudáveis? O Soft Mind Shampoo Urbano Spa Blue é o produto que você estava procurando! Sua fórmula enriquecida com argila verde e extratos vegetais ajuda a remover o excesso de oleosidade e a regular a oleosidade do couro cabeludo, proporcionando uma limpeza profunda e eficaz. O Urbano Spa Blue é um kit de terapia capilar completo, que ajuda a tratar caspas, queda capilar, calvície e alopecias. Com reposição de queratina, equilíbrio hormonal e metabólico, promove cabelos saudáveis e revitalizados. Experimente o Soft Mind Shampoo Urbano Spa Blue e sinta a diferença desde a primeira lavagem. Seus cabelos ficarão limpos, macios, equilibrados e saudáveis. Adquira já o seu kit de terapia capilar Urbano Spa Blue e desfrute dos benefícios exclusivos que ele oferece para seus cabelos! MODO DE USO Aplique o Soft Mind Shampoo nos cabelos úmidos, massageie intensamente e enxágue. Repita a operação e deixe o produto interagir com os cabelos por 2 minutos, massageando e estimulando a fibra capilar. Enxágue. Se houver necessidade, repita a operação. INFORMAÇÕES IMPORTANTES Não testado em animais. Dermatologicamente testado. Tratamento de calvície, alopecia, queda capilar e outras condições do couro cabeludo. Xampu com ação reguladora da oleosidade.', 123.05, 123.05, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-7rbnb-lnfrrokj47ai8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337450537%2F22497123253', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399683534', 'Pistola de Airsoft VG GK Short V45 Mola 6mm Rossi+BBs+Alvos', 'Pistola de Airsoft VG GK Short V45 Mola 6mm - Rossi + BBs + Alvos Pistola de Airsoft compacta e que cabe na palma da mão! Conheça a Pistola de Airsoft VG GK Short V45 Mola 6mm modelo de entrada para você aproveitar o melhor do esporte! A Rossi está no mercado há mais de 100 anos, durante as últimas décadas, a marca revolucionou o cenário do Tiro Esportivo e do Airsoft, fabricando e importando os melhores equipamentos do mercado. Além disso, a Rossi sempre focou nas necessidades do mercado, e através de sua tecnologia, cria os equipamentos que atendem a todas as demandas de seus clientes. Presente na plataforma GK, essa versão compacta veio para modificar sua experiência no jogo. Ela foi justamente projetada para ser uma arma pequena que cabe no seu bolso, mas não deixa de proporcionar uma partida interessante. É uma modelo que possui um desempenho satisfatório, podendo atingir a velocidade aproximada de 50 FPS, ou seja, são disparos considerados razoavelmente satisfatórios para modelos dessa categoria. Sua construção é extremamente robusta, sendo confeccionada em polímero de alta densidade, proporcionando maior resistência, qualidade e durabilidade. Conta também com magazine com capacidade para até 7 bb’s , proporcionando ainda mais realismo para o equipamento. Essa versão é uma arma spring, ou seja, seu modo de propulsão é através de mola. Armas a mola, possuem grande vantagem em comparação a outros modelos, pois necessitam de menos manutenção e você não precisar gastar a mais com gás para inserir em sua arma. Seu modo de disparo é através de repetição manual, com engatilhamento por ação manual por ferrolho, proporcionando ainda mais praticidade ao utilizar sua pistola para treinos e tiros ao alvo. Para melhorar a visada, essa versão possui alça e massa de mira fixas, ajudando o operador a verificar alvos a distâncias maiores, com total dinamismo e eficiência. Demais né? Possui cano interno com diâmetro de 6,08mm que ajuda na precisão dos disparos, permitindo menor passagem de ar entre as bb’s, o que ajuda a impulsionar a munição para tiros mais fortes e precisos. Aproveite as vantagens e benefícios proporcionados pela Pistola de Airsoft VG GK Short V45 Mola 6mm da Rossi, que você encontra no melhor custo benefício, na melhor loja da carabina do Brasil, o Mundo da Carabina. Ficha Técnica: - Marca: Rossi - Modelo: GK Short V45 - Calibre: 6mm - Modo de Ação: Spring (Mola) - Velocidade: 50 FPS - Alça e Massa de Mira: Sim - Material: Polímero - Modo de Disparo: Repetição Manual - Capacidade do Magazine: 7 BBs - Peso: 53g - Comprimento: 132mm Itens Inclusos: 1x Pistola de Airsoft VG GK Short V45 Mola 6mm - Rossi 1x Magazine para 7 bbs 1x Manual de Instruções 1x Munição BBs 1x Alvos ATENÇÃO: Nos combos que acompanham capa, esta não comporta a luneta acoplada à carabina, somente desmontadas.', 102.54, 102.54, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7rd4u-m70rwq327chn6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1078949207%2F18399683534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25396844345', 'Parachoque Traseiro Voyage 87 88 89 90 91 92 93 94 95 96 Preto', 'Código do produto: 9090 É um item indispensável para manter o design, originalidade e segurança de seu veículo. Possui material resistente, composto em plástico da mais alta qualidade, texturizado e acabamento impecável sem falar no padrão de fabricação igual aos originais que mantem um alinhamento perfeito em seu veículo. Compatível com: Volkswagen - Voyage 1987 - Voyage 1988 - Voyage 1989 - Voyage 1990 - Voyage 1991 - Voyage 1992 - Voyage 1993 - Voyage 1994 - Voyage 1995 - Voyage 1996 Especificações Técnicas - Parachoque traseiro - Texturizado - Material em Plástico ATENÇÃO O valor anunciado referente a Unidade mais o frete por conta do comprador. A empresa não se responsabiliza pela má instalação do produto. Procure por um profissional especializado!', 461.87, 461.87, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/sg-11134201-824h9-mebj9e4rr5kx77', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F469347212%2F25396844345', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598321139', 'Creme Dental Sensodyne Branqueador Extra Fresh 50g', 'Sensodyne Branqueador Extra Fresh ajuda na remoção de manchas com ação branqueadora, controlando e prevenindo a sensibilidade nos dentes, gerando uma proteção que aumenta a cada escovação. Por que Sensodyne Branqueador Extra Fresh? Possui tecnologia com ação branqueadora de baixa abrasividade, auxiliando também para o alívio da dor de dente causada pela sensibilidade. Sabor Refrescante: Possui um sabor refrescante de menta proporcionando um hálito fresco. Ação Branqueadora de baixa abrasividade desenvolvida para dentes sensíveis. Regime Completo: Sensodyne Branqueador Extra Fresh faz um regime completo contra a sensibilidade com as escovas e nossos exaguatórios. Indicado para pessoas com sensibilidade nos dentes, ou seja, que sentem dores ou desconforto ao comer ou beber alimentos gelados, quentes, doces ou cítricos, além de possuir todos os benefícios de um creme dental regular. Modo de Uso: Deve-se escovar duas vezes diariamente, proporcionado um alívio duradouro e eficaz da sensibilidade nos dentes. Conheça toda a fampilia Sensodyne Branqueador Extra Fresh: Sensodyne Branqueador Extra Fresh possui 2 tamanhos, 50g e 90g.', 25.83, 25.83, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd6n-m76w50ocjfrm1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23598321139', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399155295', 'Repelente de Insetos Propex Spray Refrescante 200ml', 'O Repelente de Insetos Propex Spray Refrescante foi especialmente desenvolvido para garantir proteção efetiva contra os mosquitos por até 10h. Possui uma fórmula não oleosa e uma composição com Camomila e Aloe Vera que garante uma fragrância agradável com 10% de Deet.', 44.05, 44.05, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-821fo-mgi1ca8fdtzh33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F22399155295', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897323309', 'Bomba Para Encher Pneus Carro Moto Bike Bicicleta 60cm Vonder', 'Bomba Para Encher Pneus Carro Moto Bike Bicicleta 60cm Vonder A Bomba de Ar Manual com Manômetro é a solução ideal para inflar pneus de carros, motos, bicicletas e diversos itens infláveis, com praticidade e precisão. Fabricada em aço carbono, oferece resistência e durabilidade, enquanto a plataforma de apoio em plástico reforçado garante estabilidade durante o uso. Conta ainda com um manômetro que permite o ajuste e a leitura precisa da pressão. Acessórios inclusos: 1 agulha para encher bolas. 2 bicos para infláveis diversos. Destaques do produto: Corpo metálico robusto e durável. Mangueira plástica flexível de 70 cm, ideal para facilitar o manuseio. Compartimento integrado para armazenamento dos bicos. Alça tipo "T" ergonômica e material de plástico reforçado. Ideal para uso doméstico e profissional em diferentes aplicações. Especificações técnicas: Material do corpo: Aço carbono. Altura da bomba: 63 cm. Diâmetro do corpo: 1.1/2" (38 mm). Material do cabo: Plástico. Pressão máxima: 118 lbf/pol². Cor do corpo: Preto e amarelo. Comprimento da mangueira: 70,0 cm. Peso aproximado: 0,8 kg. Cuidados de uso: Nunca solte o cabo tipo "T" enquanto estiver pressionado e pressurizado, evitando acidentes. Benefícios: Infla pneus e objetos com eficiência e controle. Portátil, leve e prático para transportar e armazenar. Design robusto e acessórios que aumentam a versatilidade de uso.', 150.0, 113.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7r98o-ll2kwbb4f3qab2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F18897323309', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43328036472', 'Kit Limpeza Automotiva Vonixx Sintra Pro + Vertex 5L Cada', 'Kit Limpador de Estofados Automotivo e Residencial Vonixx 5 Litros Kit profissional para limpeza interna de veículos e ambientes residenciais, indicado para estofados, carpetes, painéis e superfícies diversas. Proporciona alta eficiência na remoção de sujeiras e eliminação de microrganismos, garantindo um ambiente mais limpo e saudável. Itens Inclusos: Vertex Limpador de Estofados Vonixx 5L Sintra Pro Multilimpador Bactericida Vonixx 5L Vertex Limpador de Estofados Vonixx 5L: Limpador de estofados automotivos e residenciais com alta concentração de ativos, proporcionando alto rendimento e excelente poder de limpeza. Ideal para uso profissional, atuando com eficiência na remoção de sujeiras e manchas em tecidos diversos. Aplicações: Estofados automotivos Carpetes Tecidos em geral Sintra Pro Multilimpador Vonixx 5L: Multilimpador flotador universal, bactericida e germicida, com pH balanceado. Indicado para limpeza de painéis, laterais e cantos de portas, bancos de couro, carpetes e estofados. Remove manchas de gordura, sujeiras diversas e auxilia na eliminação de microrganismos causadores de doenças. Contribui para a redução de maus odores no interior do veículo, proporcionando ambiente mais saudável. Diluição: Extratoras: até 1:60 Tornador: 1:10 Por que escolher este kit? Produtos novos e originais Vonixx Uso profissional e alto rendimento Ação bactericida e germicida Ideal para limpeza interna automotiva e residencial Pronta entrega e envio em até 24 horas Compra 100% segura', 299.0, 299.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/sg-11134201-82608-mjhhmwbscgslba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2