INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198012621', 'Jogo De Talheres Faqueiro 24 Peças De Aço Inox Positano Lyor', 'Faqueiro Jogo De Talheres 24 Peças De Aço Inox Positano Lyor O Faqueiro 24 Peças De Aço Inox Positano da marca Lyor é a escolha perfeita para quem busca elegância e qualidade na hora de servir. Com talheres de cor cinza, este conjunto traz um toque de sofisticação à sua mesa, seja em ocasiões especiais com a família ou amigos. Cada peça é confeccionada com lâminas de aço inoxidável, garantindo durabilidade e resistência ao desgaste do dia a dia. Os cabos também são de aço inoxidável, assegurando um design harmonioso e um manuseio confortável. A linha Gold reflete o compromisso da Lyor com a excelência, enquanto a embalagem em caixa de papelão assegura uma apresentação impecável, ideal para presentear. Adquira esse faqueiro importado e transforme suas refeições em momentos memoráveis.', 189.0, 99.9, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8nsusbunocia3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F572649927%2F23198012621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
