INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10564004256', 'Cooler para Notebook Dell Inspiron 15R N5010', 'Cooler compatível com Dell Inspiron 15R N5010 Interno Este é um Cooler bringIT compatível com o notebook Dell Inspiron 15R N5010. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Atenção: Esse é um cooler bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Quantidade de vias: 3 vias Corrente (Amperagem): 0.5A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL018-DE-0004', 45.88, 45.88, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-825ay-mqsqhssz5qfh67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F10564004256', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897595242', 'Saboneteira de Parede para Banheiro Sem Furos Dourado 3M Arthi', 'Saboneteira Banheiro Suporte Parede Dourado Fosco Arthi: Elegância e Praticidade em um Toque Clássico Apresentamos a Saboneteira Banheiro Suporte Parede da Arthi, uma adição clássica e elegante para a organização do seu banheiro. Com um design atemporal e funcionalidade moderna, esta saboneteira é a solução perfeita para manter o seu espaço sempre em ordem. -Destaque para o Dourado Fosco: O acabamento em dourado fosco confere um toque de sofisticação, elevando o estilo do seu banheiro. A camada extra de protetivo especial garante cores vivas e maior resistência contra ferrugem, proporcionando durabilidade e beleza. Especificações Técnicas: - Fabricante: Arthi - Tamanho (CxLxA): 13 x 9,3 x 8,3 cm - Cor: Dourado Fosco Instalação Descomplicada: - Fixação através de fita adesiva dupla face 3M extra forte, dispensando o uso de ferramentas e furadeira. Adequado para superfícies lisas e brilhantes como vidros, espelhos, azulejos, entre outros. Instruções de Fixação: - Limpe a superfície com um pano limpo e álcool. Retire o papel protetor adesivo. Cole a saboneteira na posição desejada e segure por 10 segundos. Aguarde 1 hora até que o adesivo fixe completamente. Elevando a estética e a praticidade, a Saboneteira Banheiro Suporte Parede Dourado Fosco Arthi é a escolha perfeita para quem busca organização com um toque clássico.', 57.5, 44.5, NULL, 'Home & Living > Bathrooms > Soap Dispensers, Holders & Boxes', 'https://cf.shopee.com.br/file/sg-11134201-7rd47-lwog0x06tq9231', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402450553%2F23897595242', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
