INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19698869611', 'Toalha de Cabelo - Dry My Hair', 'A Dry My Hair É Uma Toalha Que Traz Praticidade Na Hora de Secar Os Cabelos. Macia, Ela Reduz o Tempo de Secagem Pela Metade, Pois Absorve a Umidade do Cabelo Rapidamente. Feita com Microfibras, Ela Controla o Frizz e Reduz o Atrito Dos Fios, Dando Brilho e Maciez Ao Cabelo. Seu Formato Único e Fechamento de Botão São o Diferencial Desse Produto, Pois Facilitam Na Hora de Enrolar o Cabelo Na Toalha, Segurando Todos Os Fios de Forma Simples e Prática.', 79.9, 69.9, NULL, 'Home & Living > Bathrooms > Towels & Bathrobes', 'https://cf.shopee.com.br/file/sg-11134201-8259q-mqhpvxjceqz231', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F19698869611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200529062', 'Bronzer em Bastão Marrom Médio - Bronzer Contour Stick Edition Simmer 8g', 'Um Contorno Bronzeado Natural É o Toque Perfeito para Valorizar a Beleza Brasileira. Ele Pode Ser Aplicado de Dia ou de Noite, Valorizando Qualquer Look. o Bronzer Contour Stick da Linha Edition É a Escolha Certa para Quem Busca Praticidade e Resultado Profissional. Você Certamente Notou Que Ele Tem Um Formato Triangular Diferenciado, Né? Esse Design Se Encaixa Perfeitamente Nos ângulos do Rosto, Enquanto a Textura Cremosa e Acabamento Matte do Produto Faz com Que Ele Deslize com Facilidade, Oferecendo Pigmentação Intensa, Longa Duração e Alta Fixação. Você Vai Amar Essa Praticidade! Ideal para Dar Profundidade, Contornar e Definir o Rosto, Pálpebras, Lábios, Colo e Pescoço. o Bronzer Pode Criar Diferentes Resultados, a Depender da Técnica Utilizada, Como Disfarçar, Realçar ou Simplesmente Aquecer Seu Look. com Apenas Um Produto, Você Cria Um Universo de Possibilidades para a Sua Maquiagem. São Sete Cores Incríveis Criadas para Atender Aos Tons de Pele Das Brasileiras. a Simmer É Um Ótimo Exemplo: Um Tom Neutro/oliva, com Acabamento Natural e Perfeito para Peles de Tom Médio. Sua Fórmula Vegana, Enriquecida com Óleo de Coco, Cera de Candelila e Esqualano Torna a Aplicação Mais Fácil, o Acabamento Mais Uniforme e o Resultado Mais Duradouro. Um Verdadeiro Must-Have do Seu Nécessaire. O Que Diferencia o Formato Triangular? Esse Formato Inovador Garante Encaixe Perfeito Nos Traços Faciais e Aplicação Muito Mais Precisa. a Tecnologia Faz Parte de Outros Queridinhos da Linha Edition, Como a Foundation Stick, o Iluminador e o Glow Blush Stick. Posso Transformar o Visual com Este Bronzer? Sim! com o Bronzer Contour Stick, Você Pode Escolher Entre Makes Impactantes, Cheias de Definição, para Bal