INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16365710029', 'Máscara de proteção facial PFF1 com válvula Caixa c/50', 'Máscara Modelo PFF1, no formato dobrável, na cor AZUL na parte interna é branco, tipo PFF-1, classe S, com válvula de exalação e com moldador nasal metálico. Utilização: - Poeiras, névoas e fumos em geral de acordo com o Programa de Proteção Respiratório. - Para fechar o respirador aperte-o pelas pontas do clip nasal, evitando vincar a região sobre o nariz, o que pode comprometer a sua vedação. - Armazenar o respirador dentro da embalagem lacrada, em temperatura ambiente, sem umidade, sem exposição direta a luz solar. MODELO: PFF1-(S) COM VÁLVULA CA: 45.023 Cor: Azul', 104.0, 72.5, NULL, 'Home & Living > Tools & Home Improvement > Protective Gloves, Goggles & Masks', 'https://cf.shopee.com.br/file/60c9373cab4afd90cb7e2e0d7c20894d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380456261%2F16365710029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
