INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498733218', 'Calcinha Comfort sem Costura Cenoura Zee Rucci', 'Calcinha Comfort sem Costura CenouraCalcinha comfort perfeita para o dia a dia.Com modelagem ampla, tem maior cobertura na lateral e bumbum.Uma peça ideal para quem ama conforto e cores básicas.Destaque: Este produto é confeccionado com a tecnologia seamless (sem costura). Diferente da confecção tradicional, esta tecnologia produz as peças inteiras em teares. A peça sai praticamente pronta, por isso, descarta a costura para montar diferentes partes das peças, utilizando estas interferências apenas em pequenos acabamentos, proporcionando máximo conforto, maior durabilidade e menos descartes têxteis na produção. Esta tecnologia evita que a peça marque o corpo durante o uso.Composição: 89%POLIAMIDA 11%ELASTANOConteúdo da Embalagem: 01 peçaREF: ZR0207001 C813', 50.81, 50.81, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/sg-11134201-7rdxc-mce56ppzdyttf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1267962009%2F23498733218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
