INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254971200', 'Prato de Vidro 22.4cm Fundo Duralex Primavera', 'Deixe sua refeição mais bonita com o Prato Fundo Duralex Primavera. O prato é decorado com flores que podem combinar ainda mais com sua arrumação da mesa de jantar e na sua cozinha. Feito de vidro resistente ela pode ser lavada no lava-louças sem perigo nenhum de trincar. Tem diâmetro de 22cm, não ocupando muito espaço no seu escorredor e no seu armário. OPrato Fundo Duralex Primavera pode combinar perfeitamente com temas floridos do seu ambiente, deixando mais bonito sua preparação da comida. Garanta o seuPrato Fundo Duralex Primavera com o menor preço! Não perca mais tempo, compre online agora mesmo e adicione ao seu carrinho! São diversas opções. Navegue em nossa linha completa de Pratos e Aparelhos de Jantar e confira todos os modelos disponíveis com preços em ofertas. Facilidades: -Feito de vidro resistente com detalhes floridos -Pode ser lavado no lava-louças -Ideal para deixar mais bonito sua sala de jantar Características: -22cm de diâmetro -Totalmente de vidro', 24.99, 12.9, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mr1nx4ulweto98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412968566%2F58254971200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298882388', 'Correia De Acessórios - Contitech - 6PK1891', 'A correia de acessórios da CONTITECH é uma peça essencial no sistema de transmissão de veículos, responsável por acionar diversos componentes auxiliares, como alternador, bomba d''água, compressor de ar condicionado e direção assistida. Fabricada com materiais de alta qualidade, como borracha reforçada com fibra de vidro ou polímeros avançados, a correia oferece resistência à abrasão, ao calor e ao desgaste, garantindo um funcionamento confiável e duradouro. Com um design preciso e uma construção robusta, a correia de acessórios da CONTITECH proporciona uma transmissão eficiente de energia, contribuindo para o desempenho adequado dos sistemas auxiliares do veículo. Além disso, a CONTITECH oferece uma variedade de correias de acessórios com diferentes tamanhos e configurações para atender às necessidades específicas de cada veículo. Especificações: - Marca; CONTITECH - Garantia; 3 Meses - Comprimento; 1891 mm - Função; ALTERNADOR / AR CONDICIONADO / DIREÇÃO HIDRÁULICA - Largura; 21 mm - Quantidade de lamelas (lâminas); 6 Aplicação: Chevrolet Captiva SPORT 2006 - 2013 Chevrolet Vectra ELEGANCE NLEV 2006 - 2012 Chevrolet Vectra ELEGANCE TAXI 2006 - 2012 Chevrolet Vectra ELITE 2006 - 2012 Chevrolet Vectra ELITE TAXI 2006 - 2012 Chevrolet Vectra EXPRESSION 2006 - 2012 Chevrolet Vectra EXPRESSION TAXI 2006 - 2012 Chevrolet Vectra GT 2006 - 2012 Chevrolet Vectra GT-X 2006 - 2012', 110.44, 82.83, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rfi1-m9rn2d0imzsw58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F23298882388', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
