INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42954418996', 'LIQUIDIFICADOR PLQ1430P LIMPA FACIL 127V Preto', 'PRATICIDADE PARA A SUA COZINHA! Aumente a facilidade de preparar suas receitas com o Liquidificador Philco PLQ1430P Pro Maxx 6. Com ele você tem misturas mais homogêneas e saborosas, graças a sua alta capacidade de volume útil de 2,1 litros! Além disso, ele conta com a tecnologia Pro Maxx, possuindo 6 lâminas com altíssimo poder de trituração, não deixando nenhum pedacinho por inteiro. Com a função Ice você pode preparar raspadinhas e smoothies, triturando gelo com maior facilidade e rapidez. Esse incrível liquidificador conta com 12 velocidades mais funções diferentes para você encontrar a que mais se adapta ao seu preparo! • 12 Velocidades • Tampa com sobretampa dosadora; • Faca com 6 lâminas; • Alça do copo anatômica; • Copo de plástico com capacidade total 3,0l; • Capacidade útil de 2,1l; • Painel inox; • Base antiderrapante; • Lâminas removíveis. ------------------------------------------------------------------------------- DIMENSÕES E PESO: Altura: 42,4 cm Largura: 23,5 cm Profundidade: 24,6 cm Peso: 2,290 kg Estamos à disposição para esclarecer qualquer dúvida. Atenciosamente, Equipe NegociuN!', 547.97, 252.9, NULL, 'Home Appliances > Kitchen Appliances > Juicers, Blenders & Soya Bean Machines', 'https://cf.shopee.com.br/file/br-11134207-7r98o-may9ddu7fxjjde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343318906%2F42954418996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
