INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698175648', 'Kit 3 Camisetas Apex Sem costura Alpha', 'Garanta uma peça versátil e de alto rendimento para compor seu arsenal fitness com a camiseta dry fit masculina Alpha. Perfeita para quem treina com regularidade e precisa de uma roupa que acompanhe o ritmo intenso das atividades diárias. Fabricada com blend técnico de 68% poliéster + 32% poliamida, esta camiseta oferece toque suave na pele, modelagem que valoriza a silhueta e mobilidade completa para você executar qualquer movimento sem limitações. A tecnologia dry age de forma contínua no gerenciamento térmico: retira a umidade da superfície da pele e estimula a evaporação acelerada, proporcionando sensação refrescante mesmo nos treinos mais desafiadores. Mantenha-se seco e focado no seu objetivo. Benefícios do produto: - Peça individual versátil: complemento ideal para seu guarda-roupa esportivo. - Sistema dry de resposta imediata: controla transpiração e mantém frescor. - Aplicação universal: excelente para academia, caminhada, corrida, esporte, beach tennis, ciclismo, futebol, hiit, hyrox, musculação, spinning, treino ao ar livre, treino em casa, treino funcional, treino intenso, crossfit e exercício. - Fácil manutenção: lava rapidamente, seca em pouco tempo e mantém qualidade. Invista em uma peça que entrega resultado treino após treino.', 299.7, 299.7, NULL, 'Men Clothes > Tops > T-Shirts', 'https://cf.shopee.com.br/file/sg-11134201-825aq-mqe98bytips22d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337417367%2F22698175648', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
