INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294663927', 'Conjunto Infantil Menino Piquet Colorittá Vermelho', 'O Conjunto Colorittá é composto por camiseta em piquet trabalhado e bermuda em moletom ponto roma. A camiseta de mangas curtas possui detalhe de recorte em V com sobreposição no decote e botões decorativos, trazendo um toque charmoso ao look. Já a bermuda conta com elástico no cós e bolsos laterais. Ideal para momentos especiais em família, esse conjunto é a escolha perfeita para deixar os meninos ainda mais lindos. Aposte!Detalhes da peça: • Conjunto composto por camiseta e bermuda • Feito em piquet trabalhado e moletom ponto roma • Possui mangas curtas • Possui recorte V com sobreposição • Elástico no cós • Possui bolsos • Ideal para momentos especiais em família', 189.9, 94.95, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8257y-mr1tn4wktfk5e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1079500559%2F23294663927', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
