INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48709398479', 'KIT 2 Tênis QIX Chorão Park Masculino Feminino', 'Um é bom, mas dois é PERFEITO! Quem é da família precisa garantir um tênis desse, mas como sabemos que você "veste a camisa" aí vai dois pares de uma vez que o drop fica completo! Características desse produto: O tênis CHORÃO QIX PARK possui cabedal em camurça de couro natural, solado em borracha natural vulcanizada, palmilha e espuma de alta densidade garantem o conforto e mais durabilidade, a forração interna é feita em tecido poliéster de excelente gramatura dublada em espuma, oferecendo ainda mais conforto. Características do ProdutoNome: QIX CHORÃO PARK Gênero: Masculino/Feminino Indicado: Uso diário e prática de skate Tipo de Ajuste: Cadarço Forro: Tecido poliéster com espuma poliuretano de alta densidade Palmilha: Em EVA antibactéria (evita bactérias e fungos) Solado: Vulcanizado Forma: Grande (recomenda-se escolher um número menor do que o seu tamanho padrão)', 659.9, 499.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-820nx-mneqan0blbeo95', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976841479%2F48709398479', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
