INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297969970', 'Termômetro Digital Infravermelho De Testa Sem Contato LCD Febre Medição Do Bebê/Adulto', 'O Termômetro digital infravermelho sem contato Easy Sensor G-Tech é indicado para medição de temperatura corpórea a distância de maneira rápida e precisa, podendo ser utilizado para medir, além da temperatura corpórea, a temperatura de ambientes e superfícies. Com seu exclusivo sensor de distância, o termômetro emite indicadores no visor para garantir a distância correta para a medição precisa. E o melhor: as temperaturas aferidas ficam armazenadas na memória, permitindo um acompanhamento preciso das variações de temperatura. - Exclusivo sensor de distância: garante a distância correta para uma medição precisa - Touch Free: sem contato com a pele, mais prático e higiênico - Versátil: mede a temperatura corpórea e de ambientes - Sistema Color Glow: o display muda de cor conforme a temperatura - Memória para 30 medições', 137.99, 129.99, NULL, 'Health > Medical Supplies > Health Monitors & Tests', 'https://cf.shopee.com.br/file/sg-11134201-7reop-m1o39fplvr2hfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F602117686%2F20297969970', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
