INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21597673624', 'Pia Sintética para Cozinha 100cm x 53cm Aj Rorato Cinza', 'Pia Roralit Granitada em mármore sintético com espessuras reforçadas, com cobertura granitada de gel coat com brilho e resistência incomparáveis. Superfícies mais lisas sem porosidade proporcionando maior higiene e fácil limpeza. Pias com protetor de parede e caneletas altas, evitando o derramamento acidental de água. Peso (kg): 9.31 Garantia: 03 Meses Altura (cm): 10.2 Largura (cm): 100 Espessura (mm): 30 Tipo de Cuba: Simples Profundidade (cm): 53 Acompanha Válvula: Não Origem do Produto: Nacional Ambiente Principal: Cozinha Material Principal Construção e Acabamento: Mármore Sintético Marca: AJ Rorato Cor: Cinza', 300.92, 300.92, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gp-mptwemwlzpc0d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F21597673624', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208048806', 'Vinil Def Leppard - Pyromania - Importado', 'Vinil Def Leppard - Pyromania - Importado Pyromania é o terceiro álbum de estúdio do Def Leppard lançado em 20 de janeiro de 1983. O álbum alcançou a posição # 2 na Billboard e # 18 na UK Albums Chart. Com mais de 110 milhões de álbuns vendidos em todo o mundo e dois prestigiados Diamond Awards nos EUA, os indicados ao Rock & Roll Hall of Fame® de 2019, Def Leppard com Joe Elliott no vocal, Phil Collen e Vivian Campbell na guitarra, Rick Savage no baixo e Rick Allen na bateria, continuam a ser uma das forças mais importantes do rock. Ao longo de sua carreira, a banda produziu uma série de álbuns clássicos inovadores que estabeleceram o padrão para gerações de fãs de música e artistas. Os espetaculares shows ao vivo e o arsenal de sucessos do grupo se tornaram sinônimos de seu nome, levando o Def Leppard a ser aclamado como uma das maiores bandas de rock ao vivo do mundo. A carreira influente de Def Leppard inclui vários singles de sucesso e álbuns multi-platina inovadores - incluindo dois dos álbuns mais vendidos de todos os tempos, Pyromania e Hysteria, capturando as faixas lendárias do grupo, reunindo sucessos clássicos de Leppard como “Rock of Ages ”, “Pour Some Sugar on Me” e “Foolin”. Pela primeira vez, em janeiro de 2018, o Def Leppard estreou seu catálogo completo de gravações em todo o mundo através de plataformas de streaming e download. Assim como fizeram com o lançamento original de seus discos, o Def Leppard dominou as paradas mundiais novamente, o que colocou seus álbuns no Top 10 do iTunes em mais de 30 países, incluindo Hysteria em 3º lugar nos EUA e 5º no Reino Unido. Def Leppard também teve os discos #1, #2 e #3 na parada de álbuns do catálogo dos EUA. A banda acumulou impressionantes 6 bilhões de streams desde 2018, alcançando um grupo demográfico mais jovem de 18 a 44 anos que agora representa 58% de sua base de fãs. Além disso, a banda conquistou impressionantes 15 milhões de seguidores em suas plataformas de mídia social. Repertório do LP: Lado A: A1. Rock! Rock! (Till You Drop) A2. Photograph A3. Stagefright A4. Too Late For Love A5. Die Hard The Hunter Lado B: B1. Foolin’ B2. Rock Of Ages B3. Comin’ Under Fire B4. Action! Not Words B5. Billy’s Got A Gun', 269.9, 229.9, NULL, 'Hobbies & Collections > Vinyl Records', 'https://cf.shopee.com.br/file/sg-11134201-8257z-mq6xryilr9xrfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58208048806', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698350799', 'Kit 2 Cestos Organizadores Multiuso Redondos Alças Tampa Azul Lavanderia Banheiro Plasútil', '- Os cestos organizadores multiuso - FITA - &nbsp;possuem design que remetem aos trançados da corda náutica. Tendência do segmento de decoração que ganha cada vez mais espaço ao longo dos anos devido à estética rústica contemporânea. &nbsp; - Em dos tamanhos (baixo e alto), são ótimas opções para banheiros ou lavandeiras no armazenamento de roupas sujas. Por serem vazados, permitem circulação de ar na parte interna evitando odores desagradáveis ou que os tecidos fiquem abafados. As alças laterais, facilitam o transporte de um ambiente para outro e a tampa encaixável não deixa que a bagunça fique aparente. &nbsp; - Também podem ser usados de forma decorativa em salas ou homes para armazenamento de mantas, cobertas e almofadas. &nbsp; - Fabricado em plástico polipropileno (PP). Atóxico e livre de bisfenol-A. &nbsp; - Plástico rígido e reforçado. Maior durabilidade e resistência. &nbsp; - Dimensões: Alto: 36,5 x 34,8 x 59,7 cm – 37 L Baixo: 36,5 x 34,8 x 32,0 cm – 19 L', 189.9, 189.9, NULL, 'Home & Living > Home Organizers > Laundry Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-7rd6z-m7s3f7q455t3c3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F22698350799', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258602332', 'Vinil Louis Tomlinson - How Did I Get Here? (Deluxe Double) - Importado', 'Vinil Louis Tomlinson - How Did I Get Here? (Deluxe Double) - Importado Vinil Duplo com Capa Gatefold, Edição Limitada. Inclui 2 faixas bônus. How Did I Get Here? é o aguardado terceiro álbum de Louis Tomlinson. Criado no vibrante ambiente de Santa Teresa, Costa Rica, o disco captura sua criatividade incansável e seu espírito artístico destemido. Após o sucesso do álbum de estreia, Walls (2020), e do sucesso Faith In The Future (2022), este novo capítulo consolida a evolução de Louis para o artista que ele sempre quis ser. Tracklist: 1. Lemonade 2. On Fire 3. Sunflowers 4. Lazy 5. Palaces 6. Last Night 7. Broken Bones 8. Dark To Light 9. Imposter 10. Sanity 11. Jump The Gun 12. Lucid 13. The Observer 14. The Answer', 349.9, 297.9, NULL, 'Hobbies & Collections > Vinyl Records', 'https://cf.shopee.com.br/file/sg-11134201-825at-mr0jrv6b6fpce8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F58258602332', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
