INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18453603095', 'Motor de Partida Cb 300R 2009-2015 / Xre 300 2009-2018 Magnetron', 'Conteúdo da Embalagem: 01 Motor de Partida - Magnetron Código: 90205860 Código da peça original: 31200-KVK-901 O motor de partida, também conhecido como motor de arranque tem a função de acionar o motor da motocicleta até que ele possa funcionar normalmente sozinho. Ao girar a chave na moto, o motor de partida é acionado diretamente pela bateria, transformando assim essa energia elétrica em mecânica quando o motor é acionado. Compatível com: HONDA CB 300R (2009-2015) CB 300R LIMITED (2012-2012) XRE 300 (2009-2012) XRE 300 FLEX (2013-2018) Especificações e Características: - Facilidade na partida e agilidade na instalação; - Torque e potência com baixo consumo da bateria; - Modelos fabricados com rolamento agulha; - Ponto de fixação para encaixes perfeitos, evitando adaptações ou retrabalho - Equivalente a Peça Original - Ideal para Reposição - Alta Resistência e Durabilidade - Tratamentos contra a oxidação - Confeccionado com a melhor matéria-prima - Melhor condutibilidade e maior vida útil da peça - Material leve e resistente - Ótimo acabamento, proporcionando uma instalação sem adaptações - Excelente qualidade e acabamento Instalação: - Este produto é de fácil instalação, não exige que mude a estrutura de sua moto, pois foi confeccionado seguindo as especificações do produto original, para encaixe e funcionamento perfeito. *O motor de arranque utiliza o mesmo padrão da peça original, sendo assim segue todas as especificações do original! Importante: - Para a instalação do produto corretamente, leve ao mecânico de sua confiança! - Não nos responsabilizamos pelo uso indevido do produto.', 936.9, 749.52, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/b44a1a155793e41956432d7a9f380e85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F18453603095', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
