INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256667843', 'Shampoo e Condicionador 5 em 1 Pet Clean Cães e Gatos 700ml', 'O Shampoo Pet Clean 5 em 1 para Cães e Gatos oferece limpeza completa, brilho intenso, ação desembaraçante, hidratação profunda e fragrância suave, tudo em um único produto. Desenvolvido para proporcionar praticidade e eficiência, é ideal para manter a pelagem saudável e bonita no dia a dia. Com fórmula balanceada, o shampoo é indicado para cães e gatos de diferentes raças e tamanhos, ajudando a manter a higiene e o bem-estar dos pets com segurança. FICHA TÉCNICA Marca: Pet Clean Produto: Shampoo 5 em 1 Indicação: Cães e gatos Funções: Limpeza, brilho, hidratação, desembaraço e fragrância Tipo de uso: Higiene regular da pelagem Volume: 700 ml Tipo de pelagem: Todos os tipos CUIDADOS COM O PRODUTO Uso externo, específico para cães e gatos Evitar contato com olhos, boca e ouvidos do animal Não ingerir Em caso de irritação, suspender o uso e consultar um veterinário Conservar em local fresco, seco e protegido da luz solar Manter fora do alcance de crianças Usar conforme orientação do fabricante', 17.9, 17.9, NULL, 'Pets > Pet Grooming > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260p-mlnw8nhddc75e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1760624219%2F58256667843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
