INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097669629', 'Ducha Higiênica Banheiro Yesop Dourada Núcleo de Cobre Alta Qualidade Brilhante', '🚿 Pulverizador de Bidê Portátil em Latão – Prático, Higiênico e Versátil Na abertura e fechamento do mecanismo 1/4 volta o consumo/desperdício é em torno de 84 ml d’água para o processo completo de abertura e fechamento, enquanto que no sistema vedante esse consumo é em torno de 970 ml, pois ela precisa de 5 giros para completar o ciclo de abertura/fechamento. Garanta mais higiene e praticidade no seu dia a dia com o nosso pulverizador de bidê portátil. Ideal para uso doméstico e profissional, ele oferece conforto, durabilidade e múltiplas aplicações. ✅ Principais Benefícios 💧 Higiene íntima feminina com mais conforto 🚽 Limpeza eficiente do banheiro e cantos difíceis 🚗 Pode ser usado para lavagem de carro 🌿 Ideal para jardim e cuidados com plantas 👨‍🦽 Perfeito para idosos, pessoas com mobilidade reduzida e cuidados especiais 🏨 Indicado para casas, hotéis, spas e clubes 🔧 Especificações do Produto Nome: Pulverizador de Bidê Portátil Material do gatilho (chuveirinho): Latão de alta qualidade Válvula de controle duplo: Latão Suporte de parede: Latão Mangueira: Aço inoxidável resistente Comprimento da mangueira: 1,5 metros Conexão: Padrão G1/2" Água quente e fria: Não (apenas água fria) Instalação: Montagem na parede 📦 Conteúdo da Embalagem 1 × Pulverizador de bidê portátil 1 × Válvula de controle duplo 1 × Suporte de parede 1 × Mangueira de aço inox (1,5 m) Acessórios para instalação ⚠️ Observações Importantes Medições manuais podem apresentar pequenas variações. A cor do produto pode variar levemente devido à iluminação e tela. Consulte o produto real como referência final.', 249.0, 139.99, NULL, 'Home & Living > Bathrooms > Showerheads & Bidet Sprays', 'https://cf.shopee.com.br/fi