INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4677377153', 'Pulseira elos coração prata 925 feminina', 'Itens inclusos: -Pulseira em prata 925 elos coração -tamanho: 19cm - Termo de Garantia Esta linda peça, fabricada em Prata legítima, teor 925, além de linda trás a simplicidade e a elegância da beleza feminina. A Prata com teor 925, é o metal mais precioso, depois do ouro. Sua legitimidade pode ser confirmada através de sua marcação nas peças e pelo certificado de garantia que oferecemos. Garantimos a autenticidade de nossos produtos. Compre e tenha certeza de receber uma jóia com duração para o resto da vida. A prata 925 é um material que tem garantia e durabilidade permanente, assim como o ouro 18k. Nossas jóias tem certificado de autenticidade reconhecidos no mundo todo, você pode levar em qualquer joalheria para efetuar os testes e comprovar a autenticidade das mesmas. Havendo dúvidas, não hesite em perguntar por favor! Será um prazer atendê-lo. Acompanha certificado que garante teor 925 do produto.', 64.83, 37.0, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/sg-11134201-7rd46-lvdj5tkaxi426e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F4677377153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
