INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598769035', 'Bomba De Oleo Sandero 1.6 8v K7m 2012 2013 2014 2015 Takao', 'APLICAÇÃO COMPLETA - COMPATÍVEL COM OS SEGUINTES VEÍCULOS: RENAULT LOGAN 1.6 8V K7M - 2007 a 2015 SANDERO 1.6 8V K7M - 2007 a 2015 SYMBOL 1.6 8V K7M - 2009 a 2014 OMBA DE ÓLEO PARA MOTORES RENAULT 1.6 8V K7M MODELO COM 22 DENTES MARCA: TAKAO REFERÊNCIA OEM: 8200698014 Garanta a lubrificação ideal do motor com a bomba de óleo Takao BORE16A, projetada para oferecer alto desempenho, durabilidade e confiabilidade. Produzida com rigorosos padrões de qualidade, esta bomba é responsável por manter o fluxo constante de óleo lubrificante, essencial para evitar desgaste prematuro das peças internas e garantir o bom funcionamento do motor. - Alta eficiência na lubrificação - proteção completa para o motor - Produto novo - envio imediato com nota fiscal e garantia - Marca Takao - referência em peças de reposição automotiva', 530.97, 530.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rdwn-mcqhv0eo332m8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1355197042%2F23598769035', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297477890', 'Pré Filtro Combustível Vw Kombi 1997 a 2005 - 133715 - 1302', 'Pré Filtro Combustível Vw Kombi 1997 a 2005 133715 1302 Motor 1.6 8v Álcool/Gasolina - (Sistema Marwal)O pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 36.98, 36.98, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd5v-m7s4ebnsizcofa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22297477890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
