INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22392567488', 'Válvula Termostática Peugeot 206 1.4 8V 1.6 8/16V 1999/2010 - 16102 - VT37089', 'Válvula Termostática Peugeot 206 1.4 8V 1.6 8/16V 1999/2010 Produto novo, com garantia e nota fiscal! Válvula Termostática - VT37089 Aciona em: 89º Aplica em: Peugeot 206 1.4 8V 1.6 8/16V - 1999 2000 2001 2002 2003 2004 2005 2006 2007 2008 2009 2010 A válvula termostática é uma peça importantíssima do sistema de arrefecimento dos carros. Ela controla a temperatura do motor. Quando o motor está frio, ela fica fechada, fazendo com que o líquido de arrefecimento (água e aditivo) volte para o bloco do motor. A partir de uma determinada temperatura, cerca de 90 graus, ela se abre, permitindo a passagem do líquido para o radiador para que ele seja refrigerado e volte para o bloco. A manutenção preventiva a cada 30 mil km ou menos.', 74.16, 74.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rbn1-lmxegtbjzeca2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22392567488', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799005450', 'Termostato SANDERO 2007/2016 - 29336 - VT43889', 'Termostato SANDERO 2007/2016 Motor 1.0 16v /1.6 8/16 - (89 º) (Com Flange) A válvula termostática é uma peça importantíssima do sistema de arrefecimento dos carros. Ela controla a temperatura do motor. Quando o motor está frio, ela fica fechada, fazendo com que o líquido de arrefecimento (água e aditivo) volte para o bloco do motor. A partir de uma determinada temperatura, cerca de 90 graus, ela se abre, permitindo a passagem do líquido para o radiador para que ele seja refrigerado e volte para o bloco. A manutenção preventiva a cada 30 mil km ou menos.', 139.49, 139.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbn0-lmt3bbcz88qh48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20799005450', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
