INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19697673682', 'Filtro Gasolina ESCORT 1984/1992 - 43320 - FCC225', 'Filtro Gasolina ESCORT 1984/1992 MOTOR 1.3/1.6 CHT/1.8 AP ÁLC/GAS (GRANDE BICO 6/8mm) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 18.7, 18.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd3t-luf1jwmsetmzd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19697673682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997461969', 'Palheta Limpador Para-Brisa Gm Omega 1992 a 1998 - 198393 - PVT13', 'Palheta Limpador Para-Brisa Gm Omega 1992 a 1998 198393 PVT13 13" traseira - Conexão gancho Os limpadores combinam duas tecnologias mecânicas. A primeira delas é uma combinação de motor elétrico com engrenagem redutora. Ela é responsável por gerar a força necessária para acionar os limpadores. A segunda delas é um inteligente sistema de transmissão por hastes, ela converte a rotação de saída do motor no movimento dos limpadores para de um lado para o outro.Elas funcionam como uma espécie de rodo. Estas hastes arrastam uma fina tira de borracha com a função de retirar a água.', 21.5, 21.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rbks-ln0lwt5zb7ed1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18997461969', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
