INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6769633921', 'Vaso Cachepot de Madeira Cônico com Rodas 40cm Decoração', 'Vaso de madeira com rodas embutidas, para quem deseja melhorar o aspecto de seu ambiente internoDesign ripado e com rodas de silicone, este modelo é ideal para áreas internasCor envelhecidoObservações: O vaso acompanha 2 mãos de verniz marítimo, podendo ser exposto a sol e chuva, mas não recomendamos deixa-lo em áreas externasEste vaso tem a função de cachepot, ou seja, não é para plantar direto neleMarca: Alpe &amp; Aritana', 169.9, 169.9, NULL, 'Home & Living > Decoration > Vases & Vessels', 'https://cf.shopee.com.br/file/4f4967805b7270836d3c39b034dc2192', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F306698991%2F6769633921', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
