INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398003174', 'Arandela Led Externa Cube 12w 6500k Cafe Avant', 'Arandela Cube - Café - 12W - Avant A Arandela Cube é a solução ideal para quem busca aliar funcionalidade e beleza na iluminação de seus ambientes. Com design moderno e formato retangular, ela oferece um efeito luminoso homogêneo e elegante, ideal para destacar fachadas, áreas de circulação, corredores, escadarias, halls, jardins, piscinas e espaços de convivência. • Propriedades - Iluminação eficiente e econômica: Potência de 12W com LED integrado - Alta durabilidade: Corpo em ABS e difusor em policarbonato - Proteção contra intempéries: Índice de proteção IP65, ideal para áreas externas e ambientes úmidos. - Ângulo de abertura de 120°: Distribuição uniforme da luz, criando um ambiente aconchegante. - Facilidade de instalação: Tipo de instalação sobrepor, simplificando a instalação. • Características de funcionamento - Tensão nominal: Bivolt (100-240V) - Temperatura de cor: 6500K (Luz Branco Frio) - Fator de potência: =0,50 • Especificações Técnicas - Código: 341311371 - Potência: 12W - Fluxo luminoso: 720lm - Eficiência luminosa: 60 - Dimensões: 42mm x 118mm x 204mm - Peso: 300g • Garantia: A Arandela Cube possui Garantia Oficial Avant de 12 meses para defeitos de fabricação. Sobre a Avant: A Avant é uma marca que se destaca no mercado de iluminação por oferecer produtos de alta qualidade, design inovador e tecnologia de ponta. Com foco na eficiência energética e na sustentabilidade, a Avant busca proporcionar soluções luminosas que aliam beleza, funcionalidade e respeito ao meio ambiente.', 155.9, 94.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rep6-m1zzhww6kcho4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275385296%2F22398003174', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20298131378', 'Spot Led Authentic Embutir 3w 6500k Branco Frio 7cm 110v/220v Bivolt Ip20 Quadrado Branco Cod: 865441376 Avant', 'SPOT AUTHENTIC 3W - Iluminação Moderna e Eficiente O SPOT AUTHENTIC 3W é a escolha ideal para quem busca uma iluminação moderna e eficiente em seus ambientes internos. Com luz branca fria e direcionável, ele oferece um toque de modernidade e funcionalidade, ideal para destacar objetos e criar um ambiente clean e convidativo. PROPRIEDADES: Livre de mercúrio; Ajuste manual da direção da luz; Acabamento em policarbonato na cor branca; Baixo consumo de energia. CARACTERÍSTICAS DE FUNCIONAMENTO: Temperatura ambiente: -5°C a 40°C; Tensão de entrada: 100V a 240V; Fator de potência: >0,50; Tipo de Instalação: Embutido. ESPECIFICAÇÕES TÉCNICAS E COMERCIAIS: Código: 865441376 Modelo: LED-SPOT-AUTHENTIC-EMB-QUA-BR6500K-3W-BIVOLT-250 Potência: 3W Candelas: 385cd Fluxo Luminoso: 250 Im Eficiência Luminosa: 83 lm/W Temperatura de Cor: 6500K Emissão de Cor: 70 Dimensões (mm): A: 70, B: 70, C: 30 Nicho de Corte (mm): 055 Peso (g): 43g GARANTIA: O SPOT AUTHENTIC 3W conta com a garantia oficial Avant de 12 meses para defeitos de fabricação. SOBRE A MARCA AVANT: A Avant é uma marca reconhecida pela qualidade e inovação em iluminação LED. Com um compromisso com a sustentabilidade e a excelência, a Avant oferece soluções inteligentes e eficientes para diversos ambientes, contribuindo para um futuro mais sustentável e iluminado.', 21.5, 16.13, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rff9-m97g70jdcis56b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275385296%2F20298131378', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
