INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42268701904', 'Rodo com Spray (MOP) Vonder – Limpeza Prática e Econômica de Pisos', 'Rodo com Spray (MOP) – VONDER 63.58.400.000 Transforme a limpeza da sua casa em algo rápido, eficiente e econômico com o Rodo com Spray Vonder! Ideal para pisos lisos como porcelanatos, cerâmicas e azulejos, ele possui reservatório com gatilho spray, aplicando água e produtos de limpeza de forma controlada, sem desperdício. Seu cabo anatômico garante conforto e praticidade, tornando a limpeza diária muito mais fácil. Itens Inclusos: 1 Rodo com spray 1 Almofada de refil Especificações Técnicas: Material: Haste e corpo em aço Capacidade do reservatório: 600 ml Comprimento total do rodo: 1,25 m Dimensões da base: Superior 35,5 cm / Inferior 32,5 cm / Largura 12 cm Peso aproximado: 0,692 kg Por que escolher este produto? Produto novo e original Pronta entrega: envio em até 24 horas Compra 100% segura Estoque limitado: garanta o seu antes que acabe!', 180.0, 180.0, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/sg-11134201-824h3-mek1ooxqwd1d17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F42268701904', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
