INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45253308175', 'Sapateira Multiuso Slim para Apartamento e Espaços Pequenos', 'Sapateira ideal para quem busca organização, praticidade e um visual moderno para o ambiente. Com design compacto e funcional, permite armazenar seus calçados de forma organizada, protegendo contra poeira e facilitando o acesso no dia a dia. Possui 2 portas basculantes, que otimizam o espaço e garantem melhor visualização dos sapatos. Sua estrutura é fabricada em MDP de qualidade, oferecendo resistência e durabilidade para o uso diário. Cada prateleira suporta até 10 kg, ideal para diferentes tipos de calçados como tênis, sapatos, sandálias e chinelos. Perfeita para uso em quartos, closets, halls de entrada ou corredores, a sapateira combina facilmente com diversos estilos de decoração, trazendo mais organização sem ocupar muito espaço. Características: 2 portas basculantes Organização prática e eficiente Estrutura em MDP Suporta até 10 kg por prateleira Design moderno e compacto Ideal para quarto, closet ou hall de entrada Dimensões aproximadas: Altura: 76 cm Largura: 60 cm Profundidade: 28 cm Produto enviado desmontado, acompanha manual de montagem e ferragens. Montagem simples (recomenda-se uma pessoa).', 299.98, 171.05, NULL, 'Home & Living > Home Organizers > Shoe Storage Boxes', 'https://cf.shopee.com.br/file/br-11134207-820m8-mqxb6mxs7jt117', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242718651%2F45253308175', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797981916', 'Kit Central Multimidia Dvd 2 Din Palio Siena Strada Fire G2', 'Kit Central Multimidia 2 din Mp5 7" Polegadas Central Multimidia / Moldura / Câmera de Ré Contém espelhamento de tela com iOs e Android conhecido como Mirror Link, tela de 7" polegadas, potência em 4 canais de 50 watts para tocar seus alto-falantes com ótima potência. Possui entrada USB, conexão Bluetooth, entrada auxiliar e ainda para câmera de ré, além de rádio FM e player de MP3 e MP4 e MP5. Compatível com: Fiat: - Palio Fire G2 - Siena 1.0 Fire - Strada 1.4 MPI Fire - Fabricados entre os anos de 2002 a 2014 *COM AR CONDICIONADO Moldura Fiamon, que tem hoje o melhor acabamento comercializado. A Fiamon tem garantia de qualidade já demonstrado pelos anos de sucesso nas vendas, sendo sem dúvida a melhor e mais bonita opção disponível no mercado mantendo a originalidade e qualidade no acabamento de seu veículo. COR: CINZA Especificações Técnicas: - Tela Full Touch 7" Polegadas de Alta Definição - Resolução de Imagem 800 x 480 - Formato de vídeo 1080P - Idiomas: Chinês , Inglês , Russo , Espanhol e Português - Painel com 7 cores de iluminação: (Azul, Azul Oceano, branco, amarelo, vermelho, roxo e verde) - Equalizador Jazz, POP, Classic, Rock - 30 Estações de Rádio pré selecionadas 12AM/18FM - Saída de áudio: 4x50W - Seleção de Logotipo de Inicialização - Espelhamento Android e IOS - Reprodução de áudio MP3/WMA/WAV/FLAG/OGG/APE - Reprodução de vídeo RM/RMVB/DVD(VOB)/VCD(DAT)/DIVX/XVID - Reprodução de vídeo MP4/H2664HFLV/3GP/AVI/ASF etc. Conexões: - 1 Entrada para Câmera de Ré - 1 Entrada AV - 2 Saídas de vídeo para telas traseiras - 2 Saídas para Amplificador - 1 Entrada USB - 1 Entrada Auxiliar P2 - Microfone Interno - Conexão Principal: Padrão ISO - Comandos de Volante Resistivo (Necessário Interface