INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198699157', 'Jogo Chave Fenda Philips Magnetizada Imã 10 Peças Vonder Profissional', 'KIT/JOGO CHAVE DE FENDA E PHILIPS - PONTAS MAGNETIZADAS/IMANTADAS - AÇO CROMO VANÁDIO - PROFISSIONAL VONDER O kit chave de fenda Phillips da Vonder é um conjunto de ferramentas que não pode faltar em sua casa ou na sua empresa. Produzida em aço cromo vanádio, proporcionando maior resistência e durabilidade. Possui acabamento niquelado que aumenta a proteção contra oxidação/corrosão. Conta com ponta magnetizada que facilita tanto a colocação quanto a retirada de parafusos em locais de difícil acesso, além de cabo anatômico em polipropileno revestido com borracha termoplástica que garante maior conforto ao operador. Indicado para fixar e soltar parafusos fenda/phillips. :: BENEFÍCIOS 1 - Maior resistência e durabilidade 2 - Proteção contra oxidação e corrosão 3 - Ponta magnetizada :: FICHA TÉCNICA -Material do cabo: Polipropileno revestido com borracha termoplástica -Cor: amarelo e preto -Quantidade: 10 peças -Acabamento: niquelado -Material do jogo: aço cromo vanadio :: CONTEÚDO DA EMBALAGEM 1 Jogo de chaves de fenda/phillips composto por 10 peças, sendo: 1 chave de fenda 1/8" x 2" 1 chave de fenda 3/16" x 1.1/2" 1 chave de fenda 3/16" x 3" 1 chave de fenda 1/4" x 1.1/2" 1 chave de fenda 1/4" x 4" 1 chave de fenda 5/16" x 6" 1 chave phillips 1/8" x 2" 1 chave phillips 3/16" x 1.1/2" 1 chave phillips 3/16" x 3" 1 chave phillips 1/4" x 4". Emitimos Nota fiscal e Envio Imediato.', 74.9, 68.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbrdh2vhflg9d4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F885912594%2F23198699157', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
