INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23592934099', 'Kit 2 Reparador Capilar Óleo de Coco 60ml Belkit', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - APRESENTAÇÃO: KIT com 2 Unidades. - - - - - DESCRIÇÃO: Com textura suave e sensorial leve, o Reparador de Pontas Óleo de Coco Belkit - 60ml possui alto poder de umectação. Formulado para propor a solução perfeita para quem sofre com as famosas pontas duplas, frizz, falta de brilho e outras imperfeições que comprometem a beleza dos cabelos. O Reparador de Pontas Óleo de Coco Belkit - 60ml possui nutrientes que ajudam a repor a umidade natural dos fios, deixando-os suaves, alinhados, com brilho, livres do ressecamento e da aspereza. - - - - - MODO DE USO: Aplicar nos cabelos úmidos ou nos cabelos secos e limpos, aplicar diariamente nas pontas. - - - - - Enviamos o seu pedido o quanto antes possível! Obrigado pela preferência.', 55.8, 27.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0et6aouj6aod8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F23592934099', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
