INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993131120', 'Martelete Demolidor 5.4 KG 900W M8600B Encaixe Sextavado MAKITA MT', 'Martelete Demolidor 5,4 KG 900W M8600B Encaixe Sextavado MAKITA MT CARACTERÍSTICAS: Ideal para romper concreto, remover pisos e azulejos. Rápida troca do ponteiro. Dupla isolação. Encaixe sextavado 17mm. ESPECIFICAÇÕES: Potência: 900W Impactos por minuto: 2.900 Força: 7.2 joules Dimensões (C x L x A): 406 x 99 x 232mm Peso: 5.4kg Emissão de vibrações: 16.5 m/s² Incerteza K: 1.5m/s² ITENS QUE ACOMPANHAM Punho lateral e maleta. Código de Fábrica: M8600B-127V/ M8600B-220V Marca: Makita MT Garantia: 12 meses Fotos Martelete meramente ilustrativa. Não acompanha cinzel.', 1589.9, 1272.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdvl-lxjqtawoet7q39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1287093777%2F22993131120', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22599138846', 'Parafusadeira Furadeira de Impacto Bateria 18V com Carregador e Maleta 96pçs DHP490WVX3 MAKITA', 'Parafusadeira e Furadeira de Impacto a Bateria 18V com Carregador, Maleta e Kit de Pontas — MAKITA A Parafusadeira e Furadeira de Impacto 18V MAKITA é a ferramenta ideal para quem busca potência, precisão e versatilidade em um único equipamento. Desenvolvida com tecnologia de ponta, ela conta com motor BL (Brushless), que oferece maior autonomia da bateria, reduz o desgaste das peças e aumenta a eficiência energética — perfeita para profissionais exigentes e entusiastas do faça-você-mesmo. Projetada para suportar os desafios dos ambientes mais severos, esta furadeira é equipada com a tecnologia XPT (Extreme Protection Technology), que garante resistência à poeira e à água, ampliando sua durabilidade e vida útil. O mandril de aperto rápido facilita a troca de brocas e bits, enquanto o sistema de duas velocidades mecânicas e os 20 níveis de torque permitem ajustes precisos conforme o tipo de material e aplicação. Além de potente, é extremamente prática: possui iluminação LED integrada para áreas de baixa visibilidade, velocidade variável e função reversível, garantindo maior controle e segurança em cada operação. Seu freio instantâneo proporciona paradas rápidas e evita danos ao material ou à superfície perfurada. Acompanha maleta metálica exclusiva e um kit completo de pontas e brocas, permitindo iniciar o trabalho imediatamente em uma ampla variedade de aplicações — de alvenaria e concreto até metal, madeira e plásticos. Características técnicas Bateria: 18V (2,0Ah BLB182 inclusa) Motor: Brushless (BL) sem escovas Proteção: Tecnologia XPT – resistente à poeira e água Mandril: Aperto rápido 1,5 – 13 mm Torque máximo: 65 N·m Torque junta rígida: 50 N·m Torque junta flexível: 27 N·m Rotação (baixa): 0 – 500 rpm Rotação (alta): 0 – 1.900 rpm Impactos por minuto (baixa): 0 – 7.500 ipm Impactos por minuto (alta): 0 – 28.500 ipm Capacidades de perfuração: Aço: 13 mm | Concreto: 13 mm | Madeira: 38 mm Dimensões da Parafusadeira (C x L x A): 17,2 x 8,1 x 23,7 cm Peso: 1,4 kg Peso Bruto: 10 kg Iluminação: LED integrada Funções: Velocidade variável, reversível, freio instantâneo Garantia: 12 meses Marca: MAKITA Conteúdo incluso 1 Parafusadeira/Furadeira de Impacto MAKITA 18V 1 Bateria 18V 2,0Ah BLB182 1 Carregador rápido DCB18WA 1 Maleta metálica exclusiva Conjunto de 100 pontas e brocas: Bits Torx: T10, T15, T20, T25, T27, T30, T40 (incluindo variações H) Pozidrive: PZ0, PZ1, PZ2, PZ3 Philips: PH0, PH1, PH2, PH3 Fenda: SL4,5 / SL5 / SL5,5 / SL6,5 Allen: H4, H5, H6 Brocas para madeira: 3, 4, 5, 6, 8, 10 mm Brocas para metal: 3, 4, 5, 6, 8, 10 mm Brocas para concreto: 3, 4, 5, 6, 8, 10 mm 2 adaptadores, 2 chaves manuais, 1 trena de 3 m e 1 estilete Aplicações e segmentos Segmentos: Carpintaria, Construção Civil, Marcenaria, Metal Mecânica Materiais compatíveis: Madeira, MDF, metais, alvenaria, concreto, cerâmica, drywall, plástico e bambu Usos indicados: Perfuração, parafusamento e impacto em diversas superfícies Benefícios Maior autonomia: motor BL sem escovas otimiza o consumo da bateria. Durabilidade superior: tecnologia XPT protege contra poeira e respingos de água. Praticidade: mandril de aperto rápido e iluminação LED integrada. Versatilidade: 20 níveis de torque e duas velocidades mecânicas. Conforto e segurança: design ergonômico, rotação reversível e freio instantâneo. Kit completo: acompanha brocas, pontas, bateria, carregador e maleta metálica. A Furadeira e Parafusadeira de Impacto MAKITA 18V entrega o equilíbrio ideal entre potência, autonomia e tecnologia. Uma ferramenta indispensável para quem busca desempenho profissional e resultados precisos em qualquer tipo de aplicação. *Imagens meramente ilustrativas', 1634.9, 1559.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-821dq-mggwp3ukccug2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1287093777%2F22599138846', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699186622', 'Disco de Corte 7 x 1,6 MM Standard Com 25 Unidades NORTON', 'Disco de Corte 7 x 1,6 MM Standard Com 25 Unidades NORTON Produzido com grãos abrasivos de óxido de alumínio de alta qualidade e dureza, com aditivos que reduzem o calor gerado durante o corte. Fabricado sob alto padrão de qualidade em conformidade com as Normas Internacionais EN 12413. Indicado para corte de metais ferrosos e não ferrosos, aço inoxidável e ferro fundido. Dados Técnicos: Diâmetro do Disco: 4.1/2" (115mm); Espessura: 3/64" (1,2mm); Diâmetro do Furo: 7/8" (22,23mm); Tipo do grão: Óxido de Alumínio; Tamanho do Grão: 46; Fórmula: A 46 R BF; Centro: Reto; Rotações por minuto: 13.300 rpm; Acabamento/ Composição do acessório: Óxido de Alumínio, Resina Fenólica, Fibra de Vidro, Aço; Aplicação: Metais ferrosos e não ferrosos, aço inoxidável; Máquinas compatíveis: Esmerilhadeiras de 115mm (4.1/2"). Marca: NORTON Referência: 2608602262 Garantia: 3 Meses *Imagens Meramente Ilustrativas', 143.9, 143.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbls-lqozbe80bli22d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F20699186622', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8630865565', 'SUTIÃ DULOREN 111759 TAÇA B', 'Características: Sutiã modelador sem aro sem bojo. Com busto anatômico em tecido duplo, que acomoda e modela os seios na medida ideal. Alças fixas reguláveis largas, oferecendo maior conforto. Costas com fecho em colchetes, com três regulagens. Confeccionado em tecido elástico, produzido com fio LYCRA® Beauty. Alta sustentação aos seios e atenuando os excessos indesejáveis nas laterais. Outros detalhes: Taça B. Modo de lavagem: Lavar a mão. Não usar alvejante. Não secar em tambor. Não passar a ferro. Não limpar a seco. Composição: Corpo: 85% Poliamida e 15% Elastano.', 135.9, 135.9, NULL, 'Women Clothes > Lingerie & Underwear > Bras', 'https://cf.shopee.com.br/file/sg-11134201-22100-eygvrykbv6iv11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F8630865565', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5183216008', 'Meia 3/4 Kendall Alta Compressão Sem Ponteira', 'Características: Meia 3/4 Sem Ponteira Alta Compressão (20-30mmHg) Referência1881. Ultra Pro: Dupla Tecnologia em um único produto A Kendall, pioneira na aplicação de bacteriostáticos em seu produto, foi buscar novas tecnologias para proporcionar a você um conforto ainda maior: Nossa Pele é nossa interface com o mundo! Através da nossa pele sentimos: Temperatura Umidade Movimento do ar Todos estes fatores impactam nosso senso de conforto! A Tecnologia UltraPro, além de adaptar-se a temperatura aumentando e diminuindo a sensação de frescor dependendo do ambiente e atividades, é um agente antimicrobiano que age evitando o crescimento de microrganismos como bactérias e fungos causadores de odores desagradáveis nos artigos têxteis, proporcionando uma proteção duradoura e higiênica, conferindo a sensação de bem-estar e comodidade. Benefícios adicionais na sua meia Kendall® Máxima proteção contra fungos e bactérias Prevenção de odores desagradáveis Conforto térmico Frescor e absorve a umidade da sua pele Indicações: Antes e após cirurgias. Grandes inchaços de natureza cardíaca, renal ou hepática. Linfedema (Edema de natureza linfática). Síndrome pós traumática. TVP ( Trombose Venosa Profunda). Contra-indicações: Insuficiência arterial (dificuldade de circulação do sangue nas artérias com conseqüente obstrução caracterizada no seu grau mais extremo pela gangrena). Gangrena (morte tecidual da extremidade com conseqüente mudança de coloração da pele, chegando a ficar negra e mal cheirosa). Infecções cutâneas (proliferação de fungos ou bactérias, causando alterações de coloração ou feridas com localização entre os dedos ou demais territórios das pernas. Exemplo: Erisipela – fase aguda, frieiras e ferimentos purulentos – com presença de pus). Dermatoses úmidas (lesões da pele com secreção acentuada). Enxertia de pele em processo de cicatrização nos membros inferiores (pacientes com queimaduras graves ou feridas que necessitam de cobertura de pele de outra região, numa fase recente – até 30 dias). Composição: 74% Poliamida e 26% Elastano', 132.9, 132.9, NULL, 'Women Clothes > Lingerie & Underwear > Panties', 'https://cf.shopee.com.br/file/sg-11134201-22110-qqlep8k2wqjva3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F5183216008', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198020147', 'Câmera de Segurança Babá Eletrônica com 3 Antenas Visão Noturna e Controle via App Áudio e Microfone', 'Câmera de Segurança Babá Eletrônica OI-2006 com 3 Antenas, Wi-Fi, Visão Noturna e Controle via App Garanta a segurança da sua casa com a Câmera de Segurança Babá Eletrônica OI-2006. Ideal para monitoramento de ambientes internos e externos, ela oferece visualização superior via Wi-Fi, notificação de movimento e gravações em alta resolução. Com resolução de 1.3 MP (720p) e visão noturna de até 10 metros, esta câmera é a escolha perfeita para quem busca um sistema de vigilância completo e acessível. Além disso, a Câmera OI-2006 possui rotação de 355° e um ângulo de 120°, garantindo uma cobertura ampla. Ela também é resistente a quedas e suporta cartão microSD de até 32GB para gravações contínuas. Com áudio bidirecional, você pode se comunicar diretamente pelo aplicativo Yoosee, que é compatível com Android e iOS. PRINCIPAIS CARACTERÍSTICAS: - Visão Noturna: Até 10 metros com LEDs infravermelhos. - Rotação 355° e Ângulo de 120°: Cobertura panorâmica completa. - Áudio Bidirecional: Ouça e fale com quem está no ambiente. - Resolução de 960p (1280×960): Imagens nítidas em alta qualidade. - Compatibilidade com Yoosee: Controle total pelo app para Android e iOS. - Instalação Simples: Conecte via Wi-Fi e configure facilmente pelo app. - Resistente a quedas: Maior durabilidade. - Consumo baixo de energia: Apenas 5W. ESPECIFICAÇÕES TÉCNICAS: - Entrada de vídeo: H.262 e MJPEG - Sensor de Imagem: CMOS 1/mega pixels - Lente: Lente Glall - Conexão sem fio: IEEE 802.11b/g/n (WPS) - Ângulo de PAN/TILT: Horizontal 355° / Vertical 120° - Visão Noturna: Até 10 metros com LEDs infravermelhos - Áudio: Bidirecional (microfone e alto-falante embutidos) - Conexão Ethernet: 10/100Mbps RJ45 - Consumo de energia: 5W - Alimentação: DC5V/2A (bivolt 110V/220V) CONTEÚDO DA EMBALAGEM: - 1x Câmera de Segurança OI-2006 - 1x Fonte de Alimentação Bivolt (110V – 220V) - 1x Manual de Instruções - 1x Suporte de Fixação - 2x Buchas e Parafusos Atenção: A instalação é fácil e rápida via Wi-Fi, com suporte para o aplicativo Yoosee disponível tanto para Android quanto para iOS.', 249.99, 165.99, NULL, 'Cameras & Drones > Security Cameras & Systems > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhrn7e033imae0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1333507062%2F23198020147', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692683392', 'Kit com 3 Cuecas Slip Zorba 0764', 'Características: Cueca Zorba Slip Max Elástico aparente personalizado com logo da marca Bojo forrado Possui a tecnologia Go Tagless, sem etiquetas costuradas, não irrita a pele Ajuste perfeito ao corpo, extremo conforto Modo de Lavagem: Lavar com temperatura máxima de 30°C Não usar alvejantes Não secar em secador rotativo Passar com temperatura máxima de 110°C Não limpar a seco Cores: Preto: Todas preto Cinza: Todas cinza Marinho: Todas marinho Branco: Todas branco Composição: Cor Cinza: 88% Algodão e 12% Poliéster Demais Cores: 100% Algodão', 100.7, 100.7, NULL, 'Men Clothes > Innerwear & Underwear > Underwear', 'https://cf.shopee.com.br/file/sg-11134201-7rbm4-lp85lnj96aw5ac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401430924%2F22692683392', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099384730', 'Spray Metal Protection Preto Fosco Metálico 312g Rust Oleum', 'O Spray da Rust-Oleum Metal Protection é um esmalte protetor anticorrosivo que pode ser aplicado sobre o metal oxidado ou para prevenir a oxidação de objetos e superfícies metálicas de interior e exterior. O produto oferece grande proteção contra intemperismo e resistência à umidade. Inclui uma válvula confortável e tecnologia de 360 ​​graus que permite pintar em qualquer ângulo. Metal Protection fará com que seu projeto seja mantido como novo por mais tempo.', 90.9, 90.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/sg-11134201-81zwa-mn7biwdnowzsb3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1344829093%2F20099384730', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21099556088', 'Pinos para Pinador Pneumático F-50 com 5000 Peças MTX', 'Pinos para Pinador Pneumático F-50 com 5000 Peças 576209 MTX Os Pinos para Pinador MTX 18GA 576209 são compatíveis com qualquer pinador pneumático projetado para fixações de 50 x 1,25 x 1 mm. O comprimento aumentado para 50 mm torna-os ideais para conectar peças de madeira, aglomerado, MDF e metal de espessura considerável, ampliando significativamente o alcance de projetos possíveis, desde construções residenciais a trabalhos artesanais detalhados. Fabricados em aço carbono de alta qualidade, os Pinos para Pinador MTX 18GA 576209 são projetados para resistir a quebras, assegurando que as estruturas conectadas sejam extremamente confiáveis. Esta durabilidade é crucial para profissionais e entusiastas que buscam resultados de longa duração em seus projetos, proporcionando segurança e estabilidade onde é mais necessário. O revestimento anticorrosivo de cada pino oferece uma defesa robusta contra a destruição, mesmo sob condições de alta umidade. Esta proteção é indispensável para projetos expostos a elementos naturais ou em ambientes propensos a umidade, garantindo a integridade e a aparência das fixações ao longo do tempo. A embalagem contendo 5000 pinos garante um suprimento extenso, ideal para a realização de grandes volumes de trabalho sem a necessidade de reabastecimento constante. Esta quantidade é particularmente vantajosa para profissionais envolvidos em projetos de grande escala ou para entusiastas do faça-você-mesmo que apreciam ter um estoque adequado à mão para futuras criações. Os Pinos para Pinador MTX 18GA 576209 representam uma solução de fixação superior, adequada para uma ampla variedade de aplicações. Seu design robusto, aliado à proteção anticorrosiva e à embalagem econômica, os torna uma escolha excelente para qualquer projeto que exija fixações confiáveis e de alta qualidade. Seja em construções estruturais, montagem de móveis ou trabalhos artesanais, esses pinos são projetados para garantir que cada fixação seja realizada com a máxima eficácia, assegurando resultados duradouros e esteticamente agradáveis. VANTAGENS E BENEFÍCIOS Compatibilidade Universal: Os pinos são projetados para funcionar com qualquer pinador pneumático padrão de 50 x 1,25 x 1 mm, tornando-os uma solução versátil para diferentes equipamentos e aplicações. Resistência e Durabilidade: Fabricados em aço carbono de alta qualidade, oferecem excelente resistência contra quebras, garantindo fixações seguras e confiáveis, ideais para projetos estruturais ou de alto desempenho. Revestimento Anticorrosivo: Cada pino é tratado com proteção contra corrosão, garantindo durabilidade mesmo em ambientes úmidos, sendo especialmente útil para trabalhos em exteriores ou locais expostos a intempéries. Tamanho Ideal para Diversas Aplicações: Com 50 mm de comprimento, são perfeitos para unir materiais como madeira, MDF, aglomerado e até metais leves, atendendo a uma ampla gama de necessidades em carpintaria, construção e marcenaria. DADOS TÉCNICOS Tipo: Pino F-50 Comprimento: 50 mm Espessura: 1,25 mm Largura: 1 mm Quantidade na embalagem: 5000 Garantia: 3 Meses Referência: 576209 Marca: MTX * Imagens meramente ilustrativas.', 81.9, 81.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rffn-m33yy3mw2zrnba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1287093777%2F21099556088', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47106682169', 'Kit 2 Displays Charge Bar Barrinha de Proteína 12 Unidades 45g Cada - Nutrata', 'A Nutrata e a Nestlé se unem em uma collab que nasce da busca constante por inovação e qualidade. O Charge Nutrata reúne chocolate ao leite, caramelo e amendoim com proteínas de alta qualidade. Disponível na versão de 45g, oferece 11g de proteína provenientes do whey protein, sem adição de açúcares e zero glúten, o produto foi desenvolvido para preservar sabor e textura característicos do Charge®, ao mesmo tempo em que atende às necessidades de consumidores que buscam uma fonte funcional de proteínas para o consumo diário. ------------------------------------------------------------------------------------------ Posso consumir em meu processo de emagrecimento? ------------------------------------------------------------------------------------------ Sim, pode! As barras de proteína são uma excelente opção para os dias mais corridos, em que precisamos de algo prático, mas ainda nutritivo e proteico. ---------------------------- Contém lactose? ---------------------------- Sim, as barras de proteína possuem whey protein em sua composição. Se você tem algum grau de intolerância ou restrição, é importante considerar essa informação antes do consumo. -------------------------- Contém glúten? -------------------------- Celíacos e intolerantes podem consumir a barra Charge Nutrata, pois ela não contém glúten na composição e não há risco de contaminação cruzada durante o processo de fabricação.', 359.8, 239.9, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Breakfast Bar', 'https://cf.shopee.com.br/file/br-11134207-820lr-mmrj0fx97evb68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389266749%2F47106682169', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42668094153', 'Sandália Feminina Salto Baixo Geométrico Enfeite Dourado Conforto Premium Moda Verão Casual Luxo', 'Sandália Feminina Salto Confortável Elegante com Enfeite Exclusivo – Pronta Entrega Forma Normal – Peça seu tamanho de uso! Altura do Salto: 6 cm Envio Rápido: Pedidos feitos até as 11h são enviados no mesmo dia! Fotos Reais do Produto Tabela de Medidas: 34 = 23,3 cm 35 = 24,0 cm 36 = 24,8 cm 37 = 25,3 cm 38 = 25,8 cm 39 = 26,5 cm Detalhes do Produto: #Design moderno e elegante, perfeito para mulheres que buscam conforto sem abrir mão do estilo. #Enfeite exclusivo e sofisticado no cabedal, que garante charme único. #Tiras macias que se ajustam ao pé, proporcionando praticidade e conforto. #Ideal para ocasiões especiais, trabalho ou dia a dia com estilo. #Especificações Técnicas: #Solado: Microgel antiderrapante #Salto: Taça grosso pintado #Altura do salto: 6cm #Palmilha: Espuma macia e confortável #Material: Sintético premium #Leve e durável Sobre a Stessy Shoes: Há 16 anos no mercado, a Stessy Shoes é referência em qualidade, conforto e elegância. Com produção própria e designs exclusivos, oferecemos calçados modernos, sofisticados e acessíveis. Garanta já sua sandália e receba em casa rapidinho!', 199.9, 99.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meemb15pefpc6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F410637624%2F42668094153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
