INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394665786', 'Cruzeta Cardan Para Kia Bongo K2500 8V 2005 Até 2012', 'Cruzeta Cardan Para Kia Bongo K2500 8V 2005 Até 2012 **** PEÇA NOVA ********* GARANTIA E NOTA FISCAL ***** PRODUTO:Cruzeta Cardan Para Kia Bongo K2500 8V 2005 Até 2012 MARCA:ASH CODIGO:BCZ21001 ITENS INCLUSOS: 01 UNIDADE CRUZETA CARDAN COMPATIVEL COM: KIA / BONGO K2500 2.5 8V / 2005 / 2012 / 8v / 2,5 Conheça a MRA Auto Peças Fundada em 1998 na cidade de Ribeirão Preto/SP, a MRA Auto Peças consolidou-se ao longo dos anos como uma referência no setor automotivo, oferecendo qualidade, confiança e atendimento especializado. Com mais de duas décadas de experiência no mercado, somos especialistas em peças para VANS, UTILITÁRIOS, veículos importados e SUVs, atendendo com excelência tanto clientes particulares quanto oficinas e frotistas. Nossa matriz está localizada em Ribeirão Preto/SP, e contamos ainda com filiais nas cidades de Araraquara e Franca, ampliando nosso alcance e fortalecendo nosso compromisso com a agilidade na entrega e o suporte técnico qualificado. Na MRA Auto Peças, você encontra as melhores marcas, preços competitivos e um time pronto para oferecer as soluções certas para o seu veículo. MRA Auto Peças – Tradição, confiança e qualidade desde 1998.', 65.18, 65.18, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-821g8-mh6cqqjtoj60f2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1223398266%2F22394665786', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11197510758', 'Par Lâmpada H7 Osram Ultra Life 3200k Garantia 4 anos', 'PAR LÂMPADA OSRAM H7 ULTRA LIFE 3200K As lâmpadas automotivas OSRAM ULTRA LIFE são favoritas quando se trata de durabilidade. Elas impressionam com tempo de vida útil até quatro vezes mais longo quando comparadas à lâmpadas halógenas padrão e duram até 100.000 km (com uma média de milhagem anual de 14.259 km e 60% de iluminação) A OSRAM fornece uma garantia de 4 anos para a lâmpadas de farol confiáveis ULTRA LIFE. Além disso, essas lâmpadas automotivas ULTRA LIFE possuem um design moderno com uma cúpula em prata. Eles são, portanto, ideais para motoristas frequentes ou pessoas que usam luzes diurnas e também podem ser usados em faróis de vidro transparente. ESPECIFICAÇÕES TÉCNICAS: -Lâmpada de maior vida útil: até 4 vezes mais longa comparado a lâmpadas halógenas padrão -Encaixe: Lâmpada H7 -Temperatura de Cor: 3200K -Tensão de Operação: 12V -Potência de Saída: 55W -Maior durabilidade para ciclos de reposição mais longos -Lâmpada Certificada pelo INMETRO CONTEÚDO DA EMBALAGEM: -02 Lâmpadas H7 Ultra Life IMPORTANTE: -Garantia de 4 anos -Valor do Par -Imagens Meramente Ilustrativas -Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto', 124.83, 124.83, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhj85ff7w1s615', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F832639503%2F11197510758', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
