INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18718202840', 'Kit Cobre Leito Colcha Casal 3 Peças Boutis Estampada Dupla Face Porta Travesseiro Aba Americana', 'Transforme seu quarto em um espaço acolhedor e cheio de personalidade com o Kit Cobre Leito Boutis Estampada. Este conjunto foi pensado para oferecer conforto e beleza, trazendo leveza ao seu ambiente. O tecido de alta qualidade, com uma textura suave ao toque, complementa o design estampado, criando uma harmonia perfeita com qualquer estilo de decoração. É o detalhe que faltava para deixar seu quarto ainda mais especial, sem abrir mão da praticidade no dia a dia. Especificações do Produto: Colcha Dupla Face: 2,10m x 2,30m Porta Travesseiros: 2 unidades de 50cm x 70cm com Aba Americana Composição: Tecido: 100% Poliéster de alta qualidade Destaques do Produto: Durabilidade Prolongada: O tecido resistente garante uma longa vida útil, mesmo com o uso diário. Conforto e Praticidade: O poliéster de alta qualidade é macio ao toque, fácil de lavar e de secagem rápida, perfeito para uma rotina corrida. Elegância Versátil: A colcha estampada e as fronhas com aba americana adicionam um toque de sofisticação e estilo ao seu quarto. Ideal Para: Quem busca uma decoração de quarto elegante e versátil. Pessoas que valorizam a durabilidade e a facilidade de manutenção dos tecidos. Presentes especiais para casamentos, aniversários ou qualquer ocasião que mereça um toque especial. Atenção: As cores do produto podem sofrer pequenas variações devido à configuração da tela do seu dispositivo.', 194.9, 114.9, NULL, 'Home & Living > Bedding > Blankets, Comforters & Quilts', 'https://cf.shopee.com.br/file/b5485deb59ebcb37684f96a8a3abd74e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316749752%2F18718202840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
