INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098228798', 'Kit De Filtros VW Kombi 1.4 Flex Tecfil Original', 'Kit De Filtros VW Kombi 1.4 Flex Tecfil Original Bem Vindo a loja oficial da VGFC DISTRIBUIÇÃO! A satisfação dos nossos clientes é a nossa prioridade! Retire suas dúvidas antes de realizar a compra! Filtros tecfil 1ª linha, maior fabricante de filtros do continente - Qualidade e Desempenho para Seu Veículo. Se você é um proprietário de veículo que preza pela manutenção e desempenho do motor, os filtros Tecfil são a escolha ideal. Nossos filtros são projetados para oferecer máxima eficiência, garantindo proteção e durabilidade para o motor do seu carro. Compativel com anos: 2006 2007 2008 2009 2010 2011 2012 2013 2014 Conteúdo do Kit: - 01 Filtro de óleo lubrificante - TM2 Tecfil - 01 Filtro de combustível - GI50/7 Tecfil - 01 Filro de ar - ARS2868 Tecfil Por que a Tecfil? - Qualidade Superior: - Desempenho Confiável: - Compatibilidade Garantida: Benefícios de Usar Filtros Tecfil: - Proteção do Motor: - Economia de Combustível: - Menor Desgaste: IMPORTANTE: Troque os filtros do seu veículo a cada troca de óleo, conforme recomendado pelo fabricante; Caso tenha interesse, temos todas as opções de kits completos para troca de óleo e higienização de ar condicionado, será um prazer receber a sua visita na nossa loja; Retire suas dúvidas antes de realizar a compra! ATENÇÃO: - Não nos responsabilizamos pelo mau uso ou instalação indevida do produto. - Recomendamos que a instalação seja realizada por um profissional especializado. - Algumas imagens ( fotos ) são meramente ilustrativas. VGFC AUTO PARTS É UMA EMPRESA DO GRUPO ZT DIESEL QUE ATUA NO RAMO DE AUTO PEÇAS E REPARAÇÃO VEICULAR DESDE 1993.', 111.0, 111.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6cke4km6hl16c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1022037284%2F22098228798', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698355370', 'Car 80 Descarbonizante Car80 Limpa Bico Tbi Carburadores', 'DESCARBONIZANTE CAR80 LIMPA BICOS CARBURADORES TBI Descarbonizante de motores (automóveis e motos). Alta tecnologia em uma só fórmula. O CAR 80 foi desenvolvido e formulado para proporcionar o máximo desempenho em motores a etanol, gasolina, flex ou gás natural veicular (GNV). CAR 80 limpa completamente, externa e internamente os componentes do sistema de alimentação do motor, removendo óxidos e dissolvendo gomas e vernizes que, com o tempo, obstruem os canais e furos de passagem do sistema. APLICAÇÃO: Limpeza de componentes carbonizados. Limpeza de bicos injetores. Limpeza do sistema de admissão (corpo de borboleta, motor de passo, coletor de admissão e válvulas de admissão). Limpeza de carburador. ATENÇÃO - A MOVE AUTOPARTS não se responsabiliza pelo mau uso ou instalação indevida do produto, sempre recomendamos que a instalação seja feita por um profissional especializado. - Imagens meramente ilustrativas.', 38.5, 38.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m7wbr8p2kdm960', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1463823458%2F23698355370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
