INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43577462007', 'Prendedor de papel clip resistente caixa 12 un grande 51 mm para grandes documentos', 'Prendedor de papel grande 51 mm para organizar volumes altos Tipo de embalagem: Caixa O que contém: 12 prendedores de papel grandes 51 mm - Prendedor de papel grande 51 mm - Prende até 240 folhas - Aço resistente com proteção contra ferrugem - Fixação firme e segura - Caixa com 12 unidades - Ideal para grandes documentos Diferenciais e uso O prendedor de papel clip resistente 51 mm foi desenvolvido para organizar grandes volumes de documentos com firmeza e segurança. Fabricado em metal resistente, mantém os papéis bem presos sem danificar as folhas. A proteção contra ferrugem garante maior durabilidade no uso diário. Ideal para escritório, escola ou estudos, é perfeito para organizar relatórios, apostilas e arquivos mais espessos. Compacto e fácil de transportar, pode ser levado na bolsa ou pasta para uso sempre que necessário. Sobre a marca: Cromus Deli Organização, estilo e funcionalidade no seu dia a dia. A Cromus Deli oferece materiais de escritório, escolar e itens de papelaria com design moderno, pensados para facilitar a rotina com praticidade e visual atual. A marca nasce de uma parceria internacional que une qualidade, praticidade e criatividade, entregando produtos confiáveis para uso diário, em casa, na escola ou no trabalho.', 75.92, 75.92, NULL, 'Stationery > School & Office Equipment > Clips, Pins & Tacks', 'https://cf.shopee.com.br/file/sg-11134201-81zvx-mim7m1jj8wzl41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908137538%2F43577462007', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
