INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49209645196', '(Carry by Lovito) Bolsa de Ombro Pequena Casual com Fecho Metálico Preta Bolsa de Ombro Pequena Feminina LR36E031', '✅DESTAQUES -❤️Fivela de metal -❤️Ideal para sogra -❤️Clássica e versátil -❤️Para ocasiões especiais -❤️Para o trabalho ✅DESCRIÇÃO Estampa: Lisa Estilo: Casual Tipo de fecho: Fecho com trava Estrutura da bolsa: Compartimento principal Tipo de bolsa: Bolsa saco Material: PU Região de origem: China Continental ✅INSTRUÇÕES DE CUIDADO 1. Mantenha materiais como couro, sintéticos e acessórios de metal longe da exposição direta ou excessiva à umidade, líquidos, calor e luz solar. A exposição a esses elementos pode causar desgaste permanente. 2. Atrito excessivo e contato com substâncias oleosas, como cosméticos ou solventes, podem causar danos, desbotamento ou transferência de cor para roupas e superfícies de cores claras. 3. Use um pano macio e úmido para limpar manchas, poeira ou sujeira. 4. Quando não estiver em uso, guarde os itens em uma caixa ou saco protetor em local fresco e seco. ✅O PACOTE INCLUI 1 Bolsa', 107.9, 75.5, NULL, 'Women Bags > Crossbody & Shoulder Bags', 'https://cf.shopee.com.br/file/sg-11134201-823or-mp0mju3dtvymec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1618672347%2F49209645196', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53253449965', 'Wetesto Com Feno Grego Pote Com 60 Cápsulas Wefit', 'Wetesto com Feno Grego – 60 Cápsulas | Wefit Wetesto com Feno Grego Wefit é um suplemento alimentar em cápsulas formulado com extrato de feno grego, ingrediente tradicionalmente utilizado na rotina nutricional. Desenvolvido para complementar a alimentação diária de forma prática, é ideal para quem busca organização e constância no consumo. - O formato em cápsulas facilita o uso no dia a dia, permitindo levar e consumir em diferentes momentos da rotina. Diferenciais do Produto: - Contém feno grego na formulação - 60 cápsulas por embalagem - Suplemento alimentar de uso diário - Prático e fácil de consumir - Ideal para complementar a alimentação Modo de Consumo: - Consumir conforme a recomendação indicada na embalagem ou orientação de um profissional de saúde. Ingredientes: - Feno grego (Trigonella foenum-graecum) e excipientes. - Verificar a composição completa na embalagem. Informações Importantes: - Suplemento alimentar - Este produto não é medicamento - Não substitui uma alimentação equilibrada e hábitos de vida saudáveis Conservação: - Manter em local fresco, seco e ao abrigo da luz. Após aberto, manter a embalagem bem fechada.', 59.9, 38.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-81ztw-mik7pe4plxxfc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662618933%2F53253449965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
