INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897979244', 'Calça De Goleiro Profissional Poker VI Futebol Campo Futsal', 'Seja bem-vindo à All-in Sports!Nossos produtos são originais, adquiridos diretamente da Poker, somos revendedores autorizados. Por quê adquirir a Calça de Goleiro Poker VI? - Espuma de alta densidade "26". Desenvolvida para suportar altos impactos; - Tecido Liso com trama, que proporciona toque macio e excelente caimento; - Gramatura de 165 g/m², tornando suas defesas menos dolorosas e permitindo alta durabilidade do produto; - Calça acolchoada nas laterais e joelhos com viés contrastante, oferecendo grande proteção nas laterais do quadril e nos joelhos; - Possui Elástico com cordão interno para ajuste; - Grandes Goleiros usam e recomendam, como: Weverton (Palmeiras), Hugo Souza (Flamengo), Éverson (Atlético-MG), Jandrei (São Paulo) e muitos outros! Medidas aproximadas por tamanhos: P - 42 cm Cintura X 109 cm Comprimento M - 44 cm Cintura X 110 cm Comprimento G - 45 cm Cintura X 113 cm Comprimento GG - 50 cm Cintura X 114 cm Comprimento Composição do tecido: 100% Poliéster Acompanha:- Uma Calça de Goleiro Poker VI (do tamanho de sua preferência); - Nota Fiscal. Produto Original / Lacrado / Pronta Entrega / Despacho ágil. VALOR PROMOCIONAL POR TEMPO LIMITADO! APROVEITE!', 149.89, 149.89, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Bottoms', 'https://cf.shopee.com.br/file/br-11134207-820lg-mn2w15qfek1tb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F762356165%2F21897979244', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18998483663', 'Garrafa Térmica VG 750ml Preta Invicta', 'A Garrafa Térmica VG Invicta é a escolha ideal para quem busca elegância e desempenho térmico no dia a dia. Com design moderno, ela adiciona charme e sofisticação à sua mesa, sendo perfeita para conservar bebidas quentes ou frias por muito tempo. Projetada para uso doméstico, a VG Invicta conta com uma ampola de vidro, que garante excelente isolamento térmico, preservando o sabor e a temperatura das suas bebidas. Prática e funcional, une eficiência, estilo e qualidade em um só produto. CaracterísticasDesign moderno e sofisticado: Ideal para compor sua mesa com estilo.Ampola de vidro: Conservação térmica eficiente e preservação do sabor.Cor: PretaCapacidade: 750mlUso prático e funcional: Perfeita para o dia a dia.Manutenção da temperatura: Mantém líquidos quentes ou frios por mais tempo. Composição Fabricada com ampola de vidro e materiais de alta qualidade, garantindo excelente isolamento térmico e durabilidade.', 38.9, 38.9, NULL, 'Home & Living > Kitchenware > Tea, Coffee & Bartending Equipments', 'https://cf.shopee.com.br/file/sg-11134201-8259z-mqw6qljx37yidc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F859051456%2F18998483663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13831821679', 'Paralama Dianteiro Moto Honda Nxr 150 Bros 2009 Até 2012 Pro Tork Modelo Original', 'As carenagens e peças plásticas Pro Tork são produzidas nos moldes das peças originais da moto, descartando qualquer tipo de adaptação. Fabricadas em ABS 100% virgem, são extremamente resistentes aos raios UV, tornando-se assim o melhor custo-benefício do mercado. Características: - Marca: Pro Tork; - Modelo: Original; - Tonalidade de cores semelhante ao original; - Moto compatível: NXR 150 Bros 2009 a 2012 (Confira a relação de cores e anos abaixo). Aplicação: - Amarelo Trancoso: 2009; - Laranja: 2011 e 2012; - Laranja Canoa: 2010; - Preto: 2009, 2010, 2011 e 2012; - Vermelho Caucaia: 2009 e 2010; - Vermelho Clívia: 2011 e 2012. Atenção! Devido ao desgaste da pintura da motocicleta com o passar do tempo, pode haver uma pequena divergência na tonalidade das cores. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada. Sportbay - Seu Esporte, Nossa Paixão.', 115.68, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9zshot77fw97b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F13831821679', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197655901', 'Retentor Bacteriológico Master Para Purificador Europa', 'Retentor Bacteriológico Master Para Purificador Europa Retentor Bacteriológico Master Para Purificador EuropaDescriçãoAcrescente mais desempenho ao seu Purificador de água Europa Da Vinci Ice, Summer Line e Noblesse com o Módulo Retentor de Bactérias MRB Master. O Módulo Retentor de Bactérias Máster (MRB Máster) é composto de uma câmara contendo membranas de fibra oca sobrepostas, com mais de 400 bilhões de microporos capazes de reter coliformes totais, coliformes fecais, bactérias patogênicas e protozoários. EspecificaçõesMarca: Europa Modelo: HF Produto: Retentor Bacteriológico Master Para Purificador Europa Altura: 19 cm Peso do Produto: 0.18 kg Cor: Branco Uso Indicado: Purificador de água Summer Largura: 7 cm Adquira agora o Retentor Bacteriológico Master Para Purificador Europa', 368.9, 368.9, NULL, 'Home Appliances > Kitchen Appliances > Water Filters, Coolers & Dispensers', 'https://cf.shopee.com.br/file/sg-11134201-7rcc1-lt48m58qrowea8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F763778640%2F19197655901', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
