INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58204359809', 'Fixação Para Lavatório Com Coluna Roca', 'SOBRE O PRODUTO A fixação para lavatório com coluna da Roca é uma escolha confiável e prática para a instalação de lavatórios com coluna. Com design discreto e funcional, garante estabilidade e segurança ao lavatório, evitando movimentos indesejados. Fabricada pela renomada marca Roca, essa fixação é feita com materiais de qualidade, assegurando durabilidade e resistência. Compatível com diversos modelos de lavatórios com coluna, é um acessório indispensável para um banheiro bem montado e seguro. Permite uma instalação fácil e eficaz, complementando o visual do seu ambiente. INFORMAÇÕES TÉCNICAS - Altura (cm): 3 - Comprimento (cm): 1 - Largura (cm): 1 - Cor: Cromado SOBRE A FABRICANTE Na Roca você encontra a solução completa para equipar o seu banheiro, cozinha e área de serviço. São produtos que imprimem design, funcionalidade e tecnologia para compor projetos residenciais, corporativos, hoteleiros e hospitalares.', 30.9, 30.9, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/sg-11134201-82624-mk3vuji0t8g679', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1225401015%2F58204359809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19597684728', 'Pneu Itaro Aro 18 Performax 225/60R18 104H XL', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a marca Itaro A Itaro nasceu para motoristas viverem novas histórias - em duas ou quatro rodas. Desenvolvida nas grandes fábricas asiáticas, a marca é homologada nos principais mercados da Europa e América, como o Brasil. Seus pneus foram pensados em centros de pesquisa e desenvolvimento de países como China, Paquistão e Tailândia, que estão entre os maiores do mundo. Com presença exclusiva na PneuStore, a Itaro oferece soluções para carros de passeio, SUVs, caminhonetes, motos e caminhões, com excelente qualidade e custo que ajudam motoristas a viverem novos capítulos todos os dias.', 662.6, 616.22, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd5n-lvdpt91bdj0b5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F19597684728', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18497680414', 'Pneu Pirelli Aro 16 Scorpion HT 265/70R16 112T', 'Marca: PIRELLI Modelo: SCORPION HT Medida: 265/70R16 Largura: 265 Perfil: 70 Tamanho de Aro: 16 Índice de peso: 112 - 1120 kg, 112 Índice de velocidade: T - 190 km/h, T Tipo de Veiculo: SUV Tipo de terreno: AT RunFlat: Não Sidewall: BSW LETRAS PRETAS Extra Load: Não Desenho: Simétrico UTGQ: N/A Adesão à àgua: C Eficiência energética: B Ruído externo: 73 *Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Você busca por um pneu eficiente tanto na terra quanto no asfalto? Então o Pirelli Scorpion HT é a resposta para a sua dúvida. Desenvolvido para rodar a maior parte do tempo no asfalto (70%), o modelo vai bem em trilhas leves (30%), sendo perfeito para você que usa Picapes e ama versatilidade. Com desenho moderno e otimizado da banda de rodagem, o Pirelli Scorpion HT conta com novos compostos para diminuir a resistência ao rolamento. Essa composição ajuda na economia de combustível. Além disso, é ótimo para o dia a dia e viagens, pois seu design evita que o ruído do atrito com o asfalto entre na cabine. Sobre a marca Pirelli A Pirelli nasceu na Itália há mais de 100 anos, em Milão. Com longa tradição na construção de pneus, a marca produz soluções para carros, motos, tratores, caminhões e ônibus e possui fábricas espalhadas pelo mundo. A Pirelli é a atual fornecedora de pneus da Fórmula 1, a principal categoria do automobilismo mundial, e possui longa tradição em pneus de alto desempenho.', 1287.37, 1184.39, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rdwt-lxlqvp2ni6w006', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F18497680414', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
