INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21497668015', 'Estabilizador Ragtech Side Laser 1000VA Trivolt 60Hz Preto 20SDL5379 TI', 'Estabilizador Ragtech 1000VA 20SDL5379 TI 60HZ preto 4 Tomadas Trivolt ENTR. 115-127-220V SAI O único estabilizador do mercado especialmente projetado para proteger impressoras laser , fotocopiadoras, além dos computadores e equipamentos de informática em geral. Não permite distúrbios na saída provocados pelos picos de corrente comuns nas impressoras laser , evitando desgaste prematuro provocado pelos estabilizadores convencionais. Incorpora ainda recursos avançados como power monitor [medidor de potência], powerlook [autodesligamento programável por consumo] e true full range [estabiliza integralmente de 92V a 258V. Características: - Marca: Ragtech - Modelo: 5379 Especificações: - Sinalização Sonora: Indicação audível de níveis críticos - Fast RMS: regulação precisa com resposta ultrarrapida - Proteção Eletrônica: Autodesligameno por subtensão, sobretensão sobrecarga, curto circuito, e sobretemperatura - Microprocessado: Precisão Digital no controle de energia - Tecnologia Laser Sense: Projetado para impressora laser - Tensão Nominal: Trivolt (115V - 127v ou 220V) - Faixa de tensão de entrada: 92V a 160v (em rede 115v) / 160v a 258v (em rede 220v) - Regulação de Saída: +/- 6% - Frequência de Operação (Hz): 60 - Tempo de resposta: = 170% - Proteção Contra Surtos de Tensão: Varistor Dimensões e Peso: - Dimensões: 23X 15 X 22cm - Peso: 5kg Conteúdo da Embalagem: - Estabilizador Ragtech 1000VA', 478.45, 428.37, NULL, 'Computers & Accessories > Desktop & Laptop Components > UPS & Stabilizers', 'https://cf.shopee.com.br/file/sg-11134201-7rd6y-luje3ggyc46d92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F21497668015', NULL, NULL, '2026-07-28T02:11