INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14696423843', 'Quebra-Cabeça Infantil 6 Peças de Madeira Reflorestada de Encaixe Fazendinha +3 anos Xalingo - 17210', 'A montagem de um quebra-cabeça de encaixe para os pequenos é fascinante. Com a observação das imagens coloridas e as formas de cada peça, as crianças se inspiram, trabalhando a imaginação e a criatividade, bem como, desenvolvem o raciocínio lógico e a coordenação motora fina de forma lúdica. O quebra-cabeça de Encaixe Fazendinha Xalingo é composto de 6 peças em madeira para encaixar o contorno correspondente no tabuleiro. Os pequenos podem se familiarizar com os bichinhos que compõe a fazendinha. Indicado para crianças a partir dos 3 anos, o objetivo da brincadeira é a criança entender o contexto da cena e através das formas das peças soltas associar o encaixe no local correto. É diversão e aprendizado no mesmo produto. Características: - Marca: Xalingo - Modelo: 17210 *Imagens Meramente Ilustrativas Especificações Técnicas: - Inmetro: CE-BRI/IQB 005923 - Idade Recomendada: A partir de 3 anos - Dimensões Aproximadas (AxLxC) Tamanho da cena: 32 x 21 cm - Quantidade de peças: 6 peças - Material: Madeira Reflorestada Conteúdo da Embalagem: - 1x Quebra-cabeça de Encaixe Fazendinha', 48.74, 48.74, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-23020-1eqg2b8l0lnv7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371036439%2F14696423843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
