INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21799592479', 'Nivelador Porcelanato Espaçador Piso 2mm - 1000 Pçs', 'O Nivelador Porcelanato Espaçador Piso 2mm - 1000 Pçs da marca Cortag é perfeito para quem busca um acabamento impecável em seus projetos de revestimento. Com sua espessura de 2mm, ele garante um nivelamento preciso entre as peças, proporcionando um resultado final uniforme e profissional. Com um modelo de 20mm, esse espaçador é ideal para a instalação de porcelanatos, garantindo que as peças fiquem alinhadas e sem irregularidades. Sua quantidade de 1000 peças é mais do que suficiente para cobrir grandes áreas, tornando-o uma opção econômica e prática. Além disso, o Nivelador Porcelanato Espaçador Piso 2mm - 1000 Pçs é novo, garantindo a qualidade e durabilidade do produto. Seja você um profissional da construção ou um entusiasta do DIY, esse espaçador é indispensável para obter um resultado perfeito em seus projetos. Invista no Nivelador Porcelanato Espaçador Piso 2mm - 1000 Pçs da marca Cortag e tenha a certeza de um acabamento impecável em seus revestimentos. Garanta já o seu e transforme seus ambientes com praticidade e qualidade.', 364.02, 271.97, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-7rbn5-m5im4fdpgx567c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328278916%2F21799592479', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
