INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199284536', 'Pneu Aro 15 Firestone 195/65 R15 91H BL F-600', 'Pneu Aro 15 Firestone 195/65 R15 91H BL F-600 Sobre a marca: A Firestone é uma marca de pneus da Bridgestone, a maior fabricante de pneus do mundo. A empresa nasceu em Ohio, nos Estados Unidos no ano de 1900. Com mais de 100 anos de experiência e história, a empresa preza pela qualidade dos produtos, serviços e tecnologia. Informações Adicionais: - Marca: Firestone - Modelo: F-600 - Medida: 195/65 R15 - Largura: 195mm - Perfil: 65% - Aro: 15 - Índice de carga: 91 - 615 kg - Índice de velocidade: H - 210 km/h - Desenho: Assimétrico - Tipo de construção: Radial - Tipo de terreno: HT - Runflat: Não - Extra Load: Não - Protetor de bordas: Não - Sidewall: Letras Pretas - Garantia: 5 anos contra defeitos de fábrica Aplicações: - KIA: CERATO - VOLKSWAGEN: BETLE, BORA, GOLF, PARATI, PASSAT, VIRTUS II - FIAT: LINEA, STILO, STRADA II - TOYOTA: COROLLA, PRIUS, PRIUS II - RENAULT: ESPACE, KANGOO EXPRESS, LAGUNA, MEGANE, SAFRANE - AUDI: 80, A4 OBSERVAÇÕES: IMAGEM MERAMENTE ILUSTRATIVA VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU PNEU', 529.47, 449.11, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-81zw4-migcv8jzuakh9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F22199284536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19948602363', 'Par de Alto Falante Pioneer Quadriaxial 6X9 Polegadas 100W de Potência RMS - TS 6960BR', 'O TS-6960BR é o novo modelo de alto-falante da Pioneer. Com borda de espuma e telas de acabamento, oferece maior sensibilidade e ampla resposta em frequência, deixando sua viagem mais agradável. Alto-falante quadriaxial 6x9 polegadas com ampla resposta de frequência. Woofer com cone de IMPP (polipropileno moldado por injeção) resistente a água e bobina de voz resistente ao calor. Com borda de espuma e telas de acabamento, oferece maior sensibilidade e ampla resposta em frequência, deixando sua viagem mais agradável. Características: - Marca: Pioneer - Modelo: TS-6960BR *Imagens Meramente Ilustrativas* Especificações Técnicas: - Midrange com cone de filme de Ø50 mm - Tweeter piezoelétrico de Ø29 mm em PET - Supertweeter piezoelétrico de PET de Ø12 mm - Potência RMS - 100 W (cada) - Potência RMS (par) - 200 W - Sensibilidade (1 W/1 m) – 88 dB - Impedância – 4 ohms - Profundidade de instalação – 83 mm - Dimensões do alto-falante (sem tela) – 234 x 164 x 99 mm - Dimensões do alto-falante (com tela) – 264 x 184 x 112 mm - Dimensões para corte – 218 x 148 mm Conteúdo da Embalagem: - 1x Par de alto-falantes - 1x Par de telas de acabamento - 8x Parafusos - 1x Certificado de garantia - 1x Lista de postos de assistência técnica', 299.18, 284.23, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/9a008617806b828f31cfc75f839548e4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376053737%2F19948602363', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21199299583', 'Chuveiro Lorenzetti Loren Shower Ultra Eletrônica 7.500W Branca - 7510156 220V', 'O Loren Shower Ultra possui formato quadrado, seguindo as tendências de arquitetura. A Resistência Loren Ultra integra o conceito tecnológico do produto e garante alta performance e longa duração, se comparada às resistências comuns. O Loren Shower Eletrônico possui controle de temperatura gradual, sem a necessidade de aumentar ou diminuir a vazão da água para obter a temperatura desejada, garantindo comodidade e economia no banho.', 211.12, 211.12, NULL, 'Home & Living > Bathrooms > Showerheads & Bidet Sprays', 'https://cf.shopee.com.br/file/sg-11134201-7rd5o-lwwy8af1h1unfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F21199299583', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097721546', 'Kit com 2 Super Pano de Chão SCOTCH-BRITE Azul 3M', '- Pano com superior poder de absorção, limpa, enxuga e revela o brilho natural de seu piso com facilidade. - Limpa e enxuga com muito mais eficiência que os panos convencionais. - Além disso, sua lavagem é simples e pode ser realizada em tanque convencional ou colocado em máquina de lavar roupa. - É indicado para limpeza leve ou pesada de superfícies diversas, apresentando alta resistência. - Proporciona excelente desempenho na limpeza de pisos, portas, janelas e etc. Benefícios - Seca muita mais que os panos comuns - Super macio e fácil de torcer. - Especial para pisos delicados - Formato: 49x59cm - Cor: azul claro Microfibras são artigos têxteis sintéticos, compostos por fios de multifilamentos individuais e ultrafinos que proporcionam uma série de propriedades superiores comparado aos outros tecidos. Comparativamente, as fibras de microfibra são 2 vezes mais finas que a seda, 3 vezes mais finas que o algodão e 100 vezes mais finas que o cabelo humano. Microfibras geram produtos com excelente toque, maciez e resistência, além de reduzir o esforço na hora da limpeza e oferecer alto poder de absorção. Benefícios da Microfibra: - Não riscam! - Toque agradável - Não soltam pelo! - Absorvem mais de 06 vezes o seu peso em água (mais que o algodão) - Suportam várias lavagens na máquina de lavar', 71.8, 71.8, NULL, 'Home & Living > Home Care Supplies > Cleaning Cloths', 'https://cf.shopee.com.br/file/sg-11134201-7rdx0-lyy27848qxdg1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328711923%2F23097721546', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41805895663', 'Bicicleta Infantil Menino Hot Wheels Aro 20 Nathor Cor Azul E Preto Tamanho Do Quadro 15', 'Indicada para crianças a partir de 7 anos ou com altura entre 1,20m e 1,50m. Conforto, segurança e muitas aventuras! As Bicicletas aro 20 Nathor garantem máxima segurança e conforto a cada pedalada! Possuem regulagem de ângulo do guidão (se adapta à postura do ciclista) movimento central avançado (mais facilidade para pedalar) e freios v-brake dianteiro e traseiro. Conta também com pezinho de descanso, protetor de corrente, pneus com câmara, quadro em aço carbono e aro em alumínio, diferenciais que levam muito mais conforto e segurança! Características: - Mesa Head-Set - Aro em alumínio - Maçaneta com ajuste do freio - Movimento central avançado - Pezinho de descanso exclusivo - Pneus com câmara - Freios V-brake - Idade mínima recomendada: A partir de 7 anos Informações Técnicas: - Tamanho da roda: 20 - Altura máxima recomendada: 120 cm a 150 cm - Peso máximo recomendado: 70 kg - Peso do produto: 10,600 Kg - Peso com a embalagem: 12,200 Kg - Cubagem: 0,15 m³ - Dimensões do produto (CxAxL):140cm x 85,5 cm x 66 cm - Dimensões da embalagem (CxAxL):120 cm x 23 cm x 56 cm Características: - Marca:NATHOR - Modelo:101370160000 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Bicicleta Aro 20 Hot Wheels - Mattel - Nathor', 1025.65, 923.09, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-7ra11-mbe05886zo0z99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F41805895663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259106647', 'Barra de Apoio e Segurança com Ventosa 30 cm Jaru Pingoo - Branco', 'A Barra de Apoio e Segurança com Ventosa Jaru Pingoo proporciona estabilidade e segurança para banheiros, garantindo apoio extra para idosos, pessoas com mobilidade reduzida ou usuários que necessitam de firmeza, por exemplo, ao entrar e sair do box, utilizar o vaso sanitário ou se levantar. Ideal para superfícies de Azulejos, Placa de acrílico, Mármore sintético, superfície Metálica, superfície de Vidro e Painel de madeira, oferecendo uma solução versátil para quem busca funcionalidade e facilidade no uso diário, sem a necessidade de furar a parede. Medidas: 30 cm (C) x 13 cm (L) Cor: Branco e Cinza Tipo de produto: Barra de Apoio Local de Uso: Versátil Material: Plástico de alta resistência com acabamento emborrachado Acabamento: Fosco Forma de instalação: Ventosa Peso do produto: 0,478Kgs Conteúdo da embalagem: 1 Barra de Apoio e Segurança com Ventosa Jaru', 139.68, 139.68, NULL, 'Home & Living > Bathrooms > Safety Handles', 'https://cf.shopee.com.br/file/sg-11134201-81zv1-mn62lp5bjsw042', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1758065666%2F58259106647', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13223727679', 'Mamadeira Anticólica Essence Smart Flow 270ml NUK - Branca', 'Mamadeira Essence Smart Flow 270ml Bico 6m+ Branca NUK A Mamadeira NUK Essence Smart Flow possui bico com tecnologia composta por sistema de fluxo de líquidos com múltiplos furos, que variam em quantidade, para garantir a saída adequada de líquido conforme a consistência de cada alimento. Bico Produzido em silicone. Sua válvula reduz a formação e ingestão de bolhas de ar durante a alimentação. Seu frasco com design mais acinturado é super-resistente. O novo indicador de controle de temperatura possui a sinalização do termômetro, localizada próximo à escala de graduação do frasco, que ajuda os pais na tarefa de assegurar a temperatura adequada dos alimentos para o consumo. Se o conteúdo estiver muito quente, acima de 37ºC, o botão de temperatura ficará branco, sendo necessário aguardar até retornar à cor azul para oferecer a mamadeira. O frasco de 270ml acompanha o bico tamanho M (6+ meses) com 6 furos e líquidos de média consistência. Livre de BPA. O MINISTÉRIO DA SAÚDE ADVERTE: A CRIANÇA QUE MAMA NO PEITO NÃO NECESSITA DE MAMADEIRA, BICO OU CHUPETA. O USO DE MAMADEIRA, BICO OU CHUPETA PREJUDICA O ALEITAMENTO MATERNO. Principais Características: - Bico Tamanho M - 6 furos (6+ Meses) - Indicador de controle de temperatura. - Capacidade em Volume: 270ml - Frasco com design acinturado. - Livre de BPA Especificações Técnicas: - Conteúdo da Embalagem: 01 Mamadeira - Composição/Material: Polipropileno e Silicone - Certificação INMETRO: CE-PUR/IQB - 000632 NBR 13793 - Garantia: 30 Dias (Contra Defeito de Fabricação pelo Fabricante) - Referência do Fabricante: PA7071-2N - Código EAN: 7896098814246 - Marca: Nuk Fotos Ilustrativas. Estampas e cores podem variar de acordo com lote do fabricante.', 64.9, 64.9, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/1722ac5be6b1721b9cdd618310976fd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F467697231%2F13223727679', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898145498', 'Par De Amortecedor Porta Malas Mola a Gás Tampa Traseira Para Linha Palio G1 G2 G3 G4 1996 até 2011.', 'Anúncio contém: 02 (Dois) Amortecedores Mola A Gás Do Porta Malas. Aplicável nos seguintes veículos: Montadora: Fiat; Veículo: Palio G1; Ano de fabricação: 1996, 1997, 1998, 1999, 2000, Montadora: Fiat; Veículo: Palio G2; Ano de fabricação: 2001, 2002, 2003. Montadora: Fiat; Veículo: Palio G3; Ano de fabricação: 2004, 2005, 2006, 2007. Montadora: Fiat; Veículo: Palio G4; Ano de fabricação: 2008, 2009, 2010, 2011. Sobre o produto: O que é o par de amortecedor de porta-malas a gás? O par de amortecedores de porta-malas a gás é um conjunto de componentes que ajuda a abrir, sustentar e fechar o porta-malas de maneira suave e controlada. Ele utiliza gás pressurizado (geralmente nitrogênio) para oferecer a força necessária ao movimento. Para que serve? Abrir e segurar o porta-malas: Auxilia no levantamento sem esforço. Movimento suave: Evita quedas bruscas ou fechamentos abruptos. Segurança: Garante que o porta-malas fique firme na posição aberta. Quando trocar? Deve ser substituído quando apresentar sinais de desgaste ou falhas, como: Dificuldade para abrir o porta-malas. Queda ou fechamento brusco ao levantar a tampa. Ruídos ou vazamento de gás perceptíveis no amortecedor. Falta de força para sustentar o porta-malas. Benefícios da troca do amortecedor de porta-malas a gás Facilidade de uso: Torna a abertura e fechamento mais leve e confortável. Segurança: Evita acidentes causados pelo fechamento inesperado do porta-malas. Durabilidade: Garante funcionamento adequado por mais tempo. Conforto e praticidade: Proporciona um movimento suave e controlado. Estética e funcionalidade: Mantém o veículo em bom estado de uso. Processo de Substituição Trocar as molas a gás do porta-malas geralmente envolve os seguintes passos: Apoiar o Porta-Malas: Use uma barra ou peça de apoio para segurar o porta-malas aberto durante a substituição. Remover as Molas Antigas: Solte as fixações das molas antigas, que podem ser parafusos, clipes ou outros tipos de encaixes. Instalar as Novas Molas: Coloque as novas molas a gás no lugar, fixando-as adequadamente. Testar o Funcionamento: Abra e feche o porta-malas algumas vezes para garantir que as novas molas estão funcionando corretamente. Manter as molas a gás do porta-malas em boas condições é essencial para a segurança e conveniência do uso diário do veículo, e a substituição regular conforme necessário ajuda a manter o funcionamento ideal do porta-malas. Sobre a empresa: Nós da Vallente E-commerce comercializamos apenas produtos originais de fabricantes certificado pelo ISO 9001. E só trabalhamos com peças novas, originais ou importadas de 1ª linha. Qualidade e confiança que você precisa para fazer a manutenção do seu veículo de forma segura. Vallente E-commerce. Sempre prontos para ajudar você a cuidar do seu carro! Dúvidas frequentes: O Produto é novo? Sim. Nós trabalhamos apenas com produtos novos, e com garantia. O Produto é original? Sim. Nós só trabalhamos com distribuidores homologados pelo fabricante. Tem garantia? Sim. Tem três (3) meses pelo fabricante munido de nota fiscal de compra. O produto é igual ao da foto? Sim. Todas as fotos são fiéis ao que você receberá, e para facilitar a sua compra, ilustramos também o veículo em que se aplica o produto. Em quanto tempo recebo minha compra? Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Instalação/Utilização Para este produto recomendamos e requer a mão de obra de um especialista para a sua instalação. Qualquer dúvida antes de sua utilização entre em contato pelo canal de perguntas que estaremos a sua disposição para Ajudar.', 80.12, 76.12, NULL, 'Automobiles > Automobile Spare Parts > Shocks, Struts & Suspension', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5366v3ld9xh92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1404803902%2F22898145498', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23693474559', 'Kit Suporte Acessórios Banheiro Lavabo Aço Inox Rose Gold', 'KIT ACESSÓRIOS PARA BANHEIRO OU LAVABO ARES LUXO 4 PEÇAS EM AÇO INOX 304 ROSE GOLD. SOBRE O PRODUTO: O kit luxo para banheiro em inox 304 é um conjunto de acessórios que vai deixar o seu banheiro mais bonito e funcional. Ele é composto por quatro peças: porta toalhas, porta papel higiênico e cabide. Todas as peças são feitas de aço inoxidável 304, um material resistente à corrosão e à ferrugem, que garante maior durabilidade e higiene. Um kit de banheiro é um conjunto de acessórios que têm como objetivo tornar o ambiente mais organizado e prático. Esse kit pode ser composto por diversos itens, como suportes para toalhas, saboneteiras, porta papel higiênico, entre outros. A vantagem de adquirir um kit acessórios para banheiro é que você garante que todos os itens estarão em harmonia com o ambiente. Além de proporcionar mais praticidade no momento de organizar e limpar o banheiro. Os banheiros pequenos precisam ser otimizados. Assim você garante que o conforto e praticidade não sejam comprometidos. ESPECIFICAÇÕES TÉCNICAS DO PRODUTO. - MATERIAS DE COMPOSIÇÃO DO PRODUTO: AÇO INOX 304. AÇO INOX 304: Porta toalha banho, Porta toalha rosto, Papeleira e Cabide. - MEDIDAS DAS PEÇAS: VIDE FOTO. NOSSO DIFERENCIAL: - Melhor acabamento do mercado. - Produtos resistentes e de alta durabilidade. - Preço imbatível de Fábrica. - Envio mais rápido do Brasil. PEÇAS QUE ACOMPANHAM O PRODUTO: 01 – PORTA TOALHA BANHO (AÇO INOX). 01 – PORTA TOALHA ROSTO (AÇO INOX). 01 – PAPELEIRA (AÇO INOX). 01 – CABIDE (AÇO INOX). RECOMENDAÇÕES: Limpe periodicamente os produtos utilizando um pano macio com sabão neutro. Contrate um profissional para a instalação. Nunca use produtos abrasivos como alcalinos, ácidos ou solventes nos produtos. Confira nossa lista, ou entre em contato conosco, temos peças de reposição à pronta entrega e atendimento a qualquer momento.', 299.9, 209.9, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/br-11134207-820ly-mmswufuwwmwxf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337531568%2F23693474559', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11111676331', 'Livro - Sítio do Picapau Amarelo - Capa dura - Ciranda Cultural', 'O melhor lugar do mundo para se passar as férias é o Sítio do Picapau Amarelo. Escutar as histórias da Dona Benta, experimentar os quitutes da Tia Nastácia e brincar com Emília, Visconde e toda a turma que lá vive atraiu a curiosidade de crianças do mundo todo, e até mesmo das criaturinhas dos contos clássicos, que resolveram fazer uma visita a este lugar mágico, onde tudo pode acontecer. Tudo mesmo! Editora: Ciranda Cultural Edição: 1, 2019 Autor: Monteiro Lobato Idioma: Português Páginas: 144 Dimensões: L 15.50 x A 22.30 x E 0.70 ISBN: 9788538088097', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/bf53f7ee94449c3b14ac992606bcd4d6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F11111676331', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
