INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093560073', 'Livro Cartonado Veja... Eu sou feliz!', 'Vamos dar um SORRISO? Quer fazer cara de SURPRESA? Olhe no espelho e faça muitas expressões engraçadas com este divertido livro sobre sentimentos._x000D_ _x000D_ Editora: Ciranda Cultural_x000D_ Edição: 1, 2024_x000D_ Autor: Igloo Books_x000D_ Ilustrador: Andy Passchier_x000D_ Idioma: Português_x000D_ Páginas: 10_x000D_ Dimensões: L 18.00 x A 18.00 x E 1.20_x000D_ ISBN: 9786526113066_x000D_ Coleção: Espelho mágico_x000D_ Linha Editorial: Ciranda Cultural - Coedição_x000D_ Faixa Etária: + 4 anos_x000D_ Assuntos (tags): Sentimentos, Aprendizado, Felicidade_x000D_ BISAC: Literatura Infantil / Conceitos / Sentidos & Sensações_x000D_ Linha de Produto: Cartonado_x000D_ Encadernação: Lombada quadrada_x000D_ Acabamento: Faca especial_x000D_ Material: Cartonado', 44.9, 44.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7repu-m2s73htih9rh97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F22093560073', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
