INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9067293789', 'Kit com 2 Mamadeiras My 1st 150/300ml First Choice Rosa - Nuk', 'Kit 2 Mamadeiras My 1st 150/300ml First Choice - NUK O kit de mamadeiras NUK My First é uma ótima opção para acompanhar o desenvolvimento dos bebês desde o nascimento. Possuindo dois tamanhos diferentes, sendo 150ml (0m+) e 300ml (6m+) para acompanhar cada fase. O bico das mamadeiras foi desenvolvido com o NUK Air System Anticólica, sistema de ventilação que reduz a formação e ingestão de bolhas de ar durante a alimentação, possibilitando um fluxo constante de líquido para que a criança se alimente de forma contínua. Ideal para a passagem de líquidos de média consistência, como o leite materno, chá e água. Livre de BPA. O MINISTÉRIO DA SAÚDE ADVERTE: A CRIANÇA QUE MAMA NO PEITO NÃO NECESSITA DE MAMADEIRA, BICO OU CHUPETA. O USO DE MAMADEIRA, BICO OU CHUPETA PREJUDICA O ALEITAMENTO MATERNO. Principais Características: - Tamanho do Bico: Nº 1 (0 - 6 meses) e Nº 2 (6+ Meses) - Capacidade: 150ml (0 - 6 meses) e 300ml (6+ Meses) - Válvula Nuk Air System - Fácil de Limpar e Esterilizar - Bico em Silicone Macio - BPA Free - Cor: Rosa Especificações Técnicas: - Conteúdo da Embalagem: 2 Mamadeiras My First Choice - Nuk - Composição/Material: Polipropileno e Silicone - Garantia: 30 dias (Contra Defeitos de Fabricação Pelo Fabricante) - Certificação: CE-PUR/IQB-000611 NBR 13793 SEGURANÇA DE MAMADEIRAS E BICOS DE MAMADEIRAS OCP 006 - Código do Fabricante: PA7063-MG - EAN: 7896098810811 - Marca: Nuk Imagens meramente ilustrativas, as cores e estampas podem variar de acordo com o lote do fabricante.', 78.9, 78.9, NULL, 'Mom & Baby > Feeding Essentials > Bottle-feeding', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lgxv2pmzi1fa7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2