INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198854172', 'Filtro de Ar JDR Honda CRF 250F', 'Filtro de Ar JDR Honda CRF 250F *Confira as especificações do Filtro de Ar JDR Honda CRF 250F: - Capacidade de fluxo de ar - alta vazão de ar projetada para otimizar a admissão, contribuindo para melhor combustão, resposta mais rápida ao acelerador e desempenho consistente em rotações baixas e médias - Tecnologia de filtragem - elemento filtrante em espuma de duas camadas: a camada externa captura partículas maiores, enquanto a camada interna retém partículas finas, oferecendo proteção superior ao motor - Encaixe e vedação - design sob medida para a CRF 250F com apoio uniforme nas bordas, reduzindo o risco de passagem de poeira por folgas e garantindo a integridade do sistema de admissão - Durabilidade e custo-benefício - materiais de alta qualidade e construção robusta pensadas para uso off-road, suportando ciclos repetidos de limpeza e prolongando a vida útil do componente - Aplicação recomendada - ideal para trilhas, enduro e uso recreativo ou esportivo em off-road, onde a combinação de alta filtragem e boa vazão faz diferença na confiabilidade do conjunto - Desempenho - proteção aprimorada do motor contra desgaste prematuro, acelerações mais cheias e entrega de potência estável em diferentes tipos de terreno e condições de poeira - Compatibilidade - desenvolvido especificamente para Honda CRF 250F, garantindo encaixe perfeito no compartimento do filtro de ar original e vedação efetiva contra poeira e sujeira - Manutenção e limpeza - lavável e reutilizável, com processo de limpeza simples que preserva a eficiência de filtragem e reduz custos recorrentes com reposição de filtros - Benefícios - maior proteção do motor, melhor resposta do acelerador, desempenho consistente e redução dos custos com manutenção preventiva ao longo do tempo *Compatível com todos os anos da moto Honda CRF 250F (Cód.', 149.9, 149.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-824jc-me0fn433wmbn99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F451914474%2F22198854172', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
