INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692833755', 'Batom Rosa Semi-Matte – The Lipstick Nude Pink Océane Edition 3,2g', 'Se a Gente Pedisse para Você Escolher Um Item de Maquiagem Que Você Não Pode Viver Sem, Certamente o Batom Seria Um Deles. Afinal, Ele Costuma Ser o Primeiro Item de Make de Muitas Pessoas. Pensando Nisso, The Lipstick Chega para Ocupar Um Lugar No Seu Nécessaire e No Seu Coração. Vem Ver Os Benefícios: O Primeiro Destaque Fica Por Conta da Sua Cobertura Semi-Matte, Que É Muito Confortável e Não Craquela, Além de Possuir Uma Durabilidade Incrível. a Cor Nude Pink - Rosa É Aquele Tom Que Traz Delicadeza e Feminilidade Ao Look, Deixando Seus Lábios Rosados e Lindos. Especialista em Maquiagem de Qualidade, a Linha Océane Edition Combina com Todos Os Momentos do Seu Dia. e a Tonalidade Nude Pink - Rosa do The Lipstick Ainda Conta com Óleo de Girassol, Óleo de Amêndoas e Ácido Hialurônico, Ingredientes Que o Tornam Ainda Mais Fáceis de Espalhar. Tudo de Bom, Né? Pode Parar de Procurar: o Batom Certo para Deixar Seus Lábios Lindos e Rosados Por Mais Tempo Está Aqui! com Ele, Sua Boca Ganha Aquele Aspecto Uniforme Na Tonalidade Rosada Sofisticada e Discreta Que Combina com Qualquer Ocasião. Seja para Trabalhar, para o Happy Hour ou para Um Encontro a Dois, Tenha Este Batom Na Bolsa e Garanta o Visual Sempre Intacto Aonde Quer Que Esteja. Este Batom Combina com Quais Ocasiões? Todas! Nude Pink - Rosa É Uma Cor Coringa em Qualquer Nécessaire. Ele Passa Uma Mensagem Doce e Delicada, para Os Dias Que Você Quer Se Sentir Mais Feminina. Além Disso Ele É Super Elegante e Pode Ser Usado para Compor Uma Make de Trabalho e Até Mesmo Um Look de Festa.', 109.9, 109.9, NULL, 'Beauty > Makeup > Lips', 'https://cf.shopee.com.br/file/sg-11134201-825ay-mr22wtyjsqgx6b', 'https://shope.ee/an_redir?origin_link=https%3A