INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21599244862', 'Endurecedor 065 para Esmalte PU/Verniz Alto Sólidos 450ml', 'Olá, seja bem vindo(a) a Ibicolor! Somos uma loja física do interior de São Paulo que opera nas principais lojas online do Brasil, fique a vontade para mandar uma pergunta ou tirar suas dúvidas que nosso time vai te atender o mais rápido possível. Em caso de dúvida mande uma pergunta que nosso time já vai te responder! Endurecedor 065 utilizado para promover a secagem e cura do Esmalte poliuretano Automotivo do Sistema Mixing Machine e Verniz Alto Sólidos 8937. Produto possui grande absorção de umidade devendo ser aberto somente no momento do uso, e fechado logo em seguida.', 59.9, 59.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Polisher', 'https://cf.shopee.com.br/file/sg-11134201-7rd6e-luanxepe9xhl23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F346348161%2F21599244862', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23296807682', 'Cristianismo e Liberalismo | Capa Dura | J. Gresham Machen', 'O liberalismo teológico é muito temido, mas qual seria o seu real perigo? E o que realmente seria o liberalismo teológico? Nesta edição de comemoração aos 100 anos de lançamento desta obra, contando com comentários e 18 artigos de professores do seminário que fundou, os argumentos de J. Gresham Machen recebem uma nova chance para defender que o cristianismo ortodoxo e o liberalismo teológico são duas religiões diferentes. Com precisão e palpável devoção a Cristo, Machen utiliza seu profundo conhecimento do Novo Testamento e sua longa interação com teólogos liberais para alertar a igreja dos perpétuos perigos de contemporizar a mensagem cristã. Detalhes do Produto: Autor: J. Gresham Machen Editora: Trinitas Acabamento: Brochura Dimensões: 16 larg. X 23 alt. Número de páginas: 288', 63.99, 63.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbkp-ll9o7uzop3edbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F23296807682', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
