INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397476315', 'Chuveiro Para Banheiro Ducha Teto Parede Quadrada 20x20 Preto Fosco Black Quadrado Metal Luxo Solar', 'Ducha Slim Quadrada 20x20cm Preto Fosco Para Gás E Piscinas Revitalize a sua mente, corpo e alma com uma ducha estimulante. Nosso modelo repleto de funcionalidades fornece uma gama de sensações, de modo que você pode ter o banho dos seus sonhos. Esse modelo possui a tecnologia para distribuição de água equilibrada para cada bico, feita completamente em metal, com durabilidade e luxuosidade agregando a praticidade para garantir uma vida de aparência perfeita, desenvolvido para serem usados com nossos modelos de suporte de parede, que compartilham do mesmo design. - Ducha fria compatível com aquecedor solar ou a gás. - Ducha articulável com dimensões de 20cm x 20cm e braço de chuveiro quadrado de 30 cm. - Fabricada em liga de cobre e braço em alumínio, ambos com acabamento em pintura termofixa em Preto Fosco. - Design slim para um banheiro sofisticado. - Dutos de saída de água em silicone para evitar entupimentos e facilitar a limpeza. - Base do chuveiro com pré-filtro para impedir acúmulo de detritos. - Bitola de instalação: ½. - Cabeça articulável. - Produto não elétrico, compatível com aquecedores elétricos, a gás ou solar. - Vazão: 15L/min por 10 m.c.a. - Polegada: 8 polegadas. - Material: Inox 201. - Pressão Mínima: 4 m.c.a. - Pressão Máxima: 32 m.c.a. Itens inclusos: 1 - ducha 20x20 preto 1 - acabamento quadrado preto 1 - cano 36cm preto', 249.9, 65.22, NULL, 'Home & Living > Bathrooms > Showerheads & Bidet Sprays', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lujkz9o5trisc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356560587%2F23397476315', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21397185234', 'Cabo Intermediario da Alavanca do Freio de Mão Vectra 2.0 8v 16v MPFI CD GL GLS 1997 1998 1999 2000 2001 2002 2003 2004', '311mm Numeração original compatível: 93285212 Usamos Fotos REAIS EM TODOS NOSSOS ANUNCIOS Produto com a qualidade Peças Premium Todos os nossos produtos acompanham nota fiscal Para compras com CNPJ de fora do Estado de São Paulo, o valor do imposto, (ST) Substituição Tributária NÃO ESTÁ INCLUSO NO VALOR DO PRODUTO ANUNCIADO, caso deseje comprar com CNPJ, após a emissão da nota fiscal, será calculado o valor do imposto de (ST), Substituição Tributária, que será COBRADO separadamente e antecipadamente. LEMBRANDO QUE O VALOR DO IMPOSTO, (ST) É COBRADO PELO ESTADO DE DESTINO e mercadoria só poderá ser despachada após o recolhimento antecipado. Peças Rápidas - O seu shopping de auto peças online!', 41.75, 41.75, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/br-11134201-7qukw-ljllmnild40ze0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513651190%2F21397185234', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
