INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992533693', 'Correia Dentada Fiat Palio 1996 a 2000 - 516128 - CT964', 'Correia Dentada Fiat Palio 1996 a 2000 516128 CT964 (Weekend) - Motor 1.0 8v - (131 Dentes) (CVA - Comando de Válvulas) A correia dentada é a responsável por manter ligado o eixo-comando de válvulas ao virabrequim do motor. Ela também faz com que ambos se sincronizem. Outra função importante executada pela correia dentada é a de fazer com que as válvulas de admissão e de escapamento se fechem e se abram no momento certo. A manutenção deve ser feita ao menos de seis em seis meses, ou então a cada 10 mil km rodados. Essa quilometragem varia de modelo para modelo.', 54.3, 54.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbm8-lmtf8qt672dsc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22992533693', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597467771', 'Cebolinha do Óleo UNO 1992/2002 - 19782 - 13028', 'Cebolinha do Óleo UNO 1992/2002 TODOS C/I.E (0,50 BAR) Indicar anomalia na pressão do óleo lubrificante. O interruptor de pressão do óleo é normalmente localizado no bloco do motor próximo a bomba de óleo, a pressão gerada pela bomba passa pelo interruptor acionando uma mola interna do mesmo fechando assim contato elétrico, enviando um sinal para o painel de instrumentos. Se a pressão for maior do que a especificada o interruptor libera a passagem do óleo de volta para o cárter. Vida Útil: Substituir a cada 40.000 Km (consultar manual do veículo)', 48.26, 48.26, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6h-luf93ih1q5ll60', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23597467771', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793197773', 'Sensor Velocidade Gm Bonanza 1991 a 1996 - 516098 - 7300', 'Sensor Velocidade Gm Bonanza 1991 a 1996 516098 7300 4.1 12v - 3 Pinos - 6 Pulsos - Rosa Informa com precisão a velocidade do veículo ao computador da injeção eletrônica. Esta informação é fundamental para o controle da injeção do combustível e nos casos de desaceleração o corte deste para a redução do consumo e emissões de poluentes (CUT-OFF). Localizado geralmente na caixa de câmbio ou próximo ao eixo da roda do veiculo.', 61.56, 61.56, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd5t-luf6i94ys3an89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23793197773', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44508213208', 'Pano De Prato Barrado Pe De Galinha Kit Com 5 Peças', 'Quer uma cozinha moderna ? Comece pelos Panos de Prato! Pano de prato sacaria de alta qualidade (O Legitimo), com barrado e passa fita, com excelente absorção, não solta fiapos na louça, super absorventes e são anti mancha, podem ser lavados em água sanitária sem medo de manchar os barrados, conta com diversas estampas modernas e exclusivas, uma mais linda que a outra, criadas para alegrar e dar vida a sua cozinha. Contém 5 unidades Estampas: Sortidas Especificações: Trama 12, acabamento em bainha nas laterais com costura reforçada. Barrado: altura de 12cm 100% algodão tecido anti-mancha, estampas exclusivas. Medidas: 41 cm largura x 66 cm altura. Marca da Sacaria: Têxtil H. Carvalho (O Legitimo pé de Galinha). LAVAGEM: Podem ser lavados em água sanitária. Detalhes da Sacaria: O tecido branco do pano de prato é feito em sacaria 100% algodão (conhecido por donas de casa como pé de galinha), considerado por muitos a melhor sacaria do mercado. pano de prato natal | pano de prato barrado | panos de prato | pano prato | kit pano de prato | panos de prato atacado | pano de prato | pano de prato atacado | panos de.prato', 35.99, 29.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Cloths', 'https://cf.shopee.com.br/file/sg-11134201-81zu9-mmlqimf9tamc44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F388739239%2F44508213208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098121831', 'Correia Alternador Poly V BRAVO 2011 a 2016 - 14135 - 6PK1045', 'Correia Alternador Poly V BRAVO 2011 a 2016 Produto novo, com garantia e Nota Fiscal!_x000D_ _x000D_ Correia Poly V - 6PK1045_x000D_ BRAVO - Motor 1.8 16v_x000D_ Anos: 2011 2012 2013 2014 2015 2016_x000D_ Utilização: Virabrequim / Alternador / Bomba D''Água / Direção Hidráulica As correias Multi V permitem a transmissão não positiva de binários. A sua função: O acionamento do alternador, ventoinha, bomba de água, compressor do ar condicionado e direção assistida nos motores modernos. As correias Multi V estão sujeitas a envelhecimento e desgaste. Por essa razão, têm de ser controladas e substituídas a intervalos regulares. Os intervalos de controle e de substituição são sempre estabelecidos pelo fabricante do veículo e devem ser respeitados.', 71.34, 71.34, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rblr-lollilmxprr5cc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23098121831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
