INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45703009449', 'Espuma Expansiva De Poliuretano 500mL 320G Mundial Prime', 'Garanta eficiência e praticidade nos seus projetos com a Espuma Expansiva PU 500mL da Mundial Prime. Ideal para vedação, fixação, isolamento térmico e acústico, este produto é indispensável em obras, instalações e reparos residenciais ou industriais. Principais Características: Alta Expansão: preenche vãos, frestas e cavidades com facilidade. Secagem Rápida: forma uma estrutura rígida e resistente após a cura. Isolamento: excelente capacidade de isolamento térmico e acústico. Versatilidade: ideal para uso em portas, janelas, tubulações, sistemas elétricos e muito mais. Durabilidade: resistente a fungos, umidade e variações climáticas. Conteúdo da Embalagem: 1 unidade de Espuma Expansiva PU de 500ml. Modo de Uso: Agite bem antes de usar. Aplique diretamente na área desejada, respeitando o tempo de expansão e cura. Utilize equipamentos de proteção individual (EPIs) conforme orientações do fabricante. Produto de qualidade, confiança da marca Mundial Prime! Perfeito para profissionais da construção civil, montadores ou quem busca soluções práticas e eficientes para vedação e isolamento.', 24.9, 18.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-820ln-mqs1ztc73bi97c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F844004880%2F45703009449', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
