INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394366342', 'Palheta Dunlop Maxgrip Nylon Standard 73mm', 'Somos a RCK AUDIO, sua loja virtual de Instrumentos Musicais e Áudio Profissional - Há mais de 10 anos no mercado - Mais de 150.000 clientes atendidos - Todos os produtos com Nota Fiscal - Revenda autorizada oficial do produto - Criterioso processo de embalagem e expedição ; Palheta Dunlop Maxgrip Nylon Standard 73mm A Dunlop Max-Grip Nylon Standard 0,73mm é a escolha perfeita para músicos que valorizam conforto, firmeza e precisão na hora de tocar. Desenvolvida em nylon de alta qualidade, possui a exclusiva superfície texturizada Max-Grip, que garante pegada antiderrapante e segura, mesmo em situações de maior suor ou movimentação intensa. Com espessura de 0,73mm, oferece ótima flexibilidade, ideal para bases rítmicas, batidas leves e dedilhados suaves, proporcionando resposta equilibrada e confortável. Essa espessura é muito procurada por violonistas e guitarristas que desejam versatilidade para diferentes estilos musicais, como pop, sertanejo, MPB e rock leve. A série Max-Grip Nylon Standard é reconhecida pela sua durabilidade, controle e segurança, sendo amplamente utilizada por músicos de todos os níveis, do iniciante ao profissional. Especificações: Marca: Dunlop; Modelo: Max-Grip Nylon Standard; Espessura: 0,73mm; Material: Nylon texturizado com superfície Max-Grip antiderrapante; Formato: Standard; Excelente pegada e conforto; Alta durabilidade e resposta sonora versátil.', 12.62, 12.62, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-824gw-me7a7ue0d7nn05', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F313967528%2F23394366342', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52211558605', 'KZ Zsn Pro Fones De Ouvido Com Fio Dual Drivers Earsets HiFi Cancelamento De Ruído Bass Intra-Auriculares Cabo Removível', 'Os fones de ouvido com fio ZSN Pro são feitos de tampa de liga de zinco e cavidade de resina, tudo em forma aerodinâmica muito suave, sem bordas afiadas de liga de zinco e cavidade de resina, tudo em formato aerodinâmico muito suave, sem bordas afiadas. Costuras mal feitas ou excesso de cola. Fone de ouvido elegante e atraente. Cabo destacável de 2 pinos aprimorado】 Projetado com proteção de slot de 2 pinos, o cabo banhado a ouro do Pro pode efetivamente evitar que o pino quebre e prolonge a vida útil da interface. O cabo destacável também facilita a substituição para manter e atualizar. Cancelagem de ruído e uso ergonômico】 Isso nos fones de ouvido possui excelente isolamento de ruído para reduzir pelo menos 90% de ruído, o que oferece uma melhor experiência enquanto usa música. a cavidade é cientificamente molde para se adequar aos seus ouvidos como fones de ouvido personalizados,Ajuste de longo tempo de uso.', 111.0, 67.24, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/sg-11134201-823pe-mp7xbdavde6mce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F52211558605', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
