INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21898274348', 'Buzina Tipo Xavequinho Para Moto 12v Agudo Techone', 'ESPECIFICACAO TECNICA: FABRICADA EM LIGA METALICA RESISTENTE SOM DE ALTA INTENSIDADE TENSAO: 12V DC DB: 105-115 CONECTOR: PADRAO DUPLO HORIZONTAL. MODELO: PADRAO ESTILO UNIVERSAL. REGULAGEM: EM PARAFUSO FIXADO NA CONFIGURACAO DO EQUIPAMENTO (PODENDO SER AJUSTADO PELO INSTALADOR). TOM: AGUDO (450 10HZ). POTENCIA: 27 WATTS CORRENTE: 2 2 AMPERES APLICACAO: MOTO CONTEUDO DA EMBALAGEM: 1X BUZINAS. 1X KITS DE FIXACAO. (SUPORTE RETO). INFORMACAO QUIMICA POLIMERO LIGA METALICA COBRE. OBSERVACAO A INSTALACAO DEVE SER EFETUADA POR UM PROFISSIONAL CAPACITADO; ATENCAO: CONFORME LEI FEDERAL N 11.291 A EXPOSICAO PROLONGADA A RUIDOS SUPERIORES A 85DB PODE CAUSAR DANOS AO SISTEMA; A REGULAGEM DO TOM PODE SER FEITA PELO INSTALADOR. APOS A FIXACAO NA POSICAO ESCOLHIDA ACONSELHAMOS UTILIZAR UMA PEQUENA QUANTIDADE DE COLA INSTANTANEA (NAO INCLUSA NO KIT) PARA PRENDER O PARAFUSO NA POSICAO DESEJADA. OBS: A instalação dos produtos devem ser sempre realizada por um profissional capacitado. Na LS Distribuidora, nossa prioridade é oferecer a você produtos de alta qualidade e um serviço excepcional. Trabalhamos exclusivamente com produtos novos, acompanhados de nota fiscal, para que você tenha total confiança em suas compras. Escolha a LS Distribuidora e tenha a certeza de que está optando por excelência, confiabilidade e produtos que fazem a diferença!', 20.49, 20.49, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvi-mdkc4w04ss0k83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1279212230%2F21898274348', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13345729057', 'Psyllium Original 500g – Qualidade Premium', 'Psyllium Natural 100% Puro Rico Em Fibras Alta Qualidade Psyllium é originário de um arbusto (Plantago ovata) e extraído da casca de suas sementes. Tem sido muito utilizado em dietas de emagrecimento, por ter um excelente poder sobre nosso intestino, melhorando o transito intestinal de forma natural, sem ser agressivo, ajudando a diminuir a absorção de gordura em excesso. Psyllium para que serve? É uma excelente opção para quem busca um alimento que auxilie na regulação intestinal, no emagrecimento, controle de diabetes, colesterol, redução da pressão arterial e vem sendo fonte de estudos na prevenção e combate de algumas doenças. Sobre a empresa: A p&p linha fit é uma empresa especializada em produtos naturais. Com uma estrutura de ponta para a manipulação de alimentos, fracionamos as sacas e vendemos em embalagens ideias para o nosso consumidor final. A política da garantia de satisfação faz com que nossos produtos passem por um rigoroso controle de qualidade levando o melhor produto a mesa do nosso cliente com um preço justo. Obrigado por comprarem nossos produtos Dúvidas de sempre: 1) Em quando tempo meu pedido será enviado? Enviamos o seu produto em até 24 horas após a aprovação do pagamento. 2) E se meu produto não chegar ? TODOS OS PACOTES SEGUEM COM O PROTOCOLO DE RASTREIO, E VOCÊ PODE CONSULTAR DIARIAMENTE NO SITE DAS TRANSPORTADORAS PARA VER ONDE ELE ESTA. CASO OCORRA ALGUM SINISTRO, A MERCADORIA ESTÁ ASSEGURADA PELO SISTEMA DO MARKETPLACE E VOCE RECEBE SEU DINHEIRO DE VOLTA.', 69.9, 18.98, NULL, 'Food & Beverages > Cooking Essentials > Flour Coating', 'https://cf.shopee.com.br/file/br-11134201-23010-ilqtt0f5ywlv41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F394192376%2