INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5863418208', 'Capa Case Capinha Armor Proteção Militar para iPhone 11 - Gshield, Antiderrapante', 'Use a melhor case para seu celular! A capa armor possui um design leve, fino e é extremamente resistente. Suas dimensões se adaptam perfeitamente ao desenho do smartphone, garantindo uma pegada firme e livre de escorregões. Produzida sob a certificação Internacional Militar, a Capa Armor de Superproteção da Gshield tem material antiderrapante nas laterais. O Acessório ainda vem com uma alça kick stand para deixar o dispositivo em uma inclinação de até 60°. A posição é ideal para assistir vídeos, séries e filmes ESPECIFICAÇÕES -Material: Polipropileno de alta densidade - Não Amarela. -Marca: Gshield - Dimensões: Dimensões exatas do aparelho - Proteção: Contra impactos - Certificações: Us Military - Peso: 10G - Cor: Azul escuro (Conforme imagem) COMPATIBILIDADE - iPhone 11 ITENS INCLUSOS - 1x Capa protetora', 99.97, 99.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/31412aff7f5427a7f13401856bea884d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F5863418208', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
