INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23991956402', 'Creatina 100% Pura Monohidratada 500g - Bodybuilders', 'A Creatina Monohidratada 100% Pura é um suplemento alimentar em pó formulado exclusivamente com creatina monoidratada de alta pureza. A creatina é um composto naturalmente produzido pelo organismo a partir de aminoácidos e armazenado nos músculos na forma de fosfocreatina, participando do processo de regeneração do ATP, principal fonte de energia celular. Por sua característica e composição simples, a creatina é amplamente utilizada por praticantes de atividades físicas e atletas como complemento alimentar, podendo ser incluída na rotina diária conforme a necessidade individual ou orientação profissional. Modo de uso: Diluir 3 g (1 colher de café) em água ou bebida de sua preferência. Consumir uma vez ao dia ou conforme orientação de nutricionista ou profissional de saúde. Ingredientes: Creatina monoidratada em pó e antiumectante. Avisos gerais: Este produto não é um medicamento. Não exceder a recomendação diária de consumo indicada na embalagem. Gestantes, nutrizes, crianças, idosos e pessoas com enfermidades devem consultar um profissional de saúde antes do consumo. Manter fora do alcance de crianças.', 99.9, 99.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mabahxsf1vnd51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F555509944%2F23991956402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
