INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393723961', 'Conjunto Infantil Menina Blusa Pretty Cat E Legging Estampada Malwee Kids', 'Conheça o Conjunto Infantil Menina Blusa Pretty Cat e Legging Estampada, uma escolha cheia de charme e conforto para as garotas! Confeccionado em malha, esse conjunto é ideal para o dia a dia e garante total liberdade de movimentos. A blusa adorável com estampa de gato, combinada com a legging estampada, traz um toque divertido e moderno para o look. • Conjunto Infantil Malwee Kids • Design Estiloso • Conforto que proporciona liberdade de movimentos • Ideal para Passeios e Dia a Dia', 72.9, 65.61, NULL, 'Baby & Kids Fashion > Baby Clothes > Sets', 'https://cf.shopee.com.br/file/sg-11134201-7rce6-m6ef4om6rmdof2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1264817414%2F22393723961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
