INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394178585', 'Teclado para Notebook Semp Toshiba Infinity IS-1442', 'Teclado compatível com Semp Toshiba Infinity IS-1442 O teclado compatível com Semp Toshiba Infinity IS-1442 foi aprovado em rigorosos testes de qualidade e atende todas as exigências do seu equipamento, apresenta encaixe perfeito com o notebook, possui a mesma fixação da peça original. Além de 12 meses de garantia contra defeitos de fabricação. Atenção! Esse é um teclado bringIT, portanto não é um produto original da fabricante Semp Toshiba. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Marca: bringIT Modelo: IS-1442 Moldura: Com Moldura Idioma/Layout: ABNT2 Backlight: Sem Iluminação Pointing Stick: Sem Pointingstick Cor: Preto Referência: TC196-TO-0001 Atenção: Para que esse teclado seja compatível com seu notebook, deverá ter as mesmas especificações de encaixe, layout e moldura. Esse produto é compatível com os notebooks: IS-1442 V111330AK2BR, IS1442 IS-1442 IS 1442, IS-1442 90.4IN07.S1B, 1442, IS-1442 Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 106.2, 65.43, NULL, 'Computers & Accessories > Desktop Computers > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259f-mqtjkc0pkemm36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23394178585', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20997975025', 'SSD Adata 240GB SATA III 6GB/S Leitura 520MB/S Gravação 450MB/S ASU650SS-240GT-R', 'SSD Sata Adata 240GB ASU650SS-240GT-R Se você deseja realizar um upgrade em seu notebook, o SSD Sata Adata é uma ótima escolha de custo-benefício. Tem implementado o 3D NAND Flash e um controlador de alta velocidade, oferecendo um desempenho de leitura e gravação de até 520/450 MB/s e maior confiabilidade do que os SSDs com NAND 2D. Possui em sua tecnologia o suporte ECC (código de correção de erro), o que garante o desempenho e a integridade dos dados. Sua memória opera no modo de célula em único, fazendo com que aumente o seu desempenho e mantenha a velocidade de leitura e gravação por segundo, tornando as transferências de arquivos e downloads ainda mais rápidas. Especificações técnicas Capacidade: 240GB Fator de forma: 2.5" NAND Flash: 3D NAND Interface: SATA III Desempenho sequencial R/W (máx.): Até 520 / 450MB/s * O desempenho real pode variar devido a capacidade SSD disponível, componentes de hardware e software do sistema e outros fatores Temperatura operacional: 0°C a - 70°C Temperatura de armazenamento: -40°C a - 85°C Resistência a choque: 1500G / 0,5ms MTBF: 2.000.000 horas Dimensões: 100,45 x 69,85 x 7mm (C x L x A) Peso: 59,5g Garantia: 3 anos de garantia direto com o fabricante Referência: SS137', 790.36, 790.36, NULL, 'Computers & Accessories > Data Storage > SSD', 'https://cf.shopee.com.br/file/sg-11134201-825bd-mq3scyguawao18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F20997975025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798288303', 'Pedal Cambio Marcha Completa Cg 150 Sport 2005/2008 Original', 'COMPRANDO NA PARANÁ AUTO CICLO VOCÊ TEM O MELHOR PREÇO E ENTREGA RÁPIDA ----SOMOS REVENDEDORES OFICIAIS ---- TEXX - HJC - TXK - KMP - RIK - GP7---- >>>Enviamos sua encomenda em até 24h - Totalmente rastreável e 100% seguro.<<< [PRODUTOS COM NOTA FISCAL e GARANTIA DE FÁBRICA.] PEDAL DE CÂMBIO COMPLETO ARTICULADO HONDA CG 150 SPORT 2005 A 2008 - GP7 Aplicação: - Honda CG 150 Sport (2005 a 2008) Os Pedais de Câmbio GP7 destacam-se no mercado por possuírem encaixe e ângulo perfeito durante o acionamento das marchas. Com isso, as estrias acopladas no eixo de câmbio se encaixam perfeitamente. evitando desgastes e danos no eixo de câmbio. Esta é uma peça de alta qualidade e durabilidade, características presentes em todos os produtos GP. Número da Peça: 24701-KRM-870SET >---------------< • Não nos responsabilizamos pelo mau uso do produto. • Recomendamos que a troca / instalação seja realizada por um profissional qualificado. • Antes de comprar verifique se seu e-mail, endereço e dados estão atualizados no Cadastro, assim manteremos contato com você durante o processo da compra e, evitando eventuais problemas com a entrega do produto. DUVIDAS CHAMA NO CHAT!!! Qualquer dúvida entrar em contato no campo de perguntas para evitar transtornos, temos uma equipe totalmente qualificada a disposição pronta para ajudar. Obrigado!', 79.9, 59.1, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rd5z-m76lmlms7rau5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1124035980%2F23798288303', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
