INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097926556', 'Kit Creamy Calming Retinol B Complex (3 produtos)', 'Kit Creamy Calming Retinol B Complex (3 produtos) Este Kit Contém Creamy Skincare Calming Cream - Creme Hidratante Facial 40g: hidratante facial para pele sensível ou sensibilizada. Creamy Skincare Gel-Creme Retinol 0,3 - Antirugas Concentrado 30g: gel creme facial anti-idade de uso noturno. Promove firmeza à pele e traz ainda ingredientes calmantes e reparadores que garantem conforto na aplicação. Creamy Niacinamide B Complex 20% - Sérum Ultraconcentrado 30ml: possui um blend de vitaminas (B3, B5, B6, B12 e E) que age no fortalecimento da barreira cutânea, melhorando a aparência, textura e tonalidade da pele. Ele garante o aumento da hidratação, reduz a aparência de poros dilatados e auxilia no controle da acne. Conselho de Aplicação Calming Cream: aplicar sobre a pele completamente seca, de 1 a 2 vezes ao dia, espalhando até absorção completa. Reaplicar conforme desejado. Creme Retinol: uso Noturno. Aplique 1 ou 2 pumps sobre a pele seca e hidratada, evitando a região dos olhos, os cantos do nariz e da boca. Niacinamide B: uso diurno e noturno. Aplique uma fina camada sobre a pele completamente seca após sua rotina de limpeza facial.', 533.45, 277.9, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvf-m18tdpw6qkuw31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F21097926556', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897670237', 'Sensor De Fase Equivalente 036.907.601.c Volkswagen Original Gauss', '🚚 𝗘𝗡𝗩𝗜𝗢 𝗜𝗠𝗘𝗗𝗜𝗔𝗧𝗢 𝗘𝗠 𝗔𝗧𝗘́ 𝟭𝟮𝗛 𝗨́𝗧𝗘𝗜𝗦 Sensor de Fase Equivalente 036.907.601.C Volkswagen Gauss O sensor de fase da GAUSS é responsável por informar a posição do eixo do comando de válvulas. Essa informação, com conjunto com o sensor de rotação, permite que o carro identifique o momento exato para fazer a injeção e ignição do motor, garantindo um maior rendimento para o veículo. Observação: Os sensores de fase da Gauss são rigorosamente testados para que apresentem sempre o melhor resultado. Usando tecnologia de ponta, a Gauss hoje é uma multinacional, com mais de 20 anos do mercado e certificado pelo ISO 9001, que garante excelência de qualidade e atendimento. Especificações tecnicas do Veículo: Especificação Tecnica - Sensor de fase: Cod Produto: Gs9076 Equivalencia: 036.907.601.C (Vw) 🚚 Enviamos para todo o Brasil com segurança e rapidez! ✅ Qualquer dúvida estamos à disposição no chat.', 179.99, 179.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m5khk8yvv90090', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1272573624%2F23897670237', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394635350', 'Grill Elétrico Burguer Oster 2 Em 1 Com Estufa 110V', 'Grill Elétrico Burguer Oster 2 Em 1 Com Estufa 110V Prepare um hambúrguer completo e delicioso com o Grill Elétrico Burguer 2 em 1 da Oster. Ele possui grelha e chapa para preparar seus alimentos, além de uma estufa exclusiva para aquecer pães e derreter queijos, garantindo que tudo fique quentinho e saboroso na hora de servir. Diferenciais do Produto: 2 em 1 com Estufa: A solução completa para seu hambúrguer. Enquanto a grelha prepara a carne, a estufa superior mantém os pães e queijos aquecidos e no ponto certo. Não Gruda e Fácil de Limpar: As placas possuem revestimento antiaderente e um design inclinado que, junto com a bandeja coletora, remove o excesso de gordura e facilita a limpeza. Capacidade para a Família: Com espaço para preparar até 4 hambúrgueres na grelha, é perfeito para servir todo mundo de uma vez. Compacto e Fácil de Guardar: Desenvolvido para não ocupar muito espaço, possui um tamanho ideal para qualquer cozinha e conta com um prático porta-fio. Especificações Técnicas: Marca: Oster Modelo: OGRL500-127V Voltagem: 110V (Não é Bivolt) Código: OGRL500 Potência: 1200W (110V) Consumo: 1,2 kWh (110V) Peso: 1,9 Kg Dimensões [LxAxP]: 235 x 140 x 275 mm Garantia: 12 meses', 219.0, 219.0, NULL, 'Home Appliances > Kitchen Appliances > Toasters', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mgcp31p2tf616a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1617519379%2F22394635350', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
