INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208074814', 'Combo Instance Baunilha Intensa: Creme para Mãos 30g + Sabonete Líquido 200ml', 'O Combo Instance Baunilha Intensa que traz o Creme Perfumado Para Mãos e o Sabonete Líquido da linha para garantir uma rotina de cuidado completa para suas mãos, proporcionando limpeza suave e hidratação imediata. A vantagem é o uso combinado que intensifica a fragrância oriental gourmand e mantém a pele protegida contra o ressecamento. CREME PARA MÃOS Possui textura leve e secagem rápida para deixar suas mãos macias e protegidas. Sua fórmula com ingredientes naturais garante um toque aveludado sem danificar o brilho do esmalte. SABONETE LÍQUIDO Formulado com 91% de ingredientes naturais, este sabonete com glicerina vegetal limpa profundamente sem ressecar. Sua espuma de fácil enxágue deixa a pele suave e perfumada desde o primeiro momento do uso. Possui embalagem feita com plástico reciclado. Nenhum produto Eudora é testado em animais, ou seja, este item possui selo Cruelty Free. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 63.88, 63.88, NULL, 'Beauty > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zww-mmjd68sy6kna59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1679511787%2F58208074814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
