INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398402148', 'Prateleira para Congelador Consul CRB36/39 W10169459', 'Prateleira para Congelador Consul CRB36/39 W10169459 A Prateleira para Congelador Consul CRB36/39 W10169459 é a solução ideal para quem busca otimizar o espaço interno do freezer com praticidade e eficiência. Projetada especificamente para os modelos CRB36 e CRB39 da Consul, ela proporciona encaixe perfeito e estabilidade, garantindo melhor organização dos alimentos congelados. Seu design facilita o acesso aos itens, tornando o dia a dia na cozinha muito mais funcional. Fabricada com materiais duráveis e resistentes às baixas temperaturas, a prateleira mantém sua estrutura mesmo sob condições extremas de congelamento. Sua estrutura leve e ao mesmo tempo robusta permite o armazenamento de diversos tipos de alimentos, contribuindo para um congelador mais limpo e arrumado. Além disso, sua superfície facilita a limpeza, permitindo maior higiene e conservação do ambiente interno. Ideal para reposição ou renovação da estrutura interna do freezer, essa prateleira é uma excelente escolha para quem deseja restaurar a funcionalidade do eletrodoméstico. Com ela, é possível aproveitar melhor cada centímetro do espaço disponível e manter os alimentos organizados de forma prática e segura. Invista em mais praticidade para sua rotina com essa peça essencial para manter o desempenho e a organização do congelador Consul.', 39.9, 39.9, NULL, 'Home Appliances > Large Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7reoo-m8gnzspz94xicb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F22398402148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20098026928', 'Curvador de Tubos Hulter 1/2 HT5364A08F', 'Curvador de Tubos Hulter 1/2 HT5364A08F O Curvador de Tubos Hulter 1/2 HT5364A08F é uma ferramenta essencial para quem busca praticidade e eficiência em projetos que exigem a curvatura precisa de tubos de 1/2 polegada. Com design robusto e de fácil manuseio, ele oferece a solução ideal para trabalhos em diferentes áreas, como sistemas hidráulicos, de refrigeração e construção civil. O equipamento é fabricado com materiais de alta qualidade, garantindo resistência e durabilidade mesmo em condições exigentes. Seu mecanismo permite dobrar tubos de forma uniforme, evitando deformações e oferecendo resultados consistentes. Esse curvador destaca-se pela ergonomia e eficiência, proporcionando um trabalho confortável e menos cansativo, mesmo em tarefas prolongadas. Seu design leve facilita o transporte e o uso em diferentes locais, tornando-o uma ferramenta versátil para diversos tipos de projetos. Além disso, a precisão na curvatura permite acabamentos de alta qualidade, evitando a necessidade de retrabalhos. O modelo Hulter 1/2 HT5364A08F é um aliado indispensável para quem busca resultados precisos e um processo de trabalho mais ágil. Outro grande diferencial do Curvador de Tubos Hulter é a sua facilidade de operação. Com ajustes simples e intuitivos, ele possibilita o uso por pessoas com diferentes níveis de experiência, oferecendo excelente controle sobre o processo de curvatura. Seja para projetos de manutenção, instalação ou construção, esta ferramenta entrega resultados de qualidade com um ótimo custo-benefício, sendo uma escolha confiável para aqueles que desejam um equipamento de alto desempenho e durabilidade.', 133.9, 133.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rblo-m5ymbi1cb71453', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F20098026928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17793190414', 'Cola Artesanato Branca Pva Cola de Madeira Branca 1Kg Cola Branca Tek Bond Alta Aderência', 'Cola Branca Pva Extra - Tekbond A Cola Branca PVA Extra é uma cola a base de PVA – Acetato de Polivinila, especialmente desenvolvida para colagens em madeira onde se requeira um excelente acabamento e uma colagem perfeita. Adere a diversos artefatos de madeira como: Fórmica, aglomerados, laminados, Duratex, papel, papelão, superfícies porosas em geral. Pode ser utilizada nos processos convencionais de colagem: prensagem a frio e a quente. Modos de Uso: 1 - Aplique uma camada uniforme da cola em uma das superfícies, em seguida faça a união das peças antes da secagem da cola e prense. 2. A cura total é de 24 horas a 48 horas em função do clima, quantidade de cola e peso das peças a serem fixadas. Material onde pode ser aplicado: • Biscuit • Isopor • Madeira • MDF • Papel • Papelão • Plástico • PVC Tekbond', 48.67, 34.07, NULL, 'Stationery > School & Office Equipment > Glues', 'https://cf.shopee.com.br/file/br-11134207-820lb-mqrqisdnnu9uba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F17793190414', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21299600062', 'Relé Embraco 1/4 HP PW FF 8,5 Hulter - 220V', 'Relé Embraco 1/4 HP PW FF 8,5 Hulter - 220V O Relé Embraco 1/4 HP PW FF 8,5 Hulter - 220V é uma solução eficiente e confiável para garantir a proteção de motores elétricos em sistemas de refrigeração, compressores e eletrodomésticos que utilizam motores monofásicos. Com atuação precisa contra sobrecargas e picos de corrente, o componente contribui diretamente para o aumento da vida útil do motor, oferecendo mais segurança ao funcionamento contínuo do equipamento. Projetado para proporcionar alto desempenho, o relé da Hulter é reconhecido por sua durabilidade e pela facilidade de instalação, permitindo uma substituição ágil e sem complicações. Compatível com motores de até 1/4 HP, ele atua como uma peça fundamental na prevenção de falhas, evitando danos causados por instabilidades na rede elétrica ou sobreaquecimentos, comuns em aplicações de refrigeração.', 27.9, 27.9, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvg-mbsd1ekvq4tx31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F21299600062', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
