INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42968408558', '4 Bonecos Sonic, Tails, Shadow e Knuckles - Sonic 3 Filme', 'Quatro heróis, quatro jornadas entrelaçadas, reunidos em 5"" (12,7 cm) de pura energia do Sonic Filme 3. Sonic, Tails, Shadow e Knuckles ganham vida com detalhes que capturam seus traços únicos e a força de suas aventuras na tela. Cada figura revela um personagem cheio de personalidade, pronto para explorar mundos de amizade, desafios e descobertas. Com cores vibrantes e design fiel ao filme, esse conjunto transporta para um universo onde coragem e união brilham em cada passo. Um convite para reviver as emoções da saga Sonic 3, lado a lado com seus personagens favoritos.REGISTRO INMETRO 003311/2022', 499.99, 469.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-824go-mehazu86db7r65', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341622697%2F42968408558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
