INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894215607', 'Caixa Baú Para Ferramentas CBI030 Vonder Plus', 'Caixa baú para ferramentas plástica CBI 030 VONDER PLUS, projetada para oferecer organização e praticidade no armazenamento e transporte de ferramentas e acessórios. Ideal para uso profissional ou doméstico, combina resistência com versatilidade. Conta com sistema Cantilever que facilita o acesso aos compartimentos. A parte superior possui 12 divisões fixas e a inferior, 2 divisões fixas. A estrutura robusta inclui alça de alumínio e travas reforçadas, garantindo segurança e durabilidade. Características: Referência: 6105000300 Modelo: CBI 030 Material: Polipropileno Cor da caixa: Preta e amarela Comprimento: 580 mm Largura: 300 mm Altura: 420 mm Capacidade de carga: 30 kgf Massa aproximada (peso): 4 kg Benefícios: Sistema Cantilever para acesso prático aos compartimentos Divisões internas que otimizam a organização Alça em alumínio para transporte seguro e confortável Travas reforçadas que garantem o fechamento firme Estrutura leve e resistente para uso intenso Conteúdo da embalagem: 1x Caixa baú plástica CBI 030 VONDER PLUS', 406.38, 303.54, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdwq-mc15nwa4hc5fba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22894215607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798789928', 'Chave Grifo 14 Tipo Americana Alumínio Vonder', 'A chave grifo 14" tipo americana em alumínio VONDER é ideal para profissionais que atuam na montagem e desmontagem de tubulações e conexões metálicas. Leve e resistente, proporciona agilidade e conforto no manuseio mesmo em serviços prolongados. Seu corpo é fabricado em alumínio fundido, garantindo menor peso e reduzindo a fadiga do operador, enquanto os mordentes em aço liga oferecem alta resistência e durabilidade para trabalhos exigentes em ambientes industriais e hidráulicos. Características: Modelo: Americana Referência: 3613000014 Material: Alumínio fundido Acabamento: Pintado Capacidade de abertura: 48 mm Comprimento: 14" Massa aproximada: 0,904 kg Benefícios: Corpo leve que facilita o uso contínuo Alta resistência com mordentes em aço liga Ideal para manutenção hidráulica e industrial Boa capacidade de abertura para tubos maiores Design tradicional e eficiente em diversos tipos de obra Conteúdo da embalagem: 1x Chave grifo tipo americana em alumínio 14" VONDER', 148.86, 112.25, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdxm-md1vtva3967r8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23798789928', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
