INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24897170351', 'Microfone de Lapela Sem Fio Hello Kitty Caixa Letron Leonora - 10511', 'O Microfone de Lapela Sem Fio Hello Kitty da Letron é a escolha perfeita para quem deseja criar conteúdos com qualidade e muito charme. Estampado com a personagem mais amada do mundo, ele une funcionalidade e fofura, ideal para gravações de vídeos, entrevistas, podcasts, stories e muito mais. Com captação de áudio 360°, conexão USB-C plug and play e alcance de até 20 metros, o microfone oferece praticidade e alta performance. Recarregável e com tempo de uso de até 5 horas, ele acompanha cabo de carregamento e é compatível com diversos dispositivos. Especificações técnicas: Produto: Microfone de Lapela Sem Fio Hello Kitty Conexão: USB-C plug and play Acompanha: 1 microfone de lapela + 1 receptor + 1 cabo de carregamento Alcance: Até 20 metros Captação de áudio: 360° Tempo de uso: Até 5 horas Tempo de carregamento: Aproximadamente 90 minutos Recarregável: Sim Composição: Plástico e componentes eletrônicos Medidas do produto: 3,2 cm x 12,5 cm x 8,3 cm Peso: 68 g Indicação de uso: Gravações, vídeos, podcasts, entrevistas, stories e aulas Por que escolher o Microfone de Lapela Hello Kitty? Alta qualidade de som: Captação clara e profissional Fácil de usar: Plugou, usou - sem configurações complicadas Portátil e leve: Ideal para levar onde quiser Design exclusivo: Visual adorável da Hello Kitty Características: - Marca:Leonora - Modelo:10511 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 1 microfone de lapela + 1 receptor + 1 cabo de carregamento', 119.73, 100.9, NULL, 'Audio > Others', 'https://cf.shopee.com.br/file/sg-11134201-824h7-mf1j7iqrx1cb70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F24897170351', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697293060', 'Skate Park Bowl de Skate de Dedo - Brincadeira de Criança', 'Skate Park Bowl de Skate de Dedo - Brincadeira de Criança O skate surgiu na década de 1950, no estado da Califórnia. Os inventores do esporte foram surfistas, que em períodos de maré baixa e poucas ondas, colocaram rodinhas de patins junto a uma prancha de madeira, e assim foi criado o surfe de asfalto, mais conhecido como skate. Na década seguinte, os skatistas passaram a utilizar piscinas vazias, com o fundo arredondado, como pistas de skate, atualmente conhecidas como BOWL. Selo Inmetro: 006331/2021', 88.99, 88.99, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-7r98o-lkqvlclv02up98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F20697293060', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23435651725', 'QUEBRA CABECA CONHECA O CORPO HUMANO', 'Quebra-Cabeça Corpo Humano - Brincadeira de CriançaDesenvolvido pela marca Brincadeira de Criança, o Quebra-Cabeça Conheça o Corpo Humano é muito mais do que uma simples atividade lúdica. Este brinquedo educativo é ideal para auxiliar no desenvolvimento do raciocínio lógico, atenção, percepção visual e concentração das crianças. Com peças coloridas e figuras lúdicas, as crianças serão capazes de aprender sobre o corpo humano enquanto se divertem. Diferenciais:Auxilia no desenvolvimento do raciocínio lógico e da concentração; Peças coloridas e figuras lúdicas que facilitam o aprendizado; Material de qualidade e segurança para garantir a durabilidade; Ideal para crianças que buscam diversão aliada ao conhecimento. Mais sobre o Produto:O Quebra-Cabeça do Corpo Humano é ideal para meninos e meninas de 5 a 12 anos que gostam de aprender brincando. Estimula a criatividade e a aprendizagem de forma interativa, promovendo o conhecimento do corpo humano de maneira divertida, além de proporcionar momentos de diversão em família, combinando os estilos de brincar Descobrir e Desenvolver. Dicas de Uso:Reserve um tempo especial para montar o quebra-cabeça com a criança, incentivando-a a identificar e encaixar as peças corretamente; Explore as partes do corpo humano representadas nas peças, estimulando a curiosidade e o interesse da criança; Após montar o quebra-cabeça, aproveite para conversar sobre cada parte do corpo humano, enriquecendo o aprendizado de forma descontraída. Ficha Técnica:Marca: Brincadeira de Criança; Nome do produto: Quebra-Cabeça Corpo Humano; Idade recomendada: A partir de 5 anos; Selo Inmetro: 006333/2021 OCP 0133; Contém: 28 peças.', 41.99, 41.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7qvcu-lezra6su7h9r50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F23435651725', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
