INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18576222519', 'Escapamento Escape Moto Esportivo Gemoto Racing 3 Trioval Cg Fan Cargo Start 160 2016 2017 Ponteira', 'O Escapamento Trioval 3 da Gemoto foi projetado e desenvolvido com tecnologia de primeira linha, este modelo garante respostas mais rápidas da motocicleta, além de produzir um ronco esportivo único, sem ultrapassar os limites impostos pelos órgãos de regulação de fabricação. Especificações: - Acompanha ponteira; - Produzido em Aço de alta qualidade; - Modelo: Racing 3 Trioval; - Marca: Gemoto. Aplicações: - FAN 160 2016; - FAN 160 2017. - CARGO 160 2016; - CARGO 160 2017. - START 160 2016; - START 160 2017. Dicas: - A instalação deve ser feita por um profissional especializado. A Gemoto não se responsabiliza por instalação mal realizada; - O produto é pronto para instalação de acordo com o modelo da moto, e encaixa-se perfeitamente no lugar do original, não sendo necessário nenhum tipo de adaptação.', 352.53, 289.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Exhaust and Muffler', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9ekm1gxwxz615', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F18576222519', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393719534', 'Kit Capacete Moto Aberto Masculino e Feminino Pro Tork New Liberty 3 Three Viseira Fumê Azul', 'O Capacete Pro Tork New Liberty 3 é uma ótima opção para quem busca conforto e qualidade. Com design moderno, conta com casco injetado em ABS natural, forro antialérgico e viseira fabricada em policarbonato. Especificações: - Cores disponíveis: Amarelo, Azul, Branco, Prata, Preto, Preto Fosco, Rosa e Vermelho. - Casco fabricado em ABS natural de alto impacto; - Forro confeccionado em nylon pluma duplado antialérgico; - Cinta jugular confeccionado em nylon e fecho micrométrico; - Viseira Fumê em policarbonato com espessura de 2 mm; - Adesivo em vinil plástico, resistente as ações do clima; - Acompanha adesivo refletivo; - Modelo: New Liberty 3; - Disponível nos tamanhos: 56, 58 e 60; - Aprovado pelo INMETRO; - Marca: Pro Tork. Importante: - O CONTRAN estabelece que os capacetes do tipo aberto devem ser utilizados em vias públicas acompanhados de viseira ou óculos de proteção; - É importante escolher um capacete bem justo, pois a tendência é que ele se alargue com o uso. Portanto, se a sua medida é 56 ou 57 cm, escolha um 56 sem medo. - Não use produtos em embalagens com aerossol, pois contêm substâncias que danificam os orifícios de ventilação e o visor. OBS: - Pode haver diferença de tonalidade entre a imagem e o produto real por conta do tratamento de imagens e a calibração de cores da tela de seu monitor ou aparelho. Sportbay - Seu Esporte, Nossa Paixão.', 252.42, 194.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6ebwh4eriuo59', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F22393719534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21297192188', 'Carenagem Farol Frontal Pro Tork Pro Tork Titan 150 2011 Peças Acessórios De Moto', 'A Carenagem Do Farol Titan 150 Pro Tork é fabricada em material de alta qualidade, pintura resistente a exposição dos raios solares sem deixar de perder o brilho rapidamente. Facilita a combinação com o padrão cromático de sua moto. Especificações: - Confeccionado em termoplástico de alta resistência; - Design personalizado e mais resistente que os plásticos originais; - Peça pintada e envernizada; - Marca: Pro Tork. Aplicação: - Titan 150 2011. Instalação: - A instalação deve ser feita por um profissional especializado. A loja não se responsabiliza por instalação mal realizada.', 84.11, 48.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxlhjou8x1n6fd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F21297192188', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794466061', 'Caixa Organizadora Flat 2,35L Tampa Madeira Teca Organização Casa Escritório Banheiro Nitron', 'A Caixa Organizadora Flat com Tampa 2,35L da Nitron é a escolha ideal para quem busca praticidade, organização e estilo em um só produto. Com design moderno, funcional e minimalista, ela se adapta facilmente a diversos ambientes da casa, como quarto, banheiro, sala, lavanderia ou escritório, mantendo cada espaço sempre organizado e elegante. Produzida em polipropileno de alta qualidade e com tampa em madeira teca natural, a peça combina resistência, durabilidade e sofisticação. O acabamento refinado acrescenta um toque aconchegante e sofisticado à decoração, transformando a caixa não apenas em um item de organização, mas também em um elemento decorativo que valoriza o ambiente. Com capacidade de 2,35 litros e dimensões de 10,8 x 11,6 x 25,2 cm, é perfeita para armazenar pequenos objetos, acessórios, itens de higiene, maquiagem, documentos, materiais de escritório ou utensílios de uso frequente. Seu formato compacto permite que seja usada individualmente ou em conjunto com outras caixas da mesma linha, criando uma solução prática e versátil de organização. Mais do que funcional, a Caixa Flat da Nitron é um item que une charme, praticidade e durabilidade, sendo ideal para quem deseja ambientes bem organizados sem abrir mão do bom gosto.', 61.9, 43.95, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-824gq-mfei12ra9vyl92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1081505086%2F22794466061', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23397580743', 'Tampa Lateral Traseira sem Adesivo Lado Direito Tr50/tr100/tr125 Pro Tork Peças De Moto Reposição', 'Tampa Traseira Lateral Direita para Mini Motos TR-50F, TR-100F e TR-125F Pro Tork é fabricada para uso Off Road, trilhas e até mesmo competições, dada a sua alta resistência. Confeccionada em plástico rígido de extrema qualidade, é também muito leve. Disponível em várias cores, facilita a combinação com o padrão cromático de sua moto. Especificações: - Produto original; - Não acompanha adesivo; - Marca: Pro Tork. Aplicações: - TR-50F; - TR-100F; - TR-125F. Dica: - Antes de finalizar a compra, certifique-se de que sua moto seja compatível com algum dos modelos acima. Pois o produto é pronto para instalação e não necessita de nenhum tipo de adaptação. Instalação: - Para realizar a instalação, leve sua moto à uma oficina especializada; - A loja não se responsabiliza pela má instalação do produto.', 84.11, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd58-lw5qtt3s3dsl8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F23397580743', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
