INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997740469', 'Chuteira Penalty Max 300 Futsal Azul Preta e Branca', 'TecnologiasMicropower: Leveza, durabilidade, controle de bola e facilidade de manutenção, proporcionando aos jogadores uma vantagem competitiva em esportes como futebol.Neo Cushion: Tecnologia aplicada na entressola que a torna mais macia que as tradicionais de EVA, potencializando o amortecimento de impactos. Possui alta memória celular que proporciona maior resistência e rápida recuperação das características iniciais de amortecimento.Rotate: Ponto de giro que auxilia a movimentação.Non-Marking: Uma borracha que não marca as quadras e proporciona excelente tração.Ultra Grip: Design que confere maior aderência para o solado, em todos os tipos de quadra.HiperFlex: Canaletas posicionadas estrategicamente para auxílio na flexão e movimentação dos pés.Composição cabedal (parte superior): Micropower e Camurça sintéticaPalmilha: PU conformada e removível; facilita na higienizaçãoSolado: Borracha antiderrapanteForro: Material sintético acolchoadoCor predominante: AzulLingueta: Fina e flexívelIndicado para: FutsalGênero: UnissexOrigem: NacionalAjuste: CadarçoPeso aproximado: 610g o par nº 40', 290.9, 290.9, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/sg-11134201-7rdye-lzdgml76p6o7bc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F22997740469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
