INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258506168', 'Vaselina Spray Car80 Lubrificante Antioxidante Multiuso Alta Performance 300 ml', 'VASELINA SPRAY — LUBRIFICAÇÃO PROFISSIONAL PARA BORRACHAS E PLÁSTICOS Quando peças travam, rangem ou sofrem desgaste precoce, o problema quase nunca é a peça — é a lubrificação incorreta. A Vaselina Spray foi desenvolvida para quem exige desempenho técnico, segurança e durabilidade em aplicações automotivas, industriais e de manutenção profissional. Sua fórmula à base de vaselina industrial com aditivo EP cria uma película protetora eficiente que reduz atrito, evita ressecamento e prolonga a vida útil dos componentes, mesmo em ambientes agressivos. PRINCIPAIS BENEFÍCIOS Lubrificação eficiente de borrachas e componentes plásticos Ideal para montagem de O-rings, buchas e componentes de suspensão Facilita instalação de pneus e borrachas de para-brisa Alto poder de lubrificação com ação duradoura Resistente à água e à oxidação Não agride, não resseca e não deforma borrachas Aplicação prática em spray, inclusive em áreas de difícil acesso ONDE UTILIZAR O-rings de borracha Buchas automotivas Componentes de suspensão Borrachas de vedação Pneus e montagem técnica Borrachas de para-brisa Manutenção automotiva e industrial em geral Produto indicado tanto para uso profissional quanto para manutenção técnica de alto padrão. MODO DE USO Limpe cuidadosamente a área a ser lubrificada Agite bem a embalagem antes de usar Aplique o spray a uma distância de 5 a 10 cm Em locais de difícil acesso, utilize o prolongador Reaplique sempre que necessário PRECAUÇÕES IMPORTANTES Em contato com pele ou olhos, lavar com água em abundância Se inalado em excesso, remover para local ventilado Em caso de ingestão, não provocar vômito e procurar assistência médica Produto inflamável e envasado sob pressão Não perfurar, não reutilizar a embalagem Não expor a temperaturas superiores a 50 °C Manter fora do alcance de crianças e animais doméstico', 27.69, 26.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-820lh-mmufdzzkan7l6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1424408486%2F58258506168', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
