INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094854142', 'Carcaça Inferior da Bomba Combustível Condor Fazer 250 06–15', 'Carcaça Inferior da Bomba de Combustível Condor – Yamaha Fazer 250 2006 a 2015 Sua moto está apresentando falha de combustível, vazamento na bomba ou dificuldade de partida?A Carcaça Inferior da Bomba de Combustível Condor para Fazer 250 é a solução ideal para restaurar o sistema de alimentação, garantindo vedação correta e funcionamento seguro da bomba. Autoridade do Produto Fabricada pela Condor, este componente oferece qualidade comprovada e padrão de encaixe original, sendo indicado para substituição sem necessidade de adaptações, quando aplicada no modelo correto. MODELOS COMPATÍVEIS Yamaha Fazer 250 – 2006 a 2015 ATENÇÃO:Compatível exclusivamente com os modelos acima. Não compatível com versões após 2015 ou outros modelos não informados. CARACTERÍSTICAS TÉCNICAS Marca: Condor Função: Base inferior da bomba de combustível Sistema: Injeção eletrônica Material: Plástico técnico resistente a combustível Encaixe: Padrão original Necessita adaptação:Não BENEFÍCIOS Corrige vazamentos na base da bomba Restaura a vedação do sistema Mantém a pressão correta de combustível Ideal para manutenção preventiva Instalação simples quando realizada por profissional CONTEÚDO DA EMBALAGEM 01 Carcaça Inferior da Bomba de Combustível POR QUE COMPRAR NA KIZZ MOTO PEÇAS? Produto com procedência garantidaEnvio rápido e bem embaladoAtendimento especializadoCompra segura no marketplace', 68.98, 36.55, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820lt-mqj5lcyl2uirbc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1117095756%2F23094854142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '2969153043', 'Bola de Futevôlei Altinha XXI Penalty Amarelo/Preto', 'A Bola de Futevôlei Penalty XXI é desenvolvida exclusivamente para você mostrar suas habilidades nas areias com muito mais qualidade e eficiência nas partidas de futevôlei, por conter construção que elimina as costuras, a bola é resistente à água, garantindo durabilidade extra para você praticar o esporte na praia. E tem mais, com camada de amortecimento interno que deixa a bola mais macia, proporciona muito mais conforto ao diminuir o impacto do corpo com a bola. Adquira a sua e una lazer aos exercícios físicos! Benefícios : Ideal para Futevôlei. Máximo conforto no contato com o corpo. Maciez no toque. Resistência e durabilidade. Menor absorção de água. Alguns diferenciais técnicos : A Bola de Futevôlei Penalty XXI conta com tecnologia termofixo, onde recebe um tratamento térmico que estabiliza a estrutura, garantindo resistência, estabilidade e uniformidade. Além disso, a bola possui Câmara 6D, composta por 6 discos posicionados simetricamente, proporcionando equilíbrio total para a bola. Características : Peso: 425-440g Circunferência: 68-69cm Gomos: 32 Laminado: Pu Super Soft Construção: Ultra Fusion Câmara: 6d Sistema De Forro: Termofixo Camada Interna: Evacel Processo Extra: Dupla Colagem Miolo: Cápsula Sis Cuidados : Limpar a bola com escova ou pano limpo levemente úmido com água após utilização Secar a bola por completo Armazenar em ambiente seco e ventilado Não deixar exposta ao sol ou chuva Mantê-la sempre calibrada Conteúdo da Embalagem: 01 un. Bola de Futevôlei Altinha XXI Penalty Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa', 259.0, 259.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/61362649b5fc15adc184c2c493f38937', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429366971%2F2969153043', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
