INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194360445', 'Minilivro Contos clássicos - Cinderela', 'Encante-se com esta clássica história dos contos de fadas. Um livro com lindas ilustrações para você levar aonde quiser! 10x13cm 16 Páginas', 7.9, 1.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824gj-me5fqj1exkhy72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23194360445', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43850636248', 'Livro Plena | Fernanda Brum', 'Livro Plena | Fernanda Brum Encontrando a Plenitude em Meio aos Ciclos da Vida Fernanda Brum Em Plena, Fernanda Brum compartilha sua visão sobre a plenitude, comparando-a ao Sol que brilha no céu dos nossos corações. Porém, a plenitude não é constante, e somos desafiadas por ciclos da vida, como eclipses e entardeceres. Neste livro, a pastora e cantora revela que a verdadeira plenitude vem do entendimento dos tempos cronológico e espiritual, sempre apontando para a volta de Jesus. Por meio de histórias de vida e do ministério, você descobrirá como Deus a guiará em processos de cura e restauração, conduzindo-a a uma vida plena. Especificações do livro Plena: Título: Plena Subtítulo: Encontrando a Plenitude em Meio aos Ciclos da Vida Autor(es): Fernanda Brum Ano de Edição: 2024 Capa: Brochura Acabamento: Laminação Fosca com Verniz Localizado Miolo: Pólen Páginas: 152 Dimensões: 15.5 x 1 x 23 cm Peso: 0,250 kg ISBN: 9786557600955 Editora: Central Gospel', 38.78, 38.78, NULL, 'Books & Magazines > Books > Romance', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9ks7csapph52c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F43850636248', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20229302621', 'Dispositivo de Retorno Inox 1.1/2 Pol para Tubo de 50MM Para Piscinas SODRAMAR', 'Dispositivo de Retorno Inox 1.1/2 Pol para Tubo de 50MM Para Piscinas SODRAMARÉ um produto de excelente qualidade e que tem como principal função fazer o retorno do volume de água para a piscina gerado pela motobomba.O produto atua em conjunto com o dispositivo de hidromassagem, que é perfeito para massagear o corpo do banhista por meio do retorno de ar/água para a piscina e o dispositivo de aspiração, que capta a água da piscina para alimentar o sistema filtrante da mesma, e que deve servir de acoplamento de aspiração do fundo da piscina.DADOS TÉCNICOS:O tubo de encaixe do Dispositivo de Retorno para Piscina de Alvenaria deve ser de 50 mm.A vazão mínima deste modelo é de 2,2 m³/h, enquanto a vazão máxima é de 3,8 m³/h.A altura do Dispositivo de Retorno para Piscina de Alvenaria é de 40 cm.O modelo faz parte da linha Pratic, a qual traz um novo conceito de instalação de diversos dispositivos e acessórios em piscinas de alvenaria.Os modelos que fazem parte da linha Pratic oferecem novas soluções e muita praticidade, além de diversas possibilidades e muita funcionalidade.O Dispositivo de Retorno pratic pode ser instalado diretamente no tubo.Ele ainda possui uma canopla de acabamento em inox.Ref: 015483Marca: SodramarGarantia: 12 meses*Imagens meramente ilustrativas.', 60.9, 60.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/e942b7da7ab9f29afe346ce9a5d70a1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F20229302621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22213113070', 'Rebolo Branco 6" x 3/4" x 1.1/4" AA120 66243464692 NORTON', 'Rebolo Branco 6" x 3/4" x 1.1/4" AA120 66243464692 NORTON Dados Técnicos Aplicações: dicas de uso Indicados para afiação ou retificação de ferramentas de aço de alta dureza, de maneira rápida, com corte frio, e excelente manutenção do perfil. Destaques/diferenciais (características): Melhor manutenção do perfil do rebolo e, consequentemente, da peça-obra. Diâmetro: 6 Polegadas - 152,4 mm Espessura: 3/4 Polegadas - 31,75 mm Diâmetro do furo: 1.1/2 Polegadas - 31,75 mm Grão: 120 Tipo de grão: Óxido de alumínio Garantia: 3 meses Referência: 66243464692 Marca: NORTON * Imagens meramente ilustrativas', 101.9, 101.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-22120-exzeqh5vrclv96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F22213113070', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12745592756', 'Bíblia em Ação Infantil | Capa Dura', 'Desde que foi lançada no Brasil com exclusividade pela GEOGRÁFICA EDITORA, a série Bíblia em ação é um sucesso absoluto. Trazendo as Sagradas Escrituras na forma de histórias em quadrinhos (HQ), ela empolga os leitores com ilustrações espetaculares e texto adequado a cada faixa de público. Agora, é a vez da garotada! Bíblia em ação infantil – Uma aventura interativa da história redentora de Deus é uma deliciosa jornada pelo livro dos livros com muitas cores e aventuras. Ilustrada por Sérgio Cariello – artista brasileiro que é referência no estilo e já atuou em estúdios famosos do gênero HQ, como Marvel e DC Comics – e com textos criados por Catherine Devries, a Bíblia em ação infantil destina-se, principalmente, a crianças de até oito anos. Mas, não apenas elas serão alcançadas por essa maneira leve, divertida e apaixonante de conhecer a Palavra de Deus – ela é, de fato, uma aventura interativa e dinâmica para toda a família, pois estimula o compartilhamento das maravilhosas histórias e personagens bíblicos, com destaque para a obra salvadora de Jesus Cristo. Código do produto: 00116492Peso: 465gAutor: Cariello, Sergio e DeVries, catherineNº de páginas: 256Papel: Papel Couche 70gFormato: 16x23cmISBN: 9786556551845', 54.9, 54.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/b2231366e3a100191e64f47a4c5f1bbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F12745592756', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298283718', 'Cinto Segurança Retrátil 3 Pontas Pontos Traseiro Universal', 'ANUNCIO REFERNTE A 1 CINTO SEGURANÇA RETRATIL TRÊS PONTOS O cinto de segurança não é só um item obrigatório do veículo, ele é o que faz a diferença em caso de um acidente, pois absorve o impacto distribuindo o restante pelos pontos mais fortes do corpo. Evita que durante um acidente os ocupantes sejam lançados para fora do veículo, o que aumenta em até 5 vezes a chance de sobreviver. Impede também uma segunda colisão, ou seja, que as pessoas dentro do veículo se choquem entre si ou no interior do automóvel, por isso é de vital importância que esse item esteja dentro das condições ideais de uso. Produzido com material de excelente qualidade. TEMOS UM PREÇO DIFERENCIADO PARA MAIS UNIDADES, NOS ENVIE UMA MENSAGEM SOLICITANDO A QUANTIDADE DESEJADA, TEMOS ANÚNCIOS COM QUALQUER QUANTIDADE POSSÍVEL. Para melhor desempenho, recomenda-se instalação por profissional qualificado. Características: Materiais dos componentes: Poliéster, Aço carbono temperado e ABS. 1 anos de garantia. Benefícios do uso do cinto de segurança: Reduz o risco de ferimentos graves em acidentes de trânsito. Mantém o corpo estabilizado, evitando o impacto contra o volante ou painel. Garante segurança e conforto durante a condução. Atende às normas de segurança veicular exigidas por lei. Evita multas e pontuação na CNH por uso incorreto. Indicado para todos os veículos: carros, caminhonetes e utilitários. Fácil instalação e reposição, ideal para manutenção preventiva. Custo-benefício alto, sendo essencial para a segurança automotiva. Recomendações: - Instalar com apoio de profissional qualificado. - Garantia de 6 meses.', 97.0, 97.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdx5-mdfn96w18rz8be', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1604698269%2F21298283718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28290315706', 'Kit Cachos dos Sonhos Elseve L''Oréal Paris - Shampoo 200ml + Condicionador 200ml', 'Kit Cachos dos Sonhos Elseve L''Oréal Paris - Shampoo 200ml + Condicionador 200ml Sonha com cachos longos, fortes e definidos? O Shampoo Nutri Preenchedor de Elseve , além de limpar as impurezas, preenche o cabelo com nutrição profunda até as pontas, para cachos mais longos, fortes e definidos desde o primeiro uso. O Condicionador Selador de Elseve desembaraça instantaneamente os fios e preenche o cabelo com nutrição profunda até as pontas, para cachos mais longos, fortes e definidos desde o primeiro uso. Com nosso poderoso coquetel, nossa fórmula trata e sela os cachos até as pontas para salvar até os últimos 3 cm dos seus cachos. Com Ácido Hialurônico que preenche a fibra capilar com hidratação profunda e Óleo de Rícino que nutre profundamente e sela os fios até as pontas fortalecendo e definindo os cachos.​', 57.9, 46.15, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdq0ndi584vt7d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295597776%2F28290315706', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28736591024', 'A Bíblia Para Colorir | Volume 5', 'Livro A Bíblia Para Colorir | Volume 5 Jesus, Pascoá, Ascenção de Cristo , Pentecostes e Apóstolo Paulo Procurando uma alternativa enriquecedora ao uso excessivo de eletrônicos por crianças ? Apresentamos a Bíblia para Colorir , uma coleção que traz a História da Salvação de maneira acessível e recreativa. Este livro pode ser explorado individualmente pelas crianças ou em momentos devocionais em casa e na igreja , promovendo um tempo significativo em família . A autora concebeu ilustrações encantadoras, destinadas a inspirar e cativar as crianças de forma lúdica e criativa através da Palavra de Deus. Ao colorir cada página, nossa aspiração é conduzir os pequenos a Jesus, cultivando alegria e graça, para crescerem em sabedoria e reverência ao Senhor. Uma proposta que combina aprendizado e diversão, oferecendo uma experiência única de conexão com os princípios sagrados. Especificações do livro A Bíblia Para Colorir Título: A Bíblia Para Colorir Autor(es): Claudia Kündig Subtítulo Jesus, Pascoá, Ascenção de Cristo, Pentecostes e Apóstolo Paulo Ano de Edição: 2024 Capa: Brochura Acabamento: Laminação Brilhante Miolo: Papel Offset 70 g/m² Páginas: 48 Dimensões: Altura: 24 cm Largura: 17 cm Profundidade: 0,5 cm Peso: 0,100 kg ISBN: 9788578393359 Editora: Esperança', 11.31, 11.31, NULL, 'Books & Magazines > Books > Sticker & Colouring Books', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9kt10fsdeyq00', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F28736591024', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
