INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23330824707', 'Deus na Era Secular | Timothy Keller', 'Deus na Era SecularComo Céticos Podem Encontrar Sentido no Cristianismo Vivemos em uma época que valoriza a razão empírica, a evolução do progresso humano e o direito de todos escolherem sua própria expressão de significado, propósito e alegria. Para muitos hoje, a ideia de Deus ou de um poder superior não faz mais nenhum sentido. Para muitos, a fé e a religião já não podem oferecer nada de valor. Como seres humanos, não podemos viver sem satisfação, sentido, liberdade, identidade, justiça e esperança. Por isso, neste novo livro, Timothy Keller, pastor e autor best-seller do New York Times, convida o cético e o estudante de filosofia e de religião a considerar que o cristianismo ainda é a resposta para todas essas necessidades. Escrito para crentes e para quem ainda não vê razões para crer, Deus na era secular lança luz sobre o profundo valor e importância do cristianismo em nossas vidas. Título: Deus na Era Secular Subtitulo: Como Céticos Podem Encontrar Sentido no Cristianismo Autor: Timothy Keller Páginas: 320 Formato: 22,8 x 16 x 1,6 cm Peso: 0.481 kg. ISBN: 22,8 x 16 x 1,6 cm Editora: Vida Nova', 76.41, 76.41, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134201-23030-o7s66klmihov22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F23330824707', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
