INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22999154343', 'Jane de Lantern Hill | Lucy Maud Montgomery', 'Desde que conseguia se lembrar, Jane Stuart e a mãe viveram com a avó em uma mansão sombria em Toronto. Jane sempre acreditou que seu pai estava morto, até que ela acidentalmente soube que ele estava vivo, bem e morando na Ilha do Príncipe Edward. Depois de passar o verão na casa dele em Lantern Hill, fazendo todas as coisas maravilhosas que sua avó considera impróprias para uma dama, Jane ousa sonhar que poderia haver uma casa assim em Toronto... Uma casa onde ela, a mãe e o pai pudessem morar juntos sem a avó dirigindo suas vidas. Uma casa que poderia ser chamada de lar.256 páginas15,5x22,6 cm', 17.9, 14.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821d1-mgloydm5lp8r42', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22999154343', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4089533199', 'Chá Abdomen 140g + Kit Abdomen Dia Noite Bodyaction', 'CHÁ ABDOMEN INGREDIENTES: Hibisco Extrato Seco Solúvel (Hibiscos sabdariffa L.), Guaraná em pó (Paullinina cupana L.), Capim Limão em Pó (Cymbopogon citratus stapf), Carqueja em Pó (Baccharis genistelloides), Chá Verde Extrato Instantâneo (Camellia sinensis L.), Framboesa Extrato Seco Solúvel (Rubus idaeus L.), Laranja Amarga (Citrus aurantium L.), Estévia (Stevia rebaundiana Bert), Especiarias Aromatizantes Gengibre Extrato Seco (Zingiber officinalis Roscoe), Canela Extrato Seco (Cinnamomum spp), Pimenta Vermelha (Capsicum frutescens L.) e Aroma Sintético Idêntico ao natural de Limão. NÃO CONTÉM GLÚTEN. ALÉRGICOS: PODE CONTER AIPO E MOSTARDA. MODO DE PREPARO: Diluir 7 g (1 scoop) em 150 ml (1 copo americano) de água. Pode ser consumido quente ou frio. SUGESTÃO DE USO: Consumir 1 (uma) à 2 (duas) vezes ao dia, preferencialmente após as refeições, ou conforme recomendado pelo nutricionista ou médico. INDICADO PARA MAIORES DE 19 ANOS. ADVERTÊNCIAS: “CONTÉM PRODUTOS NATURAIS QUE PODEM APRESENTAR RESÍDUOS E VARIAÇÕES DE COR”. “PORTADORES DE ENFERMIDADES HEPÁTICAS OU RENAIS DEVEM CONSULTAR O MÉDICO ANTES DE CONSUMIR O PRODUTO”. “NÃO CONSUMIR DE FORMA CONTÍNUA POR MAIS DE QUATRO SEMANAS”. CONSERVAÇÃO: Manter em lugar fresco, não úmido e ao abrigo de luz. Não consumir o produto se o lacre estiver violado. Após aberto, consumir preferencialmente em 60 dias. _____________________________________ THERMO ABDOMEN® INGREDIENTES: Cafeína, Extrato de Guaraná em pó (Paullinia cupana), Extrato de Laranja Moro (Citrus sinensis (L.) Osbeck), Estabilizante Carbonato de Cálcio e Antiumectantes Estearato de Magnésio. INGREDIENTES DO REVESTIMENTO: Glaceante Polietilenoglicol, Estabilizante Polivinilpirrolidona e Corantes Dióxido de Titânio e Vermelho 40. NÃO CONTÉM GLÚTEN. SUGESTÃO DE USO: Consumir 2 (dois) tabletes ao dia, sendo 1 (um) pela manhã e 1 (um) após o almoço ou conforme orientação de nutricionista ou médico. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. EXCLUSIVO PARA ATLETAS. ADVERTÊNCIAS: “ESTE PRODUTO NÃO É UM MEDICAMENTO”. “NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM”. “MANTENHA FORA DO ALCANCE DE CRIANÇAS”. “ESTE PRODUTO NÃO DEVE SER CONSUMIDO POR GESTANTES, LACTANTES E CRIANÇAS”. CONSERVAÇÃO: Manter em lugar fresco, não úmido e ao abrigo de luz. Não consumir o produto se a embalagem de proteção estiver violada. Após aberto, consumir em até 24 horas. _____________________________________ NIGHT ABDOMEN® INGREDIENTES: Carnitina (L-Carnitina), Triptofano (L-Triptofano), Glicina, Cártamo em pó, Colina (Bitartarato de Colina), Magnésio (Óxido de Magnésio), Zinco (Bisglicinato de Zinco), Vitamina B6 (Piridoxina), Cromo (Picolinato de Cromo), Antiumectantes Estearato de Magnésio, Talco Farmacêutico e Dióxido de Silício. INGREDIENTES DA CÁPSULA: Gelatina, Água Potável Filtrada e Corantes Dióxido de Titânio, Azul Brilhante e Vermelho 40. NÃO CONTÉM GLÚTEN. SUGESTÃO DE USO: Sugere-se a ingestão de 2 (duas) cápsulas 1 (uma) vez ao dia, preferencialmente de 30 à 60 minutos antes de dormir. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. ADVERTÊNCIAS: “ESTE PRODUTO NÃO É UM MEDICAMENTO”. “NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM”. “MANTENHA FORA DO ALCANCE DE CRIANÇAS”. “ESTE PRODUTO NÃO DEVE SER CONSUMIDO POR GESTANTES, LACTANTES E CRIANÇAS”. CONSERVAÇÃO: Manter em lugar fresco, não úmido e ao abrigo de luz. Não consumir o produto se a embalagem de proteção estiver violada. Após aberto, consumir imediatamente. _____________________________________ Uma nutrição equilibrada tem um papel muito importante na qualidade de vida. Com o ritmo acelerado de muitas pessoas, às vezes, é muito difícil prestar atenção a todos os requisitos que o corpo precisa para estar saudável e forte. Neste sentido, os suplementos cumprem a função de complementar a alimentação e ajudam a obter as vitaminas, minerais, proteínas e outros componentes indispensáveis para o correto funcionamento do organismo. *Este produto é um suplemento dietético, não é um medicamento. Suplementa Ante dietas insuficientes. Consulte seu médico e / ou farmacêutico.', 186.12, 148.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7at9lexm3ik66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443076516%2F4089533199', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
