INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494193430', 'Capacete Fly Drive 2 HG Loko', 'Capacete Fly Drive 2 Drive 2, o capacete com design mais inovador da Fly. Com seu casco aerodinâmico, traz segurança, conforto, modernidade e muito estilo, somados aos grafismos diferenciados. Características técnicas - Drive 2: Casco aerodinâmico, com linhas modernas e atuais Duas entradas de ar (inferior e superior) e exaustão traseira, oferecendo mais conforto térmico Viseira de 2 mm em policarbonato com sistema de troca rápida Narigueira que melhora o fluxo de ar interno Forração interna com excelente toque, removível, lavável e antialérgica Cinta jugular com fecho micrométrico Acabamento em verniz HG (High Gloss)', 259.9, 259.9, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmets', 'https://cf.shopee.com.br/file/sg-11134201-7rdvf-mbo4eabbp65260', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1564156677%2F23494193430', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
