INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297411767', 'Kit 2 Fraldas Turma da Mônica Baby Jumbo RN com 36un cada', 'O Kit contém: 2 pacotes de Fraldas Turma da Mônica Baby Jumbo RN com 36un cada. A Turma da Mônica Baby uniu proteção e conforto em uma nova opção de fralda, para garantir que seu bebê cresça feliz e tenha as melhores lembranças da sua infância. A Nova fralda Turma da Mônica Baby possui a nova Tecnologia QuatroSec para que ele fique calmo, tranquilo e seguro durante o dia e a noite toda. Conta com um exclusivo sistema de canais que distribui mais rápido o xixi, barreiras anti-vazamento e uma fina camada extra que ajuda a manter o bebê sequinho por até 12 horas, além de cintura elástica que proporciona um perfeito ajuste no corpinho.', 77.77, 58.62, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-820l5-mo04a5exbxmq98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F20297411767', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
