INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40961639598', 'Kit Jogo Pano De Prato Cozinha Copa Cheff Algodão Sortidos', 'Transforme sua cozinha com charme e praticidade com o Kit Panos de Prato Atoalhado Copa Chef. Com cores sólidas e modernas, esses panos unem beleza e funcionalidade para o dia a dia. Confeccionados em tecido felpudo de alta absorção, possuem composição de 62% algodão, 35% poliéster e 3% viscose, garantindo maciez, resistência e secagem eficiente. Cada pano mede 40x60 cm, tamanho ideal para facilitar suas tarefas na cozinha com estilo. Perfeitos para secar louças, mãos ou decorar o ambiente, os panos da linha Copa Chef são uma excelente escolha para quem preza por qualidade e bom gosto. NÃO É POSSIVEL REALIZAR ALTERAÇÃO NO KIT CORES CONFORME ANÚNCIO O que acompanha: - Panos de Prato 40x60 cm Composição: -62% Algodão -35% Poliéster -3% Viscose', 69.9, 35.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Cloths', 'https://cf.shopee.com.br/file/sg-11134201-7rdy6-md26kp08n22odb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816024645%2F40961639598', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259397424', 'Camera de Ré Estacionamento Automotiva E-Tech ET-CAM 08 Universal Encaixe Borboleta Parachoque Colorida Resistente Água', 'Camera de Ré Estacionamento Automotiva E-Tech Universal ET-CAM 08 Encaixe Borboleta Parachoque Colorida Resistente Água Linha Guia Compatível com Monitores e Dvd''s Encaixe Borboleta Encaixe Para-choque Serra Copo 16,5 mm Colorida A Câmera de Estacionamento E-Tech 2 em 1 é boa? Como posso visualizar as imagens que ela transmite? Sim! A Câmera de Estacionamento é boa e para aproveitar os benefícios da sua câmera de ré, você deve ter um display monitor ou dvd para poder visualizar as imagens. O que acompanha na embalagem da Câmera de Estacionamento Mista E-Tech? A Câmera de Estacionamento Mista E-Tech acompanha: 1 Câmera 1 Cabo RCA 1 Cabo de Alimentação 1 Broca Especificações Técnicas Câmera Ré Automotiva E-Tech Mista Furada e Borboleta: Vídeo: Colorido Sistema: PAL / NTSC Resolução: 480 Linhas Cor Externa: Preta Sensor de Imagem: CMOS COLOR Resolução Horizontal: 400 TVL Tamanho da Lente: 1,8 mm Alimentação: 12 VDC Consumo de Energia: 60 mA Pixels Efetivos PAL / NTSC: 628 x 586 / 656 x 492 Comprimento do Cabo: 5,5 m Parâmetros para Perfeito Funcionamento Voltagem: 10 ~ 15 V Temperatura: -20º C ~ 70º C Mínima Iluminação: 0,1 Lux Importante: A instalação deve ser feita por um profissional especializado. Nós não nos responsabilizamos por instalação mal realizada. As imagens são meramente ilustradas, pode ocorrer mudança sem prévio aviso, porém as características técnicas são sempre preservadas.', 35.37, 35.37, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Parking Cameras and Sensors', 'https://cf.shopee.com.br/file/sg-11134201-820nr-mneevdvbrnr4a5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fs