INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997600656', 'Refil Filtro de Água Natural para Mini Avant Ibbl', 'O Refil Filtro Natural Mini Avanti da IBBL é compatível com os purificadores de água Avanti, Mio e Vivax (inclusive o modelo Mini). Com tripla ação filtrante, ele elimina impurezas como areia, barro e sedimentos e reduz o cloro, além de inibir a proliferação de micro-organismos. Ideal para garantir água pura, saborosa e mais saudável em sua rotina. Diferenciais: Tripla filtração eficiente — retém partículas e sedimentos (classe C) e reduz o cloro livre presente na água. Controle microbiológico — ação bacteriostática que impede a proliferação de bactérias. Instalação prática com sistema "Girou, Trocou" — substituição rápida, sem necessidade de assistência técnica. Certificado pelo INMETRO, garantindo segurança e qualidade na filtragem. Compatibilidade — pode ser usado nos modelos Avanti, Mio, Vivax e Vivax UP da IBBL. Durabilidade confiável — filtra até 2.000 litros ou até 6 meses, conforme o que ocorrer primeiro. Diferenciais: - Pode ser usado em todos os purificadores de água natural IBBL; - Possui tripla filtração: retém partículas de areia, barro, sedimentos e reduz o cloro existente na água, promovendo controle do nível microbiológico; - O prático sistema Girou Trocou garante ao usuário uma fácil substituição do filtro e manutenção do equipamento.', 73.62, 58.9, NULL, 'Home Appliances > Kitchen Appliances > Water Filters, Coolers & Dispensers', 'https://cf.shopee.com.br/file/sg-11134201-82612-ml5k3qgdzea257', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F23997600656', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394225634', 'Brinquedo Pet Mor Sorvete Pelúcia', 'O Brinquedo Pet Mor Sorvete Pelúcia é uma opção divertida, fofa e segura para entreter seu pet no dia a dia. Com formato de picolé e acabamento em pelúcia macia, ele estimula o instinto natural de brincar e morder, mantendo o animal ativo e feliz. Ideal para cães de pequeno e médio porte, é leve, colorido e encantador, além de ser fácil de carregar e lavar. Uma excelente escolha para momentos de lazer com o seu pet. Diferenciais: Design lúdico em formato de sorvete Pelúcia macia e agradável ao toque Leve, colorido e divertido para o pet Ideal para cães de pequeno e médio porte Ajuda no alívio do estresse e na distração do animal Acabamento seguro e resistente para mordidas moderadas', 39.87, 31.9, NULL, 'Pets > Pet Accessories > Bowls & Feeders', 'https://cf.shopee.com.br/file/sg-11134201-82604-mlw516nu14p475', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F23394225634', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
