INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398708187', 'Creme Hidratante Corporal Calmante – Calming Body Cream - Creamy Skincare - 200ml', 'O que é? O Calming Body Cream é uma loção hidratante corporal desenvolvida para todos os tipos de pele, especialmente as peles secas, ressecadas e sensíveis. Oferece hidratação imediata e prolongada de até 24h, enquanto acalma e suaviza a pele, aliviando as sensações de desconforto da pele seca, como descamação, coceira e vermelhidão já no primeiro uso. Sua fórmula leve e de rápida absorção conta com o exclusivo Hypskin®, além de pantenol, alantoína, proteínas vegetais, extratos de aloe vera e camomila, que juntos contribuem para acalmar, reparar e fortalecer a pele, deixando-a mais radiante e macia. Contém óleo de girassol, manteiga de karité e glicerina, emolientes naturais que proporcionam um filme leve e hidratante, reduzindo a perda de água da pele. Com o uso contínuo, o Calming Body Cream reforça a barreira cutânea, intensificando a proteção contra os fatores externos.', 84.72, 80.49, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfbjebppwflxc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1304513381%2F23398708187', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23538618220', 'Estojo Para Pincéis de Maquiagem Cinza Ana Hickmann', 'Sinta-se poderosa e confiante com a linha de maquiagens de Ana Hickmann. Produtos para rosto, olhos, boca e acessórios como esponjas, curvex, pincéis profissionais e kits. Produtos de alta performance. Seja a protagonista do seu próprio beauty show! O Brush Case foi desenvolvido para guardar os pincéis de maquiagem de forma prática e segura. Praticidade, não amassa as cerdas, mantém os pincéis livres de sujeira. Use o Brush Case para manter os seus pincéis seguros e limpos. Guarde com as cerdas viradas para cima. Não esqueça de fechar os botões laterais. Material: Couro ecológico, papelão, plástico e alumínio. * Produto Vegano *', 49.9, 49.9, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/br-11134207-820l5-mlxtcgpwrx1c4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F984347359%2F23538618220', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
