INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23791652330', 'Telefone Fixo com Fio Intelbras Pleno Sem Chave 3 Funções Preto Grafite', 'O telefone Pleno chegou para levar a medalha de ouro. É resistente, prático e tem design moderno, totalmente brasileiro. Este nasceu para brilhar. O Pleno é um telefone resistente e prático, ideal para ser utilizado em casas, escritórios, consultórios ou empresas. Totalmente brasileiro, o modelo conta com 3 volumes de campainha, 1 tipo de toque e funções Flash, Rediscar e Mudo. POSIÇÃO MESA OU PAREDE O Pleno pode ser utilizado nas posições mesa ou parede. Você escolhe a melhor opção. DUAS OPÇÕES DE COR Você escolhe a cor que mais combina com seu ambiente: preto ou cinza-ártico. DESCANSO PARA O FONE Caso seja necessário deixar uma ligação em espera, basta colocar o fone no descanso (acima do gancho). Essa facilidade é utilizada somente quando o aparelho está fixado na parede. CARACTERÍSTICAS: - 2 tipos de toque; - 3 níveis de volume de campainha; - Design moderno; - Funções flash, rediscar e mudo; - 2 tipos de timbre; - Com descanso para o fone; - Teclado alfanumérico. ESPECIFICAÇÕES TÉCNICAS: - Marca: Intelbras - Modelo: Pleno - Viva Voz: Não - Identificador de Chamadas: Não - Tipos de toque: 02 - Tipos de timbre: 02 - Níveis de volume: 03 - Garantia: 12 meses - Dimensões (A x L x C): 8,2 x 13,5 x 18,0 cm - Peso: 0,375 kg CONTEÚDO DA EMBALAGEM: - 01 Telefone com fio - 01 Cabo de linha telefônica - 01 Cabo espiralado', 79.9, 77.9, NULL, 'Home Appliances > Small Household Appliances > Telephones', 'https://cf.shopee.com.br/file/sg-11134201-7qvfy-lim2wkt7ysqff1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F959567682%2F23791652330', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21797128766', 'Brinquedos Boneca Coleção Frutinhas Limão com Cheirinho de Frutas Plástico Vinil 19cm Verde Cotiplas - 2512', 'Essas lindas bonequinhas vão fazer a alegria das crianças. As frutinhas estão de volta e ainda mais lindas. Brincar de boneca nunca foi tão divertido. Essas são as Frutinhas, São lindas bonequinhas fofinhas com cheirinho de frutas. São vários modelos para colecionar e brincar muito. Características: - Marca: Cotiplás - Modelo: 2512 *Imagens meramente ilustrativas. Especificações Técnicas: - Idade Recomendada: Acima de 3 anos. - Cheirinho de Frutas - Material: Plástico Vinil - Inmetro: CE-BRI/IQB 0228 IQB-OCP 006 - Altura: 19cm Conteúdo da embalagem: - 1x Boneca Coleção Frutinha Limão.', 39.41, 35.47, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7qvfh-liukn3dmnqj174', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356143297%2F21797128766', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399592210', 'Mesa de Jantar Kappesberg em Madeira Maciça com Tampo de Vidro Preto Fosco 200cm', 'Nunca foi tão fácil transformar seu ambiente com estilo e elegância como agora, com o Conjunto CSJ019CA da Linha Sala de Jantar Premium da Kappesberg. Com um estilo clássico, ela será o destaque do seu espaço. A base é produzida em madeira de eucalipto, garante resistência e estabilidade em todos os momentos. E para completar seu design, os pés contam com detalhe usinado, deixando a peça ainda mais elegante. Medindo 77cm de altura, 208,8cm de largura e 108,7cm de profundidade, ela possui uma travessa central, garantindo mais estabilidade, e quando combinada ao tampo retangular, ela acomoda até oito pessoas. Produzido em chapa MDF de 25mm e medindo 1m de largura e 2m de comprimento, além de muito resistente, o tampo conta com bordas chanfradas, garantindo segurança e um acabamento lindo. Pintado na cor preto fosco, seu diferencial fica por conta do vidro na mesma cor, completando seu design e garantindo ainda mais beleza e estilo para seu ambiente. Tranforme e renove seus momentos com a Linha Sala de Jantar Premium da Kappesberg. Informações importantes: As imagens são meramente ilustrativas, não acompanha acessórios; Pode haver variação de cor de acordo com a calibragem da tela onde o produto está sendo visualizado; Este anúncio acompanha tampo em MDF e base em madeira maciça; O tampo possui a espessura de 34mm, sendo 4mm do vidro temperado e 30mm do tampo usinado em MDF. Garantindo mais estabilidade e resistência para o seu produto; Todos nossos móveis são entregues desmontados; A montagem é sempre por conta do cliente (orientamos a contratação de um profissional qualificado, o manual de montagem acompanha o produto); O vídeo do produto pode ser genérico, então atente-se às imagens do anúncio para optar pela cor/modelo.', 4420.59, 4199.56, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-822yl-mi4j9ge3rzltfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1316611304%2F19399592210', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
