INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894690827', 'LEGGING FITNESS FEMININA DEGRADÊ MODELA BUMBUM SEAMLESS+ DLK', 'Legging Fitness Feminina Degradê Modela Bumbum Seamless+ Liberdade de Movimentos e Conforto Descubra o máximo de conforto e estilo com a Legging Fitness Feminina Degradê Modela Bumbum. Confeccionada em tecido extra macio e com detalhe canelado nas laterais, essa peça é a escolha ideal para quem busca liberdade de movimentos durante as atividades físicas. A tecnologia Seamless, sem costura visível, elimina zonas de fricção, garantindo conforto incomparável. Experimente uma sensação única de leveza enquanto você se move, sem restrições. Design Estratégico para um Ajuste Perfeito Destaque suas curvas naturais com a Legging Fitness Modela Bumbum. O cós alto duplo com textura canelada oferece compressão que sustenta o abdômen, enquanto o design molinho do bumbum proporciona um ajuste anatômico perfeito que ajuda a modelar a região, realçando o bumbum de forma sútil e valorizando o contorno natural do seu corpo. Essa legging é feita com alta Tecnologia Seamless - sem costura, que garante um toque macio, suave e alta respirabilidade, proporcionando extremo conforto e liberdade de movimentos para atividades como yoga, corrida ou treino na academia.', 197.99, 197.99, NULL, 'Women Clothes > Pants & Leggings > Leggings & Treggings', 'https://cf.shopee.com.br/file/sg-11134201-821fb-mh6aa9i9dqfid7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F22894690827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194706616', 'MACAQUINHO FITNESS FEMININO COM BOLSOS OASIS DLK', 'Macaquinho Fitness Feminino Com Bolsos Oasis O Macaquinho Fitness Feminino Com Bolsos Oasis é a peça ideal para quem busca desempenho, conforto e proteção em seus treinos. Esse macaquinho tem um design moderno e é ideal para suas atividades físicas, garantindo conforto e estilo. Tecido de Alta Performance O Macaquinho Fitness é feito em tecido super macio. Ele é confortável e proporciona sensação agradável à pele, ideal para treinos intensos. A tecnologia de secagem rápida mantém você seca e confortável, permitindo que o suor evapore rapidamente durante suas atividades. Além disso, este macaquinho oferece proteção solar UV 50+, protegendo sua pele durante treinos ao ar livre. Design e Funcionalidade Com esse Macaquinho Fitness você tem o melhor em tecnologia de tecidos e design funcional. Seus bolsos laterais espaçosos oferecem praticidade incomparável, mantendo seus itens essenciais ao alcance durante seus exercícios. Seja na academia, corrida ou ioga ao ar livre, ele oferece a combinação perfeita entre estilo, proteção e conforto!', 170.99, 170.99, NULL, 'Women Clothes > Jumpsuits, Playsuits & Overalls > Jumpsuits', 'https://cf.shopee.com.br/file/sg-11134201-821de-mgzdlwkr1dzgb6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F22194706616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
