INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793599264', 'Plantadeira Adubadeira Agricultora Semente 3kg Agrícola 2 reservatórios 14 Bicos', 'Plantadeira Adubadeira 3Kg Importway A Plantadeira Adubadeira da Importway é uma excelente opção para pequenas hortas, pois é um equipamento agrícola utilizado para dosar e plantar sementes maiores e partes vegetativas. Proporcionando maior produtividade, sendo muito prática para plantações em hortas que exigem trabalho manual Especificações: • Marca: Importway • Modelo: IWAS009 • Planta e fertiliza ao mesmo tempo • Plantadeira composta por 2 reservatórios (um para semente e outro para fertilizante) e 14 bicos • Material: PC e ABS • Taxa de semeadura por buraco: 1 a 2 sementes • Capacidade de adubo e/ou sementes: 3kg • Indicado para sementes como milho, soja, amendoim, grão de bico, algodão etc. Você está comprando: 01 Plantadeira Adubadeira 3Kg Importway "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega. *Garantia 90 dias. *Imagens meramente ilustrativas Importway Inovação e Qualidade desde 2007', 1552.21, 1066.03, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfh6-m4d9h6sttsnzfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242218284%2F23793599264', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
