INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494282484', 'Loção Hidratante Dermo Health 10% Ureia Pele Seca e Áspera 150g', 'Dermo Health Loção Hidratante 10% Ureia – Hidratação intensa para pele seca A Loção Hidratante com 10% de Ureia da Dermo Health foi desenvolvida para hidratar profundamente peles secas e ásperas. Dermatologicamente testada, sem fragrância e de rápida absorção, ela ajuda a restaurar a barreira cutânea, deixando a pele macia e suave por mais tempo. Destaques do produto: Hidratante corporal para pele seca e áspera Hidratação intensa e duradoura Ajuda na reparação da barreira cutânea Fórmula sem fragrância Dermatologicamente testado Modo de usar: Aplique uma quantidade generosa na pele limpa e seca, espalhando com movimentos circulares até a completa absorção. Reaplique quando necessário, especialmente nas áreas mais ressecadas. Composição: Ureia a 10% Água purificada Emolientes e umectantes Agentes condicionantes Base dermatológica hipoalergênica Loção x Creme Hidratante – Qual escolher? Loção Hidratante: Textura leve, rápida absorção Mais água que óleo: ideal para peles normais a levemente secas Indicado para climas quentes Sensação refrescante e leve na pele Creme Hidratante: Textura densa, maior poder de hidratação Mais óleo que água: ideal para peles secas a muito secas Recomendado para áreas ressecadas (cotovelos, joelhos, pés) e climas frios Sensação mais rica e nutritiva A escolha depende do tipo de pele, clima e necessidade de hidratação. Benefícios da Ureia em dermocosméticos: Hidratação profunda: atrai e retém água na pele Esfoliação suave: promove renovação celular Melhora a absorção de ativos: potencializa outros ingredientes Ação calmante: alivia coceiras e irritações leves Reparação da barreira cutânea: protege contra agressões externas Auxilia no tratamento de condições dermatológicas: como dermatite atópica, psoríase e ictiose Ação antipruriginosa: reduz a coceira em peles secas Controle da descamação: mantém a pele lisa e uniforme A ureia é altamente eficaz em promover hidratação, regeneração e alívio para a pele seca e sensibilizada, sendo um ativo essencial em produtos dermocosméticos. Dica de cuidado diário: Manter uma rotina de skincare é fundamental para garantir uma pele saudável, hidratada e protegida contra o envelhecimento precoce. Incorporar produtos com ureia e outros ativos específicos potencializa os resultados.', 39.21, 39.21, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdw9-mcuq226uq89a01', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F22494282484', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793824497', 'Spray Corporal Antiacne Isdin Oily Skin Acniben+ 150ml', 'O Spray Corporal Antiacne Isdin Oily Skin Acniben+ foi desenvolvido especialmente para peles oleosas e acneicas. Ideal para áreas de difícil alcance, como costas e peito, seu uso reduz a acne do corpo e renova as células da superfície da pele através da esfoliação.', 228.41, 228.41, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-7rd6y-m79mwrgq3v1ycc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23793824497', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
