INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259039920', 'Sabonete Barra Frésia e Pêssego Flor de Ypê', 'O sabonete Flor de Ypê Frésia e Pêssego oferece uma experiência de banho que vai além da simples limpeza, combinando óleos essenciais e glicerina, e é livre de parabenos. Com a exclusiva tecnologia Flower Pulse, que realça o perfume do seu banho, proporciona uma pele macia, cuidada e perfumada por mais tempo. * Testado dermatologicamente * Com óleos essenciais de frésia e pêssego * Tecnologia Flower Pulse', 2.49, 2.49, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-8259p-mqnelwhpcvm5cb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555155%2F58259039920', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093143080', 'Café Torrado e Moído L''OR Ultimo 250g', 'A combinação de grãos de café 100% arábica da linha L’OR Torras revela os sabores e aromas que as diferentes intensidades de torra podem proporcionar. Envolva-se com o sabor de L’OR Ultimo, a experiência mais intensa de L’OR. Um café encorpado, com torra clara, de intensidade marcante e notas de caramelo escuro.', 27.9, 27.9, NULL, 'Food & Beverages > Beverages > Coffee', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mefq668a2fb678', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1281578116%2F22093143080', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4192642331', 'Livro - A Pequena Sereia - Ciranda Cultural', 'Envolva-se com as aventuras da Pequena Sereia. Seu sonho é subir à superfície. Quando esse dia chega, ela conhece um príncipe e se apaixona por ele. Será que ela o conquistará? Descubra neste livro encantador. Editora: Ciranda Cultural Edição: 2, 2018 Autor: Ciranda Cultural Idioma: Português Páginas: 16 Dimensões: L 21.00 x A 27.50 x E 0.10 ISBN: 9788538081036', 7.9, 5.53, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/62eee268e35f341848d4dd6c0890e2f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F4192642331', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793972634', 'Impermeabilizante e Plastificante para Argamassa - ImperSika® - Branco - 18L - SIKA', 'IMPERSIKA® - ADITIVO LÍQUIDO IMPERMEABILIZANTE E PLASTIFICANTE - BALDE 18L - BRANCO | SIKA Transforme suas obras com o ImperSika®, um aditivo líquido de alta performance que impermeabiliza e plastifica argamassas, melhorando a trabalhabilidade sem a necessidade de aumentar a água utilizada no preparo. Ideal para diversas aplicações, este produto é a solução perfeita para garantir a durabilidade e a resistência das suas construções. Características do Produto: - Volume: 18 Litros - Base Química: Solução de sais inorgânicos, polímeros, aditivos e biocida. - Cor: Líquido branco Áreas de Aplicação: - Revestimentos Internos e Externos: Ideal para paredes e fachadas, garantindo impermeabilidade. - Assentamento de Blocos e Tijolos: Previne a umidade ascendente em alvenarias. - Subsolos e Fundações: Protege estruturas em contato com o solo. - Pisos e Muros de Arrimo: Proporciona resistência e durabilidade. - Piscinas e Reservatórios: Mantém a impermeabilidade em áreas que contêm água. - Túneis e Galerias: Garante segurança e proteção contra infiltrações. Materiais Compatíveis: - Cimento: Pode ser utilizado com diferentes traços de cimento: - 1:2:8 (cimento:cal:areia) - 1:2:10 - 1:3 (cimento:areia) - 1:2.5 (cimento:areia) - Argamassa: Aditivado para aumentar a impermeabilidade sem comprometer a respirabilidade das paredes. Instruções de Uso: - Preparação da Base: A superfície deve estar limpa, livre de trincas e impurezas. - Dosagem: Adicione 1 litro de ImperSika® para cada 50 kg de cimento. - Aplicação: Utilize desempenadeira de madeira para aplicar camadas de 1 a 1,5 cm. Realize a cura úmida por no mínimo 72 horas após a aplicação.', 224.9, 224.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9k98bbkm2pl39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1501367141%2F22793972634', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
