INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8759469355', 'Cartucho HP 122 Original CH562HB Cores p/ DeskJet 1000, 2050, 3050, 2000', 'Imprima facilmente documentos, relatórios e cartas em cores vibrantes a um preço excelente. Os Cartuchos Originais HP foram projetados para desempenho consistente e de confiança. Detalhes: - Volume de páginas impressas: até 100 páginas - Impressões que funcionam todas as vezes. Cartuchos projetados para alto rendimento - Impressões resistentes à água e que não desbotam com o tempo - Tecnologia anti curvas, páginas mais planas e mais secas quando saem da sua impressora - Fotos e documentos que duram mais de 50 anos sem perder a cor e a qualidade - Resultados superiores da primeira à última página, sem obstruções ou impressões com bandas - Impressão sustentável, os cartuchos HP originais são feitos com até 50% de material reciclado. Compatibilidade - Impressora HP Deskjet 1000 J110a - Impressora HP Deskjet 2000 J210a - Impressora HP Deskjet 2050 multifuncional J510a - Multifuncional HP Deskjet 3050 J610a Garantia e Suporte: A Lepok é revendedora autorizada HP. A garantia deste produto é prestada diretamente pela HP, por meio dos canais oficiais da marca, conforme as políticas do fabricante.', 161.28, 149.0, NULL, 'Computers & Accessories > Printers & Scanners > Inks & Toners', 'https://cf.shopee.com.br/file/sg-11134201-823qx-moqvn5pdoyz3e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F8759469355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
