INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9259466697', 'Caneta Posca PC-5M Laranja uni-ball', 'A Caneta Posca PC-5M é um dos marcadores mais versáteis e populares da linha Posca, sendo a escolha ideal para artistas, ilustradores, artesãos, estudantes e criativos que buscam liberdade para criar com precisão e excelente cobertura. Com sua ponta média, ela oferece o equilíbrio perfeito entre preenchimentos amplos e detalhes precisos, tornando-se uma ferramenta indispensável para diversos tipos de projetos. Equipada com tinta pigmentada à base de água de alta tecnologia, a Posca PC-5M proporciona cores vibrantes, acabamento uniforme e cobertura próxima de 100% de opacidade. Sua fórmula exclusiva garante excelente aderência em diferentes materiais, além de ser atóxica e sem odor, oferecendo mais conforto e segurança durante o uso. A espessura de traço variável, de aproximadamente 2,5 mm a 6,8 mm, permite criar desde contornos definidos até áreas preenchidas com facilidade, atendendo tanto trabalhos artísticos quanto aplicações decorativas e personalizações. Reconhecida mundialmente pela qualidade e durabilidade de sua tinta, a Posca PC-5M é perfeita para quem deseja explorar a criatividade em múltiplas superfícies, com resultados profissionais e cores intensas. Destaques do produto: Caneta Posca PC-5M original Ponta média versátil para detalhes e preenchimentos Traço aproximado de 2,5 mm a 6,8 mm Tinta pigmentada à base de água Alta cobertura e excelente opacidade Cores intensas e duradouras Atóxica e sem cheiro Uso em múltiplas superfícies Ideal para arte, decoração, personalização e artesanato Aplicações: Desenhos e ilustrações Lettering e caligrafia artística Artesanato e DIY Personalização de objetos Pintura decorativa Scrapbook e papelaria criativa Customização de roupas, tênis e acessórios Projetos escolares e profissionais Superfícies compatíveis: Papel e cartões Madeira Cerâmica Vidro Plástico Porcelana Metais Tecidos Pedra Entre diversas outras superfícies A Posca PC-5M combina praticidade, desempenho e criatividade em um único marcador, sendo a opção perfeita para quem busca resultados profissionais em trabalhos artísticos, decorativos e de personalização.', 37.8, 31.38, NULL, 'Stationery > Writing & Correction > Markers', 'https://cf.shopee.com.br/file/sg-11134201-823pf-mp9hmb7c9ki329', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F9259466697', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
