INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209908371', 'Néctar de Abacaxi Del Valle', 'Refresque o seu dia com o Néctar de Abacaxi Del Valle, uma bebida saborosa e nutritiva. Elaborado com suco concentrado de abacaxi e maçã, e enriquecido com Vitamina C. Ideal para quem busca uma opção prática e deliciosa. Ingredientes: Água, açúcar, suco concentrado de abacaxi, suco concentrado de maçã, vitamina C, regulador de acidez ácido cítrico, aromatizante e estabilizante goma xantana. * 30,0% de suco. * Com suco de maçã.', 10.49, 10.49, NULL, 'Food & Beverages > Beverages > Juice & Juice Vinegar', 'https://cf.shopee.com.br/file/sg-11134201-8258x-mqnekhaz24uj5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703290582%2F58209908371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
