INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097979035', 'SANDALIA USAFLEX SALTO BLOCO PRATA VELHA', 'Sinta o conforto tão conhecido da Usaflex com a versatilidade e elegância dessa Sandália com salto bloco. Seu modelo de calce fácil é feito em couro com elástico, para máximo conforto, adaptando-se à ergonomia do pé. A Palmilha Everflex possui elementos que ajudam na sustentação do peso, além de auxiliar na absorção da umidade dos pés por um sistema de microbolhas. Além disso, ela é mais resistente que palmilhas comuns, mantendo cerca de 95% da espessura original, garantindo uma boa absorção de impactos e proteção a seus pés. O forro é feito em tecido resistente, macio e muito sedoso além de impedir a propagação de bactérias e fungos, evitando alergias e odores. Possui um solado resistente com boa aderência ao solo, com o salto bloco para um toque de sofisticação. Aproveite!', 192.98, 192.98, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Health Slippers', 'https://cf.shopee.com.br/file/br-11134201-820lf-mqy30p31w64k63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F476999948%2F23097979035', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
