INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45957357545', 'Kit Finalizadores Explosão de Azeite de Oliva + Umectação bn.Cachos', '✨ Kit Explosão de Azeite de Oliva – Finalizadores ✨ Dê adeus ao ressecamento e conquiste fios nutridos, macios e cheios de brilho! O Kit Explosão de Azeite de Oliva da bn.Cachos é ideal para cabelos ondulados, cacheados e crespos (2ABC a 4ABC), promovendo nutrição profunda, definição e controle do frizz. O kit contém: 1 Creme de Pentear 1kg 1 Ativador de Cachos 300ml 1 Óleo de Umectação 100ml 1 Mix Nutritivo de Óleos (Abacate + Oliva) 55ml Principais benefícios: ✔ Nutrição intensa com azeite de oliva ✔ Hidratação profunda e duradoura ✔ Definição dos cachos com efeito memória ✔ Ação anti-frizz e controle do volume ✔ Brilho extremo e toque macio ✔ Proteção contra o ressecamento Fórmula poderosa: Rico em azeite de oliva, conhecido por suas propriedades altamente nutritivas, que penetram profundamente na fibra capilar, ajudando a restaurar cabelos secos e sem vida. Modo de uso: Aplique o creme de pentear ou ativador nos cabelos úmidos; Distribua bem e finalize como desejar; Utilize o óleo de tratamento para umectação ou nutrição intensa; Finalize com o mix nutritivo para brilho extra e proteção; ✨ Resultado: Cabelos nutridos, definidos, com brilho intenso, maciez e sem frizz!', 136.06, 102.49, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82620-mlxtl3kx9vd487', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F45957357545', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
