INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094349262', 'Capa Piscina Redonda 4500 Litros Mor', 'Capa Piscina Redonda 4500 Litros Mor Mantenha sua piscina sempre limpa com a Capa Piscina Circular! Ela é perfeita para proteger contra insetos parasitas, água da chuva, folhas e sujeiras em geral, conservando a água da piscina própria para banho por muito mais tempo, ajudando assim o meio ambiente. Produzida em PVC, a Capa possui cordas em poliéster para serem fixadas na estrutura da Piscina Circular de 4.500 litros. Lembrando que, além da Capa, é indispensável fazer o tratamento químico recomendado para a capacidade de água da sua piscina de acordo com seu Manual! Descrição do produto Marca: Mor Material: PVC Cor: Azul Detalhes: Possui cordas em poliéster para serem fixadas na estrutura da Piscina Circular de 4.500 litros. Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 254.37, 150.73, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/sg-11134201-824g2-mdxybshmjchwba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F23094349262', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23692795965', 'Película para Xiaomi 13T Pro - Traseira de Fibra de Carbono - Gshield', 'Proteja a traseira com a película para Xiaomi 13T Pro A Película Traseira de Fibra de Carbono para Xiaomi 13T Pro, da GShield, protege seu aparelho contra riscos e arranhões na parte de trás. Para uma maior proteção, as películas traseiras podem ser usadas em conjunto com as capas da Gorila Shield, evitando o acúmulo de detritos no interior do acessório e eventuais arranhões no celular.', 21.97, 21.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rbm5-lopo09nu9lvi2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23692795965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
