INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11720372983', 'Caneta esferográfica 1.0 Trilux Azul/Preto/Vermelho SM/032\343218 com 3 unidades Faber-Castell', 'A Caneta Esferográfica Trilux SM/032 da Faber-Castell é ideal para quem busca conforto, praticidade e qualidade na escrita. O kit contém 3 canetas nas cores azul, preta e vermelha, perfeitas para estudos, trabalho, organização de tarefas e uso diário. Sua ponta média de 1,0 mm proporciona traços suaves e uniformes, garantindo uma escrita macia, sem falhas ou borrões. O tradicional formato triangular ergonômico da linha Trilux oferece maior conforto durante a escrita, proporcionando melhor encaixe dos dedos e reduzindo o cansaço mesmo após longos períodos de uso. Além disso, a tinta de alta qualidade garante excelente rendimento e durabilidade. Reconhecida pela sua confiabilidade e desempenho, a linha Trilux é uma das mais tradicionais da Faber-Castell, sendo amplamente utilizada por estudantes, profissionais e usuários que valorizam uma escrita confortável e eficiente. Principais Benefícios Kit com 3 canetas nas cores azul, preta e vermelha Ponta média de 1,0 mm Escrita macia e uniforme Traços sem falhas ou borrões Formato triangular ergonômico Maior conforto durante a escrita Excelente rendimento de tinta Tampa na cor da tinta para fácil identificação Ideal para escola, faculdade, escritório e uso diário Qualidade e tradição Faber-Castell Detalhes do Produto Marca: Faber-Castell Linha: Trilux Modelo: SM/032 Tipo: Caneta esferográfica Quantidade: 3 unidades Cores da tinta: Azul, Preta e Vermelha Espessura da ponta: 1,0 mm Formato do corpo: Triangular ergonômico Aplicação: Escrita, anotações, estudos, trabalho e organização A Caneta Esferográfica Trilux 1.0mm Faber-Castell oferece conforto, durabilidade e uma escrita suave para tornar as atividades do dia a dia muito mais práticas e eficientes. INMETRO 001849/2014', 18.64, 15.85, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-82580-mqypc3vyeuiqd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F479054821%2F11720372983', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
